-- the substrate joins the A-4 no-hard-delete set (same loop shape as v5.4.2-01)
DO $$
DECLARE
    t text;
    protected constant text[] := ARRAY[
        'rate_schedules', 'rate_schedule_versions', 'rate_schedule_items',
        'rate_items', 'rate_item_versions', 'rate_item_history', 'rate_item_history_archive',
        'franchise_fee_rules',
        'wna_zones', 'wna_zone_versions'
        -- wna_monthly_adjustments and customer_tax_exemptions are in the v5.4.2-01 array already
    ];
BEGIN
    FOREACH t IN ARRAY protected LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS no_hard_delete ON public.%I', t);
        EXECUTE format(
            'CREATE TRIGGER no_hard_delete BEFORE DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.enforce_no_hard_delete()', t);
        EXECUTE format('DROP TRIGGER IF EXISTS no_truncate ON public.%I', t);
        EXECUTE format(
            'CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete()', t);
        EXECUTE format('REVOKE DELETE ON public.%I FROM tally_app', t);
    END LOOP;
END;
$$;

-- ----------------------------------------------------------------------------
-- 7. Lookups — the enforcement layer (R-15)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.rate_schedule_as_of(p_rate_schedule_id uuid, p_valid_at date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.rate_schedule_versions
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'rate_schedule_as_of: p_valid_at and p_recorded_at are both required — pass the run''s (valid, recorded) coordinate pair; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT v.* FROM public.rate_schedule_versions v
    WHERE v.rate_schedule_id = p_rate_schedule_id
      AND v.recorded_at <= p_recorded_at AND (v.recorded_until IS NULL OR v.recorded_until > p_recorded_at)
      AND v.effective_date <= p_valid_at AND (v.expiry_date IS NULL OR v.expiry_date >= p_valid_at)
    ORDER BY v.recorded_at DESC, v.id
    LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.wna_zone_as_of(p_wna_zone_id uuid, p_valid_at date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.wna_zone_versions
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'wna_zone_as_of: p_valid_at and p_recorded_at are both required — pass the run''s (valid, recorded) coordinate pair; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT v.* FROM public.wna_zone_versions v
    WHERE v.wna_zone_id = p_wna_zone_id
      AND v.recorded_at <= p_recorded_at AND (v.recorded_until IS NULL OR v.recorded_until > p_recorded_at)
      AND v.effective_date <= p_valid_at AND (v.expiry_date IS NULL OR v.expiry_date >= p_valid_at)
    ORDER BY v.recorded_at DESC, v.id
    LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.rate_item_as_of(p_rate_item_id uuid, p_valid_at date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.rate_item_versions
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'rate_item_as_of: p_valid_at and p_recorded_at are both required — pass the run''s (valid, recorded) coordinate pair; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT v.* FROM public.rate_item_versions v
    WHERE v.rate_item_id = p_rate_item_id
      AND v.recorded_at <= p_recorded_at AND (v.recorded_until IS NULL OR v.recorded_until > p_recorded_at)
      AND v.effective_date <= p_valid_at AND (v.expiry_date IS NULL OR v.expiry_date >= p_valid_at)
    ORDER BY v.recorded_at DESC, v.id
    LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.rate_schedule_item_as_of(p_rate_schedule_id uuid, p_rate_item_id uuid, p_valid_at date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.rate_schedule_items
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'rate_schedule_item_as_of: p_valid_at and p_recorded_at are both required — pass the run''s (valid, recorded) coordinate pair; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT r.* FROM public.rate_schedule_items r
    WHERE r.rate_schedule_id = p_rate_schedule_id AND r.rate_item_id = p_rate_item_id
      AND r.recorded_at <= p_recorded_at AND (r.recorded_until IS NULL OR r.recorded_until > p_recorded_at)
      AND r.effective_date <= p_valid_at AND (r.expiry_date IS NULL OR r.expiry_date >= p_valid_at)
    ORDER BY r.recorded_at DESC, r.id
    LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.franchise_fee_as_of(p_tenant_id uuid, p_city_name text, p_valid_at date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.franchise_fee_rules
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'franchise_fee_as_of: p_valid_at and p_recorded_at are both required — pass the run''s (valid, recorded) coordinate pair; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT f.* FROM public.franchise_fee_rules f
    WHERE f.tenant_id = p_tenant_id AND f.city_name = p_city_name
      AND f.recorded_at <= p_recorded_at AND (f.recorded_until IS NULL OR f.recorded_until > p_recorded_at)
      AND f.effective_date <= p_valid_at AND (f.expiry_date IS NULL OR f.expiry_date >= p_valid_at)
    ORDER BY f.recorded_at DESC, f.id
    LIMIT 1;
END;
$$;

CREATE OR REPLACE FUNCTION public.customer_tax_exemption_as_of(p_customer_id uuid, p_valid_at date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.customer_tax_exemptions
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'customer_tax_exemption_as_of: p_valid_at and p_recorded_at are both required — pass the run''s (valid, recorded) coordinate pair; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT e.* FROM public.customer_tax_exemptions e
    WHERE e.customer_id = p_customer_id
      AND e.recorded_at IS NOT NULL
      AND e.recorded_at <= p_recorded_at AND (e.recorded_until IS NULL OR e.recorded_until > p_recorded_at)
      AND e.effective_start <= p_valid_at AND (e.effective_end IS NULL OR e.effective_end >= p_valid_at)
    ORDER BY e.recorded_at DESC, e.id;
END;
$$;

CREATE OR REPLACE FUNCTION public.wna_monthly_adjustment_as_of(p_wna_zone_id uuid, p_billing_month date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.wna_monthly_adjustments
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_billing_month IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'wna_monthly_adjustment_as_of: p_billing_month (the valid-time coordinate) and p_recorded_at are both required; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT w.* FROM public.wna_monthly_adjustments w
    WHERE w.wna_zone_id = p_wna_zone_id
      AND w.billing_month = date_trunc('month', p_billing_month)::date
      AND w.recorded_at IS NOT NULL
      AND w.recorded_at <= p_recorded_at AND (w.recorded_until IS NULL OR w.recorded_until > p_recorded_at)
    ORDER BY w.recorded_at DESC, w.id
    LIMIT 1;
END;
$$;

COMMENT ON FUNCTION public.rate_schedule_as_of(uuid, date, timestamp with time zone) IS
    'A-1 lookup (v5.4.2-03, R-15). The rate_schedule_versions row asserted at transaction time p_recorded_at whose valid bracket covers p_valid_at. Both coordinates REQUIRED; NULL raises; there is no now() default and no fallback to any live column. Zero rows = unknowable at that coordinate — the caller treats it as a hard error, never as "use the current version". Three call shapes, one contract: new bill (service period, now()); correction run — RRC default — (original period, now(), so a correction discovered since is picked up); reproduce/defend the original bill (original period, the original run''s recorded_at). Date policy belongs to the billing run, not here (R-16 keeps a GUC-defaulted layer addable over these).';
COMMENT ON FUNCTION public.wna_zone_as_of(uuid, date, timestamp with time zone) IS
    'A-1 lookup (v5.4.2-03, R-15): wna_zone_versions at (p_valid_at, p_recorded_at). Same contract as rate_schedule_as_of — both coordinates required, NULL raises, zero rows = unknowable.';
COMMENT ON FUNCTION public.rate_item_as_of(uuid, date, timestamp with time zone) IS
    'A-1 lookup (v5.4.2-03, R-15): rate_item_versions at (p_valid_at, p_recorded_at) — rate_value, rate_unit, tier_config, calculation_type, taxability, regulatory_class as asserted then. Replaces get_effective_rate''s current_rate read. Same contract as rate_schedule_as_of.';
COMMENT ON FUNCTION public.rate_schedule_item_as_of(uuid, uuid, date, timestamp with time zone) IS
    'A-1 lookup (v5.4.2-03, R-15): the schedule-level override row for (schedule, item) at (p_valid_at, p_recorded_at). COALESCE its *_override columns over rate_item_as_of() to get the effective rate — that composition is the billing engine''s, not this function''s. Same contract as rate_schedule_as_of.';
COMMENT ON FUNCTION public.franchise_fee_as_of(uuid, text, date, timestamp with time zone) IS
    'A-1 lookup (v5.4.2-03, R-15): the franchise_fee_rules row for (tenant, city) at (p_valid_at, p_recorded_at). Same contract as rate_schedule_as_of.';
COMMENT ON FUNCTION public.customer_tax_exemption_as_of(uuid, date, timestamp with time zone) IS
    'A-1 lookup (v5.4.2-03, R-15): every ASSERTED exemption row (recorded_at set — pending/rejected drafts never appear) for the customer whose transaction bracket covers p_recorded_at and whose valid bracket [effective_start, effective_end] covers p_valid_at. A revoked/expired successor row still covers the dates before its effective_end — that is the point. Service-type matching is the caller''s (should_charge_tax does it). Both coordinates required, NULL raises.';
COMMENT ON FUNCTION public.wna_monthly_adjustment_as_of(uuid, date, timestamp with time zone) IS
    'A-1 lookup (v5.4.2-03, R-15): the asserted (approved or later) wna_monthly_adjustments row for (zone, month) at transaction time p_recorded_at. Valid time is the billing month (p_billing_month is truncated to month). Pending drafts never appear. Both coordinates required, NULL raises, zero rows = unknowable.';

-- 7.1 should_charge_tax: transaction-time axis added; the CURRENT_DATE-defaulting signature dropped.
DROP FUNCTION IF EXISTS public.should_charge_tax(uuid, boolean, text, date);
CREATE OR REPLACE FUNCTION public.should_charge_tax(p_customer_id uuid, p_item_is_taxable boolean, p_service_type text, p_valid_at date, p_recorded_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_has_exemption boolean;
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'should_charge_tax: p_valid_at and p_recorded_at are both required — never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;

    -- Rule 1: item-level non-taxable wins
    IF p_item_is_taxable IS NULL OR p_item_is_taxable = false THEN
        RETURN false;
    END IF;

    -- Rule 2: a customer exemption asserted as of p_recorded_at, covering p_valid_at and the service type
    SELECT EXISTS (
        SELECT 1
        FROM public.customer_tax_exemption_as_of(p_customer_id, p_valid_at, p_recorded_at) cte
        WHERE (
              cte.service_types IS NULL
              OR array_length(cte.service_types, 1) IS NULL
              OR p_service_type IS NULL
              OR p_service_type = ANY(cte.service_types)
        )
    ) INTO v_has_exemption;

    IF v_has_exemption THEN
        RETURN false;
    END IF;

    -- Rule 3: taxable item, no exemption -> charge tax
    RETURN true;
END;
$$;

COMMENT ON FUNCTION public.should_charge_tax(uuid, boolean, text, date, timestamp with time zone) IS
    'Decides whether to tax a line item for a customer, at an explicit (valid, recorded) coordinate (re-issued v5.4.2-03, A-1 / R-15; the 4-argument form with p_as_of_date DEFAULT CURRENT_DATE was dropped — it filtered valid time only and defaulted to now()). Rules: (1) item non-taxable -> no tax; (2) an exemption asserted as of p_recorded_at whose bracket covers p_valid_at and matches the service type -> no tax; (3) otherwise tax. Both coordinates required, NULL raises. Correction runs pass the original period''s date; which recorded_at to pass (current knowledge vs the original run''s) is the run''s policy. No longer SECURITY DEFINER (the definer form read exemptions across tenants for any caller — RLS now applies); search_path pinned.';

-- 7.2 get_effective_rate: neutralised (LIMIT 1, no ORDER BY, no temporal predicate, read current_rate — which no longer exists).
CREATE OR REPLACE FUNCTION public.get_effective_rate(p_rate_schedule_id uuid, p_rate_item_id uuid, p_billing_month date DEFAULT CURRENT_DATE)
    RETURNS TABLE(effective_rate numeric, rate_unit text, is_active_this_month boolean, is_taxable boolean)
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    RAISE EXCEPTION USING
        MESSAGE = 'get_effective_rate() is deprecated and disabled (v5.4.2-03, A-1): it had no temporal predicate and returned an arbitrary row (LIMIT 1, no ORDER BY) from tables that are now multi-version. Compose rate_schedule_item_as_of(schedule, item, p_valid_at, p_recorded_at) over rate_item_as_of(item, p_valid_at, p_recorded_at) — COALESCE(rsi.rate_override, ri.rate_value), COALESCE(rsi.rate_unit_override, ri.rate_unit), COALESCE(rsi.is_taxable_override, ri.is_taxable_default), COALESCE(rsi.active_months_override, ri.active_months) — with an explicit coordinate pair.',
        ERRCODE = 'feature_not_supported';
END;
$$;
COMMENT ON FUNCTION public.get_effective_rate(uuid, uuid, date) IS
    'DISABLED by v5.4.2-03 (A-1): raises unconditionally with the replacement recipe. Kept so a caller fails loudly rather than resolving to nothing. The original filtered status = active only, ignored effective/expiry dates, did LIMIT 1 with no ORDER BY and read rate_items.current_rate (dropped). No longer SECURITY DEFINER; search_path pinned.';

-- 7.3 get_partial_period_policy: both axes (the 2-argument form read rate_schedules columns that moved).
DROP FUNCTION IF EXISTS public.get_partial_period_policy(uuid, timestamp with time zone);
CREATE OR REPLACE FUNCTION public.get_partial_period_policy(p_rate_schedule_id uuid, p_valid_at date, p_recorded_at timestamp with time zone)
    RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_override  text;
    v_tenant_id uuid;
    v_policy    text;
BEGIN
    IF p_valid_at IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'get_partial_period_policy: p_valid_at and p_recorded_at are both required — pass the run''s evaluation coordinates (CI-006)';
    END IF;

    SELECT v.partial_period_policy, v.tenant_id INTO v_override, v_tenant_id
    FROM public.rate_schedule_as_of(p_rate_schedule_id, p_valid_at, p_recorded_at) v;

    IF NOT FOUND THEN RETURN NULL; END IF;                       -- unknown schedule, or unknowable at that coordinate
    IF v_override IS NOT NULL THEN RETURN v_override; END IF;    -- per-schedule override wins

    SELECT h.new_value #>> '{}' INTO v_policy
    FROM public.tenant_configuration_history h
    WHERE h.tenant_id = v_tenant_id
      AND h.config_key = 'default_partial_period_policy'
      AND h.effective_from <= p_recorded_at                      -- that history is transaction time (D-2026-08-20-10)
    ORDER BY h.effective_from DESC, h.seq DESC
    LIMIT 1;

    RETURN v_policy;                                             -- NULL if the coordinate predates all history — no live fallback
END;
$$;

COMMENT ON FUNCTION public.get_partial_period_policy(uuid, date, timestamp with time zone) IS
    'Effective partial-period policy for a rate schedule at an explicit (valid, recorded) coordinate pair (re-issued v5.4.2-03 for A-1; the 2-argument v5.4.1-02 form was dropped — its rate_schedules read no longer exists and R-15 requires both axes everywhere). Both arguments REQUIRED; NULL RAISES — do not pass get_correction_rate_date()''s NULL through. Resolution: the schedule version at (p_valid_at, p_recorded_at) — its partial_period_policy override if set — else the tenant default recorded in tenant_configuration_history with the latest effective_from <= p_recorded_at (that bracket is transaction time). No fallback to the live tenants column: an unknown schedule, a coordinate no version covers, or a coordinate earlier than the tenant''s first recorded row returns NULL — a hard error to the engine, never "use the default".';

-- 7.4 get_correction_rate_date: the documented caller contract now names both axes; while touched, its
--     search_path is pinned (A-23 item; body unchanged, still v5.2.1 unqualified — safe under public, pg_temp).
ALTER FUNCTION public.get_correction_rate_date(uuid, uuid) SET search_path = public, pg_temp;
COMMENT ON FUNCTION public.get_correction_rate_date(p_billing_run_id uuid, p_voided_invoice_id uuid) IS
    'Returns the VALID-TIME coordinate (a date) for Phase 5 of a correction billing run — the original service period by default (CI-005), or the operator''s explicit election. Resolution: custom date > per-target historical/current > run-level default. Since v5.4.2-03 (A-1) the reference tables are bi-temporal, so this date alone does not identify a row: pass it as p_valid_at to the as-of family — rate_schedule_as_of, rate_item_as_of, rate_schedule_item_as_of, franchise_fee_as_of, wna_monthly_adjustment_as_of, customer_tax_exemption_as_of / should_charge_tax, get_partial_period_policy — together with ONE p_recorded_at chosen once per run (now() for "current knowledge", the original run''s instant to reproduce the original bill; CI-003). Never filter these tables with WHERE effective_date <= X alone — that matches every transaction-time version and a LIMIT 1 on top returns the latest correction, not what was known. Returns NULL if the target is not found: the engine must substitute and log — NULL passed to any as-of function RAISES.';

-- ----------------------------------------------------------------------------
-- 8. ENABLE ALWAYS on every guard this patch created (D-2026-08-20-27)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT c.relname, t.tgname
        FROM pg_trigger t
        JOIN pg_class c ON c.oid = t.tgrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public'
          AND NOT t.tgisinternal
          AND t.tgenabled <> 'A'
          AND t.tgname IN ('no_hard_delete', 'no_truncate',
                           'a_enforce_bitemporal_assertion', 'b_enforce_bitemporal_assertion',
                           'b_enforce_rate_schedule_version_rules', 'enforce_superseded_has_successor',
                           'enforce_reference_header', 'enforce_rate_schedule_lifecycle',
                           'a_enforce_tax_exemption_lifecycle', 'a_enforce_wna_adjustment_lifecycle',
                           'enforce_rate_schedule_assignable', 'retired_read_only', 'retired_no_truncate')
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I', r.relname, r.tgname);
    END LOOP;
END;
$$;
-- ============================================================================
-- MIRROR: PATCH v5.4.2-04 — A-3: invoice calculation snapshots, Option B (Phase 4 Wave 1; CI-015)
-- Appended 2026-08-28; source of truth: sql/v5.4.2-04-invoice-calculation-snapshots.sql
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 0. Report (never refuse): issued invoices that predate the snapshot store
-- ----------------------------------------------------------------------------
DO $$
DECLARE
    v_count bigint;
BEGIN
    IF to_regclass('public.invoice_calculation_snapshots') IS NULL THEN
        SELECT count(*) INTO v_count
        FROM public.invoices i
        WHERE public.is_invoice_issued(i.status);
        IF v_count > 0 THEN
            RAISE NOTICE 'v5.4.2-04: % invoice(s) were issued before the snapshot store existed; they have no calculation snapshot and cannot be given one (CI-015 applies from this patch forward)', v_count;
        END IF;
    END IF;
END;
$$;

-- ----------------------------------------------------------------------------
-- 1. invoices: tenant-bound identity for composite FKs (A-1 precedent)
-- ----------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'invoices_id_tenant_id_key' AND conrelid = 'public.invoices'::regclass) THEN
        ALTER TABLE public.invoices ADD CONSTRAINT invoices_id_tenant_id_key UNIQUE (id, tenant_id);
    END IF;
END;
$$;

-- ----------------------------------------------------------------------------
-- 2. invoice_calculation_snapshots
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.invoice_calculation_snapshots (
    id                      uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id               uuid NOT NULL,
    invoice_id              uuid NOT NULL,
    billing_run_id          uuid,
    valid_at                date NOT NULL,
    recorded_at             timestamp with time zone NOT NULL,
    snapshot_schema_version text NOT NULL,
    formula_version         text NOT NULL,
    rate_inputs             jsonb NOT NULL,
    gas_factors             jsonb NOT NULL,
    wna_inputs              jsonb NOT NULL,
    tax_inputs              jsonb NOT NULL,
    read_inputs             jsonb NOT NULL,
    customer_inputs         jsonb NOT NULL,
    period_inputs           jsonb NOT NULL,
    line_items              jsonb NOT NULL,
    content_hash            text GENERATED ALWAYS AS (
        encode(public.digest(
            snapshot_schema_version || '|' || formula_version || '|' || (valid_at - DATE '1970-01-01')::text || '|' || extract(epoch from (recorded_at AT TIME ZONE 'UTC'))::text || '|'
            || rate_inputs::text || '|' || gas_factors::text || '|' || wna_inputs::text || '|' || tax_inputs::text || '|'
            || read_inputs::text || '|' || customer_inputs::text || '|' || period_inputs::text || '|' || line_items::text,
            'sha256'), 'hex')
    ) STORED,
    captured_at             timestamp with time zone DEFAULT now() NOT NULL,
    captured_by             uuid,
    notes                   text,
    CONSTRAINT invoice_calculation_snapshots_pkey PRIMARY KEY (id),
    CONSTRAINT invoice_calculation_snapshots_invoice_id_key UNIQUE (invoice_id),
    CONSTRAINT invoice_calculation_snapshots_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT invoice_calculation_snapshots_invoice_fkey FOREIGN KEY (invoice_id, tenant_id) REFERENCES public.invoices(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT invoice_calculation_snapshots_billing_run_id_fkey FOREIGN KEY (billing_run_id) REFERENCES public.billing_runs(id),
    CONSTRAINT invoice_calculation_snapshots_captured_by_fkey FOREIGN KEY (captured_by) REFERENCES public.users(id),
    CONSTRAINT invoice_calculation_snapshots_schema_version_check CHECK (snapshot_schema_version ~ '^v[0-9]+$'),
    CONSTRAINT invoice_calculation_snapshots_formula_version_check CHECK (length(btrim(formula_version)) > 0),
    CONSTRAINT invoice_calculation_snapshots_rate_inputs_check CHECK (jsonb_typeof(rate_inputs) = 'object'),
    CONSTRAINT invoice_calculation_snapshots_gas_factors_check CHECK (jsonb_typeof(gas_factors) = 'object'),
    CONSTRAINT invoice_calculation_snapshots_wna_inputs_check CHECK (jsonb_typeof(wna_inputs) = 'object'),
    CONSTRAINT invoice_calculation_snapshots_tax_inputs_check CHECK (jsonb_typeof(tax_inputs) = 'object'),
    CONSTRAINT invoice_calculation_snapshots_read_inputs_check CHECK (jsonb_typeof(read_inputs) = 'object'),
    CONSTRAINT invoice_calculation_snapshots_customer_inputs_check CHECK (jsonb_typeof(customer_inputs) = 'object'),
    CONSTRAINT invoice_calculation_snapshots_period_inputs_check CHECK (jsonb_typeof(period_inputs) = 'object'),
    CONSTRAINT invoice_calculation_snapshots_line_items_check CHECK (jsonb_typeof(line_items) = 'array')
);

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'invoice_calculation_snapshots_invoice_fkey' AND conrelid = 'public.invoice_calculation_snapshots'::regclass AND confdeltype <> 'c') THEN
        ALTER TABLE public.invoice_calculation_snapshots DROP CONSTRAINT invoice_calculation_snapshots_invoice_fkey;
        ALTER TABLE public.invoice_calculation_snapshots ADD CONSTRAINT invoice_calculation_snapshots_invoice_fkey FOREIGN KEY (invoice_id, tenant_id) REFERENCES public.invoices(id, tenant_id) ON DELETE CASCADE;
    END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_invoice_calculation_snapshots_tenant ON public.invoice_calculation_snapshots USING btree (tenant_id);
CREATE INDEX IF NOT EXISTS idx_invoice_calculation_snapshots_billing_run ON public.invoice_calculation_snapshots USING btree (billing_run_id) WHERE (billing_run_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_invoice_calculation_snapshots_content_hash ON public.invoice_calculation_snapshots USING btree (content_hash);

ALTER TABLE public.invoice_calculation_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_calculation_snapshots FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.invoice_calculation_snapshots;
CREATE POLICY tenant_isolation ON public.invoice_calculation_snapshots USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));

REVOKE UPDATE ON public.invoice_calculation_snapshots FROM tally_app;

COMMENT ON TABLE public.invoice_calculation_snapshots IS
    'CI-015 (v5.4.2-04, A-3, Option B). The complete, frozen input set of one invoice''s calculation: the run''s temporal coordinate pair (valid_at, recorded_at — the ONE pair AC-15 resolves per run), the snapshot schema version (key contract enforced by validate_calculation_snapshot()), the formula version replay will need, and eight sections mirroring CI-015''s input list. Exactly one per invoice; required at commit of any issuance (enforce_invoice_has_snapshot on invoices); INSERT/DELETE only while the invoice is draft/held; never UPDATE. Replay reads this row and the formula it names — not the bi-temporal reference layer. Provenance to the reference rows read lives in invoice_snapshot_references.';
COMMENT ON COLUMN public.invoice_calculation_snapshots.valid_at IS 'Valid-time coordinate the run passed to every *_as_of lookup (AC-15). A regular bill: the service period date the engine chose; a correction: the original period (CI-005) or the operator''s election (get_correction_rate_date).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.recorded_at IS 'Transaction-time coordinate the run passed to every *_as_of lookup (AC-15): now() at calculation for current knowledge, or the original run''s instant when reproducing a bill. Must not be in the future.';
COMMENT ON COLUMN public.invoice_calculation_snapshots.snapshot_schema_version IS 'Key contract of the eight sections. Accepted versions are enumerated in validate_calculation_snapshot(); a new shape is a patch that teaches the validator. v1 = CI-015''s list as of 2026-08-28.';
COMMENT ON COLUMN public.invoice_calculation_snapshots.formula_version IS 'Identifier of the calculation formula/engine build that produced the bill. Replay = this snapshot + this formula version, nothing else (CI-015).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.rate_inputs IS 'v1 keys: rate_schedule_id, rate_schedule_version_id, rate_schedule_code, customer_type, partial_period_policy, items[] (each: rate_item_id, rate_item_version_id, item_code, rate_value, rate_unit, tier, applicability, rate_schedule_item_id).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.gas_factors IS 'v1 keys: pga_factor, btu_factor, pressure_factor, temperature_factor, meter_multiplier, factor_stack_intermediates (object). Null values allowed for non-gas invoices.';
COMMENT ON COLUMN public.invoice_calculation_snapshots.wna_inputs IS 'v1 keys: applied (boolean); when true also wna_zone_id, wna_zone_version_id, wna_monthly_adjustment_id, weather_station, normal_hdd, actual_hdd, deadband, base_load, heating_factor. CI-042: the NHDD baseline is not preserved by the reference layer — this section is the only replay substrate for WNA.';
COMMENT ON COLUMN public.invoice_calculation_snapshots.tax_inputs IS 'v1 keys: jurisdictions[] (each: jurisdiction_id, authority, rate, taxable_base), exemptions[] (each: customer_tax_exemption_id, exemption_type), franchise_fees[] (each: franchise_fee_rule_id, rate, base). Supersedes invoices.tax_breakdown as the input record (tax_breakdown remains the display record).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.read_inputs IS 'v1 keys: reads[] (each: meter_id, meter_reading_id, read_date, raw_consumption, is_estimated, intermediate_values (object: every factor-stack step)).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.customer_inputs IS 'v1 keys: customer_id, customer_class, location_id, premise_zones (object: zone kind -> zone id).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.period_inputs IS 'v1 keys: period_start, period_end, days_in_period, proration_policy. period_start/period_end must equal the invoice''s (checked at insert and at issuance).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.line_items IS 'v1: array of {invoice_line_item_id, charge_type, amount, …}. Must cite exactly the invoice''s invoice_line_items rows with matching amounts (checked at insert and again at issuance — a line edited after the snapshot invalidates it; delete and re-snapshot).';
COMMENT ON COLUMN public.invoice_calculation_snapshots.content_hash IS 'GENERATED sha256 (hex, pgcrypto digest) over versions + coordinate + all eight sections (jsonb canonical text). INV-099''s content-addressable framing; not caller-writable.';
COMMENT ON COLUMN public.invoice_calculation_snapshots.captured_at IS 'Forced to now() by trigger (the database''s clock, not the caller''s).';

-- ----------------------------------------------------------------------------
-- 3. Schema validator + invoice cross-checks (BEFORE INSERT)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.calculation_snapshot_line_items_match(p_invoice_id uuid, p_line_items jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$
    -- True when the snapshot's line_items array cites exactly the invoice's
    -- invoice_line_items rows (same id set, same amounts, no duplicates).
    WITH snap AS (
        SELECT (e ->> 'invoice_line_item_id')::uuid AS id,
               CASE WHEN jsonb_typeof(e -> 'amount') = 'number' THEN (e ->> 'amount')::numeric END AS amount
        FROM jsonb_array_elements(p_line_items) e
    ),
    live AS (
        SELECT l.id, l.amount FROM public.invoice_line_items l WHERE l.invoice_id = p_invoice_id
    )
    SELECT (SELECT count(*) FROM snap) = (SELECT count(DISTINCT id) FROM snap)
       AND NOT EXISTS (SELECT 1 FROM snap s WHERE s.id IS NULL OR s.amount IS NULL)
       AND NOT EXISTS (SELECT s.id, s.amount FROM snap s EXCEPT SELECT l.id, l.amount FROM live l)
       AND NOT EXISTS (SELECT l.id, l.amount FROM live l EXCEPT SELECT s.id, s.amount FROM snap s);
$$;

COMMENT ON FUNCTION public.calculation_snapshot_line_items_match(uuid, jsonb) IS
    'CI-015 helper (v5.4.2-04): does this line_items array cite exactly the invoice''s invoice_line_items (id set and amounts equal, no duplicate or null citations)? Used at snapshot insert and at issuance. Invoker rights: RLS applies.';

CREATE OR REPLACE FUNCTION public.validate_calculation_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_inv       public.invoices%ROWTYPE;
    v_missing   text[];
    v_required  jsonb;
    v_section   text;
    v_key       text;
    v_elem      jsonb;
    v_idx       integer;
BEGIN
    -- FOR SHARE: blocks behind a concurrent status flip on the same invoice so
    -- the status read here is the committed one (Fable CRITICAL-2 race).
    SELECT * INTO v_inv FROM public.invoices i WHERE i.id = NEW.invoice_id FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot rejected: invoice %s not found (or not visible to this tenant)', NEW.invoice_id),
            ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_inv.tenant_id <> NEW.tenant_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'snapshot rejected: tenant_id must equal the invoice''s tenant',
            ERRCODE = 'check_violation';
    END IF;
    IF public.is_invoice_issued(v_inv.status) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot rejected: invoice %s is already issued (status %s); a snapshot written after issuance is a reconstruction, not the record (CI-015)', v_inv.invoice_number, v_inv.status),
            ERRCODE = 'check_violation';
    END IF;
    IF NEW.billing_run_id IS DISTINCT FROM v_inv.billing_run_id THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot rejected: billing_run_id %s does not match the invoice''s %s', NEW.billing_run_id, v_inv.billing_run_id),
            ERRCODE = 'check_violation';
    END IF;
    IF NEW.recorded_at > now() THEN
        RAISE EXCEPTION USING
            MESSAGE = 'snapshot rejected: recorded_at may not lie in the future (it is the transaction-time coordinate the run used, AC-15)',
            ERRCODE = 'check_violation';
    END IF;
    -- Server clock, never the caller's.
    NEW.captured_at := now();

    -- Key contract per schema version.
    CASE NEW.snapshot_schema_version
        WHEN 'v1' THEN
            v_required := jsonb_build_object(
                'rate_inputs',     jsonb_build_array('rate_schedule_id', 'rate_schedule_version_id', 'rate_schedule_code', 'customer_type', 'partial_period_policy', 'items'),
                'gas_factors',     jsonb_build_array('pga_factor', 'btu_factor', 'pressure_factor', 'temperature_factor', 'meter_multiplier', 'factor_stack_intermediates'),
                'wna_inputs',      jsonb_build_array('applied'),
                'tax_inputs',      jsonb_build_array('jurisdictions', 'exemptions', 'franchise_fees'),
                'read_inputs',     jsonb_build_array('reads'),
                'customer_inputs', jsonb_build_array('customer_id', 'customer_class', 'location_id', 'premise_zones'),
                'period_inputs',   jsonb_build_array('period_start', 'period_end', 'days_in_period', 'proration_policy')
            );
        ELSE
            RAISE EXCEPTION USING
                MESSAGE = format('snapshot rejected: unknown snapshot_schema_version %L — validate_calculation_snapshot() accepts: v1', NEW.snapshot_schema_version),
                ERRCODE = 'check_violation';
    END CASE;

    v_missing := ARRAY[]::text[];
    FOR v_section, v_elem IN SELECT key, value FROM jsonb_each(v_required) LOOP
        FOR v_key IN SELECT jsonb_array_elements_text(v_elem) LOOP
            IF NOT (to_jsonb(NEW) -> v_section) ? v_key THEN
                v_missing := array_append(v_missing, ((v_section || '.' || v_key))::text);
            END IF;
        END LOOP;
    END LOOP;

    -- v1 shape rules beyond key presence.
    IF NEW.snapshot_schema_version = 'v1' THEN
        IF jsonb_typeof(NEW.rate_inputs -> 'items') IS DISTINCT FROM 'array' THEN v_missing := array_append(v_missing, ('rate_inputs.items (array)')::text); END IF;
        IF jsonb_typeof(NEW.gas_factors -> 'factor_stack_intermediates') IS DISTINCT FROM 'object' THEN v_missing := array_append(v_missing, ('gas_factors.factor_stack_intermediates (object)')::text); END IF;
        IF jsonb_typeof(NEW.wna_inputs -> 'applied') IS DISTINCT FROM 'boolean' THEN
            v_missing := array_append(v_missing, ('wna_inputs.applied (boolean)')::text);
        ELSIF (NEW.wna_inputs ->> 'applied')::boolean THEN
            FOR v_key IN SELECT unnest(ARRAY['wna_zone_id', 'wna_zone_version_id', 'wna_monthly_adjustment_id', 'weather_station', 'normal_hdd', 'actual_hdd', 'deadband', 'base_load', 'heating_factor']) LOOP
                IF NOT (NEW.wna_inputs ? v_key) OR jsonb_typeof(NEW.wna_inputs -> v_key) = 'null' THEN
                    v_missing := array_append(v_missing, (('wna_inputs.' || v_key || ' (required when applied)'))::text);
                END IF;
            END LOOP;
        END IF;
        FOR v_key IN SELECT unnest(ARRAY['jurisdictions', 'exemptions', 'franchise_fees']) LOOP
            IF jsonb_typeof(NEW.tax_inputs -> v_key) IS DISTINCT FROM 'array' THEN v_missing := array_append(v_missing, (('tax_inputs.' || v_key || ' (array)'))::text); END IF;
        END LOOP;
        IF jsonb_typeof(NEW.read_inputs -> 'reads') IS DISTINCT FROM 'array' THEN
            v_missing := array_append(v_missing, ('read_inputs.reads (array)')::text);
        ELSE
            v_idx := 0;
            FOR v_elem IN SELECT jsonb_array_elements(NEW.read_inputs -> 'reads') LOOP
                FOR v_key IN SELECT unnest(ARRAY['meter_id', 'meter_reading_id', 'read_date', 'raw_consumption', 'is_estimated', 'intermediate_values']) LOOP
                    IF NOT (v_elem ? v_key) THEN v_missing := array_append(v_missing, (format('read_inputs.reads[%s].%s', v_idx, v_key))::text); END IF;
                END LOOP;
                v_idx := v_idx + 1;
            END LOOP;
        END IF;
        IF jsonb_typeof(NEW.customer_inputs -> 'premise_zones') IS DISTINCT FROM 'object' THEN v_missing := array_append(v_missing, ('customer_inputs.premise_zones (object)')::text); END IF;
        v_idx := 0;
        FOR v_elem IN SELECT jsonb_array_elements(NEW.rate_inputs -> 'items') LOOP
            FOR v_key IN SELECT unnest(ARRAY['rate_item_id', 'rate_item_version_id', 'item_code', 'rate_value', 'rate_unit', 'applicability']) LOOP
                IF NOT (v_elem ? v_key) THEN v_missing := array_append(v_missing, (format('rate_inputs.items[%s].%s', v_idx, v_key))::text); END IF;
            END LOOP;
            v_idx := v_idx + 1;
        END LOOP;
        v_idx := 0;
        FOR v_elem IN SELECT jsonb_array_elements(NEW.line_items) LOOP
            FOR v_key IN SELECT unnest(ARRAY['invoice_line_item_id', 'charge_type', 'amount']) LOOP
                IF NOT (v_elem ? v_key) THEN v_missing := array_append(v_missing, (format('line_items[%s].%s', v_idx, v_key))::text); END IF;
            END LOOP;
            v_idx := v_idx + 1;
        END LOOP;
    END IF;

    IF cardinality(v_missing) > 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot rejected: schema %s requires %s (CI-015 — every input, or an explicit null for a group that does not apply)', NEW.snapshot_schema_version, array_to_string(v_missing, ', ')),
            ERRCODE = 'check_violation';
    END IF;

    -- Cross-checks against the invoice.
    IF (NEW.period_inputs ->> 'period_start')::date IS DISTINCT FROM v_inv.period_start
       OR (NEW.period_inputs ->> 'period_end')::date IS DISTINCT FROM v_inv.period_end THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot rejected: period_inputs (%s .. %s) do not match invoice %s (%s .. %s)', NEW.period_inputs ->> 'period_start', NEW.period_inputs ->> 'period_end', v_inv.invoice_number, v_inv.period_start, v_inv.period_end),
            ERRCODE = 'check_violation';
    END IF;
    IF (NEW.customer_inputs ->> 'customer_id')::uuid IS DISTINCT FROM v_inv.customer_id THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot rejected: customer_inputs.customer_id does not match invoice %s', v_inv.invoice_number),
            ERRCODE = 'check_violation';
    END IF;
    IF NOT public.calculation_snapshot_line_items_match(NEW.invoice_id, NEW.line_items) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot rejected: line_items must cite exactly invoice %s''s invoice_line_items rows (same ids, same amounts) — write the lines first, then the snapshot', v_inv.invoice_number),
            ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.validate_calculation_snapshot() IS
    'CI-015 gate on invoice_calculation_snapshots INSERT (v5.4.2-04): parent must exist in the same tenant and be draft/held; billing_run_id equals the invoice''s; recorded_at not in the future; captured_at forced to now(); snapshot_schema_version must be one the function enumerates (v1) and every section must carry that version''s required keys (nested shapes for items/reads/line_items); period and customer match the invoice; line_items cites exactly the invoice''s lines.';

DROP TRIGGER IF EXISTS a_validate_calculation_snapshot ON public.invoice_calculation_snapshots;
CREATE TRIGGER a_validate_calculation_snapshot BEFORE INSERT ON public.invoice_calculation_snapshots
    FOR EACH ROW EXECUTE FUNCTION public.validate_calculation_snapshot();

-- ----------------------------------------------------------------------------
-- 4. Immutability (UPDATE never; DELETE only while the invoice is draft/held)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_calculation_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_status text;
    v_number text;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION USING
            MESSAGE = format('%s is immutable (CI-015): a frozen input set is never edited — while the invoice is draft/held, DELETE and re-insert', TG_TABLE_NAME),
            ERRCODE = 'check_violation';
    END IF;
    -- DELETE: only while the parent invoice is not issued. A missing parent
    -- is only reachable through the cascade of a draft-invoice delete (the
    -- FK cascades; A-4 forbids deleting an issued invoice, so the cascade
    -- can only ever remove a draft's snapshot — the invoice_line_items rule).
    SELECT i.status, i.invoice_number INTO v_status, v_number
    FROM public.invoices i WHERE i.id = OLD.invoice_id FOR SHARE;
    IF FOUND AND public.is_invoice_issued(v_status) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s is issued (status %s): its calculation snapshot is immutable (CI-015) — DELETE rejected', v_number, v_status),
            ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
END;
$$;

COMMENT ON FUNCTION public.enforce_calculation_snapshot_immutable() IS
    'CI-015 guard (v5.4.2-04) for invoice_calculation_snapshots: UPDATE always rejected; DELETE rejected once the parent invoice is issued (is_invoice_issued). Draft/held parents may be re-snapshotted by delete + insert.';

DROP TRIGGER IF EXISTS enforce_calculation_snapshot_immutable ON public.invoice_calculation_snapshots;
CREATE TRIGGER enforce_calculation_snapshot_immutable BEFORE UPDATE OR DELETE ON public.invoice_calculation_snapshots
    FOR EACH ROW EXECUTE FUNCTION public.enforce_calculation_snapshot_immutable();
DROP TRIGGER IF EXISTS no_truncate ON public.invoice_calculation_snapshots;
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.invoice_calculation_snapshots
    FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete();

-- ----------------------------------------------------------------------------
-- 5. Completeness at issuance (DEFERRABLE, on invoices)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_invoice_has_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_snap public.invoice_calculation_snapshots%ROWTYPE;
BEGIN
    -- Only the transition INTO an issued status is gated. An already-issued
    -- invoice keeps living (collections, void) and its snapshot is frozen.
    IF NOT public.is_invoice_issued(NEW.status) THEN
        RETURN NULL;
    END IF;
    IF TG_OP = 'UPDATE' AND public.is_invoice_issued(OLD.status) THEN
        RETURN NULL;
    END IF;
    -- Voiding a never-issued (draft/held) invoice is a discard, not an
    -- issuance: nobody was billed, there is nothing to replay (Fable HIGH-1;
    -- void_invoice() lists held as voidable).
    IF TG_OP = 'UPDATE' AND NEW.status = 'void' THEN
        RETURN NULL;
    END IF;
    -- No lock on the snapshot row here: the snapshot/reference guards take
    -- the invoice FOR SHARE, so a concurrent delete/insert waits behind this
    -- transaction's row lock and re-reads the committed (issued) status.
    -- Locking here would deadlock against a waiting delete (and FOR UPDATE
    -- needs the UPDATE privilege tally_app deliberately lacks).
    SELECT * INTO v_snap FROM public.invoice_calculation_snapshots s WHERE s.invoice_id = NEW.id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s cannot be issued (status %s) without a calculation snapshot (CI-015): insert invoice_calculation_snapshots in the same transaction, after the line items', NEW.invoice_number, NEW.status),
            ERRCODE = 'check_violation';
    END IF;
    IF (v_snap.period_inputs ->> 'period_start')::date IS DISTINCT FROM NEW.period_start
       OR (v_snap.period_inputs ->> 'period_end')::date IS DISTINCT FROM NEW.period_end
       OR v_snap.billing_run_id IS DISTINCT FROM NEW.billing_run_id
       OR (v_snap.customer_inputs ->> 'customer_id')::uuid IS DISTINCT FROM NEW.customer_id THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s cannot be issued: its calculation snapshot no longer matches the invoice (period, billing run or customer changed after the snapshot) — delete and re-snapshot (CI-015)', NEW.invoice_number),
            ERRCODE = 'check_violation';
    END IF;
    -- The lines ARE locked: A-4's line guard reads the invoice without a
    -- lock, so a concurrent line edit would otherwise be invisible here
    -- (Fable CRITICAL-2 variant B).
    PERFORM 1 FROM public.invoice_line_items l WHERE l.invoice_id = NEW.id FOR SHARE;
    IF NOT public.calculation_snapshot_line_items_match(NEW.id, v_snap.line_items) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s cannot be issued: its line items changed after the calculation snapshot was taken — delete and re-snapshot (CI-015)', NEW.invoice_number),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NULL;
END;
$$;

COMMENT ON FUNCTION public.enforce_invoice_has_snapshot() IS
    'CI-015 completeness (v5.4.2-04): at commit of any transaction that moves an invoice into an issued status (is_invoice_issued; INSERT included), exactly one invoice_calculation_snapshots row must exist for it and still agree with the invoice (period, billing run, customer, line id set + amounts). Voiding a draft/held invoice (a discard) is exempt. DEFERRABLE INITIALLY DEFERRED so the check runs at commit; the write order is invoice → lines → snapshot → status flip (the snapshot validator refuses an already-issued parent). Locks the lines (FOR SHARE) so a concurrent line edit is waited for and seen; a concurrent snapshot delete/insert waits on the invoice row lock inside its own guard and is then rejected.';

DROP TRIGGER IF EXISTS enforce_invoice_has_snapshot ON public.invoices;
CREATE CONSTRAINT TRIGGER enforce_invoice_has_snapshot
    AFTER INSERT OR UPDATE ON public.invoices
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION public.enforce_invoice_has_snapshot();

-- ----------------------------------------------------------------------------
-- 6. invoice_snapshot_references — provenance into the A-1 layer
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.invoice_snapshot_references (
    id              uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id       uuid NOT NULL,
    snapshot_id     uuid NOT NULL,
    source_table    text NOT NULL,
    source_row_id   uuid NOT NULL,
    role            text,
    CONSTRAINT invoice_snapshot_references_pkey PRIMARY KEY (id),
    CONSTRAINT invoice_snapshot_references_unique UNIQUE (snapshot_id, source_table, source_row_id),
    CONSTRAINT invoice_snapshot_references_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT invoice_snapshot_references_snapshot_fkey FOREIGN KEY (snapshot_id) REFERENCES public.invoice_calculation_snapshots(id) ON DELETE CASCADE,
    CONSTRAINT invoice_snapshot_references_source_table_check CHECK (source_table = ANY (ARRAY[
        'rate_schedule_versions'::text, 'wna_zone_versions'::text, 'rate_item_versions'::text,
        'rate_schedule_items'::text, 'franchise_fee_rules'::text, 'customer_tax_exemptions'::text, 'wna_monthly_adjustments'::text]))
);

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'invoice_snapshot_references_snapshot_fkey' AND conrelid = 'public.invoice_snapshot_references'::regclass AND confdeltype <> 'c') THEN
        ALTER TABLE public.invoice_snapshot_references DROP CONSTRAINT invoice_snapshot_references_snapshot_fkey;
        ALTER TABLE public.invoice_snapshot_references ADD CONSTRAINT invoice_snapshot_references_snapshot_fkey FOREIGN KEY (snapshot_id) REFERENCES public.invoice_calculation_snapshots(id) ON DELETE CASCADE;
    END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_invoice_snapshot_references_tenant ON public.invoice_snapshot_references USING btree (tenant_id);
CREATE INDEX IF NOT EXISTS idx_invoice_snapshot_references_source ON public.invoice_snapshot_references USING btree (source_table, source_row_id);

ALTER TABLE public.invoice_snapshot_references ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_snapshot_references FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.invoice_snapshot_references;
CREATE POLICY tenant_isolation ON public.invoice_snapshot_references USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));

REVOKE UPDATE ON public.invoice_snapshot_references FROM tally_app;

COMMENT ON TABLE public.invoice_snapshot_references IS
    'Provenance for a calculation snapshot (v5.4.2-04, A-3 → A-1): each row cites one bi-temporal row the calculation read (source_table ∈ the seven A-1 tables). The guard proves the citation was visible at the snapshot''s recorded_at (open on the transaction-time axis at that instant, same tenant). "Which rows did this bill use, and were they really what we knew then?" is answerable from this table; the values themselves are in the snapshot sections. Optional per snapshot; same immutability as the snapshot.';
COMMENT ON COLUMN public.invoice_snapshot_references.role IS 'Free-text tag of what the citation supplied (e.g. ''commodity_rate'', ''wna_factor'', ''tax_exemption''). Not enumerated: the calculation code names its own roles.';

CREATE OR REPLACE FUNCTION public.validate_snapshot_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_snap    public.invoice_calculation_snapshots%ROWTYPE;
    v_status  text;
    v_visible boolean;
BEGIN
    SELECT * INTO v_snap FROM public.invoice_calculation_snapshots s WHERE s.id = NEW.snapshot_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot reference rejected: snapshot %s not found (or not visible to this tenant)', NEW.snapshot_id),
            ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_snap.tenant_id <> NEW.tenant_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'snapshot reference rejected: tenant_id must equal the snapshot''s tenant',
            ERRCODE = 'check_violation';
    END IF;
    SELECT i.status INTO v_status FROM public.invoices i WHERE i.id = v_snap.invoice_id FOR SHARE;
    IF FOUND AND public.is_invoice_issued(v_status) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'snapshot reference rejected: the invoice is issued and its snapshot is frozen (CI-015)',
            ERRCODE = 'check_violation';
    END IF;
    -- The cited row must have been OPEN on the transaction-time axis at the
    -- snapshot's recorded_at, in the same tenant (every A-1 table carries
    -- recorded_at / recorded_until). The table name is re-checked here
    -- because this BEFORE trigger runs before the CHECK constraint would.
    IF NEW.source_table <> ALL (ARRAY['rate_schedule_versions', 'wna_zone_versions', 'rate_item_versions',
                                      'rate_schedule_items', 'franchise_fee_rules', 'customer_tax_exemptions', 'wna_monthly_adjustments']) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot reference rejected: %L is not one of the seven bi-temporal reference tables (invoice_snapshot_references_source_table_check)', NEW.source_table),
            ERRCODE = 'check_violation';
    END IF;
    EXECUTE format(
        'SELECT EXISTS (SELECT 1 FROM public.%I r WHERE r.id = $1 AND r.tenant_id = $2 AND r.recorded_at IS NOT NULL AND r.recorded_at <= $3 AND (r.recorded_until IS NULL OR r.recorded_until > $3))',
        NEW.source_table)
    INTO v_visible
    USING NEW.source_row_id, NEW.tenant_id, v_snap.recorded_at;
    IF NOT v_visible THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot reference rejected: %s row %s was not an open assertion at recorded_at %s in this tenant — the run could not have read it at that coordinate (AC-15 / CI-003)', NEW.source_table, NEW.source_row_id, v_snap.recorded_at),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.validate_snapshot_reference() IS
    'Provenance guard (v5.4.2-04): a cited reference row must exist in source_table, in the snapshot''s tenant, and be open on the transaction-time axis at the snapshot''s recorded_at; the parent invoice must still be draft/held.';

DROP TRIGGER IF EXISTS a_validate_snapshot_reference ON public.invoice_snapshot_references;
CREATE TRIGGER a_validate_snapshot_reference BEFORE INSERT ON public.invoice_snapshot_references
    FOR EACH ROW EXECUTE FUNCTION public.validate_snapshot_reference();

CREATE OR REPLACE FUNCTION public.enforce_snapshot_reference_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_status text;
    v_number text;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION USING
            MESSAGE = 'invoice_snapshot_references is immutable (CI-015): citations are never edited — while the invoice is draft/held, DELETE and re-insert',
            ERRCODE = 'check_violation';
    END IF;
    SELECT i.status, i.invoice_number INTO v_status, v_number
    FROM public.invoice_calculation_snapshots s
    JOIN public.invoices i ON i.id = s.invoice_id
    WHERE s.id = OLD.snapshot_id
    FOR SHARE OF i;
    IF FOUND AND public.is_invoice_issued(v_status) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s is issued (status %s): its snapshot provenance is immutable (CI-015) — DELETE rejected', v_number, v_status),
            ERRCODE = 'check_violation';
    END IF;
    RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS enforce_snapshot_reference_immutable ON public.invoice_snapshot_references;
CREATE TRIGGER enforce_snapshot_reference_immutable BEFORE UPDATE OR DELETE ON public.invoice_snapshot_references
    FOR EACH ROW EXECUTE FUNCTION public.enforce_snapshot_reference_immutable();
DROP TRIGGER IF EXISTS no_truncate ON public.invoice_snapshot_references;
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.invoice_snapshot_references
    FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete();

-- ----------------------------------------------------------------------------
-- 7. ENABLE ALWAYS on every guard this patch created (D-2026-08-20-27)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT c.relname, t.tgname
        FROM pg_trigger t
        JOIN pg_class c ON c.oid = t.tgrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public'
          AND NOT t.tgisinternal
          AND t.tgenabled <> 'A'
          AND (
                (c.relname IN ('invoice_calculation_snapshots', 'invoice_snapshot_references')
                 AND t.tgname IN ('no_truncate', 'a_validate_calculation_snapshot', 'enforce_calculation_snapshot_immutable',
                                  'a_validate_snapshot_reference', 'enforce_snapshot_reference_immutable'))
             OR (c.relname = 'invoices' AND t.tgname = 'enforce_invoice_has_snapshot')
          )
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I', r.relname, r.tgname);
    END LOOP;
END;
$$;

-- ----------------------------------------------------------------------------
-- 8. Cross-references on existing objects
-- ----------------------------------------------------------------------------
COMMENT ON COLUMN public.invoices.tax_breakdown IS
    'Itemized taxes by jurisdiction for regulatory-compliant display. JSONB array of {jurisdiction, authority, rate_item_id, amount}. Display record only: since v5.4.2-04 the tax INPUTS (rates, bases, exemptions, franchise rules) are frozen in invoice_calculation_snapshots.tax_inputs (CI-015).';
-- ============================================================================
-- MIRROR: PATCH v5.4.2-05 — A-20: read/bill exception queue and validation-state substrate (Phase 4 Wave 2; CI-112/113/115/023)
-- Appended 2026-08-28; source of truth: sql/v5.4.2-05-read-and-bill-exception-substrate.sql
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Tenant-bound identity for composite FKs
-- ----------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'meters_id_tenant_id_key' AND conrelid = 'public.meters'::regclass) THEN
        ALTER TABLE public.meters ADD CONSTRAINT meters_id_tenant_id_key UNIQUE (id, tenant_id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'meter_readings_id_tenant_id_key' AND conrelid = 'public.meter_readings'::regclass) THEN
        ALTER TABLE public.meter_readings ADD CONSTRAINT meter_readings_id_tenant_id_key UNIQUE (id, tenant_id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'service_orders_id_tenant_id_key' AND conrelid = 'public.service_orders'::regclass) THEN
        ALTER TABLE public.service_orders ADD CONSTRAINT service_orders_id_tenant_id_key UNIQUE (id, tenant_id);
    END IF;
END;
$$;

-- ----------------------------------------------------------------------------
-- 2. Consecutive-estimate counter (CI-113, D14-1)
-- ----------------------------------------------------------------------------
ALTER TABLE public.meters
    ADD COLUMN IF NOT EXISTS consecutive_estimate_count integer DEFAULT 0 NOT NULL,
    ADD COLUMN IF NOT EXISTS consecutive_estimate_streak_started_on date,
    ADD COLUMN IF NOT EXISTS last_validated_actual_reading_id uuid;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'meters_consecutive_estimate_count_check' AND conrelid = 'public.meters'::regclass) THEN
        ALTER TABLE public.meters ADD CONSTRAINT meters_consecutive_estimate_count_check CHECK (consecutive_estimate_count >= 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'meters_streak_consistent_check' AND conrelid = 'public.meters'::regclass) THEN
        ALTER TABLE public.meters ADD CONSTRAINT meters_streak_consistent_check
            CHECK ((consecutive_estimate_count = 0 AND consecutive_estimate_streak_started_on IS NULL)
                OR (consecutive_estimate_count > 0 AND consecutive_estimate_streak_started_on IS NOT NULL));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'meters_last_validated_actual_reading_id_fkey' AND conrelid = 'public.meters'::regclass) THEN
        ALTER TABLE public.meters ADD CONSTRAINT meters_last_validated_actual_reading_id_fkey
            FOREIGN KEY (last_validated_actual_reading_id, tenant_id) REFERENCES public.meter_readings(id, tenant_id)
            DEFERRABLE INITIALLY DEFERRED;   -- a read born approved resets the meter before its own row exists
    END IF;
END;
$$;

COMMENT ON COLUMN public.meters.consecutive_estimate_count IS
    'CI-113 / D14-1 (v5.4.2-05): number of consecutive estimated main-register reads approved for this meter since the last VALIDATED actual read (a non-estimated read that reached validation_status = approved). Maintained only by enforce_read_exception_gate(); direct writes are rejected. Cause-indifferent (an RF-collision estimate counts). derive_consecutive_estimate_count(id) recomputes it from history.';
COMMENT ON COLUMN public.meters.consecutive_estimate_streak_started_on IS 'reading_date of the first estimate in the current streak; NULL when the count is 0.';
COMMENT ON COLUMN public.meters.last_validated_actual_reading_id IS 'The read that last reset the streak (D14-1b: passed VEE or operator-accepted, i.e. reached approved). NULL until one has.';

CREATE OR REPLACE FUNCTION public.max_consecutive_estimates(p_tenant_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_cap integer;
BEGIN
    SELECT coalesce((t.settings #>> '{estimation,max_consecutive_estimates}')::integer, 3)
      INTO v_cap
      FROM public.tenants t WHERE t.id = p_tenant_id;
    IF v_cap IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = format('tenant %s not found (or not visible)', p_tenant_id), ERRCODE = 'no_data_found';
    END IF;
    IF v_cap < 1 THEN
        RAISE EXCEPTION USING
            MESSAGE = format('tenants.settings.estimation.max_consecutive_estimates = %s is invalid: the cap must be at least 1 (CI-113)', v_cap),
            ERRCODE = 'check_violation';
    END IF;
    RETURN v_cap;
END;
$$;

COMMENT ON FUNCTION public.max_consecutive_estimates(uuid) IS
    'The tenant''s consecutive-estimate cap: tenants.settings.estimation.max_consecutive_estimates, default 3, must be >= 1 (decision table #4). The Texas 6-month ceiling is NOT enforced here (open question for Kyle).';

CREATE OR REPLACE FUNCTION public.consecutive_estimate_state(p_meter_id uuid)
    RETURNS TABLE (cnt integer, started_on date, last_actual uuid)
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$
    -- The streak is the set of VALIDATED estimates (validated_at set — a read
    -- excluded after validation stays counted) whose reading_date lies AFTER
    -- the latest-dated validated actual. A back-dated actual validated later
    -- does not clear estimates dated after it (the customer is still being
    -- estimated for those periods); a same-day estimate beside an actual is
    -- not counted (the actual covers that date). Main register only.
    WITH v AS (
        SELECT r.id, r.is_estimated, r.reading_date, r.validated_at
        FROM public.meter_readings r
        WHERE r.meter_id = p_meter_id AND r.register_type = 'main' AND r.validated_at IS NOT NULL
    ),
    la AS (
        SELECT v.id, v.reading_date FROM v WHERE NOT v.is_estimated
        ORDER BY v.reading_date DESC, v.validated_at DESC, v.id DESC LIMIT 1
    )
    SELECT (SELECT count(*)::integer FROM v WHERE v.is_estimated AND v.reading_date > coalesce((SELECT la.reading_date FROM la), DATE '0001-01-01')),
           (SELECT min(v.reading_date) FROM v WHERE v.is_estimated AND v.reading_date > coalesce((SELECT la.reading_date FROM la), DATE '0001-01-01')),
           (SELECT la.id FROM la);
$$;

COMMENT ON FUNCTION public.consecutive_estimate_state(uuid) IS
    'Recomputes (consecutive_estimate_count, consecutive_estimate_streak_started_on, last_validated_actual_reading_id) for a meter: validated main-register estimates dated after the latest-dated validated actual (validated_at marks validation; reading_date orders the streak). Backfill source and reconciliation check for the stored columns; the stored value must always equal this.';

CREATE OR REPLACE FUNCTION public.derive_consecutive_estimate_count(p_meter_id uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$ SELECT cnt FROM public.consecutive_estimate_state(p_meter_id) $$;

COMMENT ON FUNCTION public.derive_consecutive_estimate_count(uuid) IS 'consecutive_estimate_state(meter).cnt — the derived counter (CI-113).';

-- Backfill once. Step 1: validation events for history — every read already
-- in a billable state gets validated_at (locked_at, else created_at: an
-- approximation, reported). Step 2: the counter from the same function the
-- reconciliation uses. Re-runnable: step 1 matches nothing once stamped,
-- step 2 is skipped once any counter is populated.
DO $$
DECLARE
    v_stamped bigint;
    v_over bigint;
    v_badcap bigint;
BEGIN
    -- The UPDATEs fire the v5.2.1 triggers on these tables, whose bodies are
    -- unqualified; under the strict prelude they need a path for the length
    -- of this transaction (D-2026-08-28-22's class).
    PERFORM set_config('search_path', 'public, pg_temp', true);

    -- An app-set validated_at on a read that never reached a billable state
    -- is not a validation event (Fable round 2): clear it, report it.
    UPDATE public.meter_readings r
       SET validated_at = NULL
     WHERE r.validation_status NOT IN ('approved', 'released_to_billing', 'locked', 'void_released')
       AND r.validated_at IS NOT NULL;
    GET DIAGNOSTICS v_stamped = ROW_COUNT;
    IF v_stamped > 0 THEN
        RAISE NOTICE 'v5.4.2-05: validated_at cleared on % read(s) that never reached a billable state (the column now marks the validation event)', v_stamped;
    END IF;
    UPDATE public.meter_readings r
       SET validated_at = coalesce(r.locked_at, r.created_at)
     WHERE r.validation_status IN ('approved', 'released_to_billing', 'locked', 'void_released')
       AND r.validated_at IS NULL;
    GET DIAGNOSTICS v_stamped = ROW_COUNT;
    IF v_stamped > 0 THEN
        RAISE NOTICE 'v5.4.2-05: validated_at stamped on % historical read(s) from locked_at/created_at (approximation of the validation instant)', v_stamped;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.meters m WHERE m.consecutive_estimate_count > 0 OR m.last_validated_actual_reading_id IS NOT NULL) THEN
        UPDATE public.meters m
           SET consecutive_estimate_count = st.cnt,
               consecutive_estimate_streak_started_on = st.started_on,
               last_validated_actual_reading_id = st.last_actual
          FROM (SELECT m2.id, st2.* FROM public.meters m2 CROSS JOIN LATERAL public.consecutive_estimate_state(m2.id) st2) st
         WHERE st.id = m.id
           AND (st.cnt > 0 OR st.last_actual IS NOT NULL);
        -- Reporting only — never a refusal: a misconfigured cap is named, not fatal.
        SELECT count(*) INTO v_badcap FROM public.tenants t
         WHERE coalesce((t.settings #>> '{estimation,max_consecutive_estimates}')::integer, 3) < 1;
        IF v_badcap > 0 THEN
            RAISE NOTICE 'v5.4.2-05: % tenant(s) have settings.estimation.max_consecutive_estimates < 1; max_consecutive_estimates() will raise for them until corrected', v_badcap;
        END IF;
        SELECT count(*) INTO v_over
          FROM public.meters m JOIN public.tenants t ON t.id = m.tenant_id
         WHERE m.consecutive_estimate_count >= greatest(coalesce((t.settings #>> '{estimation,max_consecutive_estimates}')::integer, 3), 1);
        IF v_over > 0 THEN
            RAISE NOTICE 'v5.4.2-05: % meter(s) start at or above their consecutive-estimate cap; their next estimate cannot be approved without a field order or a reason-coded override (CI-113)', v_over;
        END IF;
    END IF;
END;
$$;

COMMENT ON COLUMN public.meter_readings.validated_at IS
    'Since v5.4.2-05: the instant the read first entered a billable validation_status (approved / released_to_billing / locked) — stamped by enforce_read_exception_gate() with the server clock (clock_timestamp(), so events in one transaction stay ordered), caller values replaced, frozen once set, NULL until then. The consecutive-estimate streak is ordered by this column. Historical reads were stamped from locked_at/created_at at patch time.';

-- Counter columns are written only from inside the read gate (trigger depth).
CREATE OR REPLACE FUNCTION public.enforce_meter_estimate_counter() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF (OLD.consecutive_estimate_count IS DISTINCT FROM NEW.consecutive_estimate_count
        OR OLD.consecutive_estimate_streak_started_on IS DISTINCT FROM NEW.consecutive_estimate_streak_started_on
        OR OLD.last_validated_actual_reading_id IS DISTINCT FROM NEW.last_validated_actual_reading_id)
       AND pg_trigger_depth() < 2 THEN
        RAISE EXCEPTION USING
            MESSAGE = format('meter %s: consecutive_estimate_count / streak columns are maintained by the read validation gate only (CI-113, D14-1) — approve or reset through meter_readings.validation_status', OLD.id),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS enforce_meter_estimate_counter ON public.meters;
CREATE TRIGGER enforce_meter_estimate_counter BEFORE UPDATE ON public.meters
    FOR EACH ROW EXECUTE FUNCTION public.enforce_meter_estimate_counter();

-- ----------------------------------------------------------------------------
-- 3. Meter master completeness (CI-023)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.meter_master_incomplete_reasons(p_meter_id uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
DECLARE
    m public.meters%ROWTYPE;
    v text[] := ARRAY[]::text[];
BEGIN
    SELECT * INTO m FROM public.meters x WHERE x.id = p_meter_id;
    IF NOT FOUND THEN
        RETURN ARRAY['meter not found (or not visible)'];
    END IF;
    IF m.rollover_point IS NULL AND m.dial_count IS NULL THEN
        v := array_append(v, 'rollover_point or dial_count');
    END IF;
    IF m.service_type = 'gas' THEN
        IF m.meter_pressure_class IS NULL THEN
            v := array_append(v, 'meter_pressure_class');
        ELSIF m.meter_pressure_class = 'elevated' AND m.meter_factor IS NULL THEN
            v := array_append(v, 'meter_factor (elevated pressure)');
        END IF;
    END IF;
    RETURN v;
END;
$$;

COMMENT ON FUNCTION public.meter_master_incomplete_reasons(uuid) IS
    'CI-023 (v5.4.2-05): the master attributes the volume-to-energy formula depends on that this meter lacks — empty array = complete. Checked: rollover_point or dial_count; for gas, meter_pressure_class, and meter_factor when elevated. multiplier is NOT NULL already; temperature_compensated does not exist (unruled). billing_run_meters refuses billed/billed_estimated for an incomplete meter.';

-- Tenant binding for the plain FKs to users / anomalies (Codex round 1: a
-- T2 user's id was accepted as resolved_by on a T1 row — FK checks bypass
-- RLS, so the guard must check the referenced row's tenant itself).
CREATE OR REPLACE FUNCTION public.assert_same_tenant_user(p_user_id uuid, p_tenant_id uuid, p_column text) RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_user_id IS NULL THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_user_id AND (u.tenant_id = p_tenant_id OR u.role = 'platform_admin')) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('%s must name a user of tenant %s (or a platform admin)', p_column, p_tenant_id),
            ERRCODE = 'check_violation';
    END IF;
END;
$$;

COMMENT ON FUNCTION public.assert_same_tenant_user(uuid, uuid, text) IS 'v5.4.2-05: the referenced user must belong to the row''s tenant (platform admins excepted). Used by the exception guards for raised_by / resolved_by / assigned_to.';

-- ----------------------------------------------------------------------------
-- 4. read_validation_exceptions (CI-112)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.read_validation_exceptions (
    id                      uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id               uuid NOT NULL,
    meter_reading_id        uuid NOT NULL,
    meter_id                uuid NOT NULL,
    rule_code               text NOT NULL,
    severity                text DEFAULT 'medium' NOT NULL,
    detail                  jsonb DEFAULT '{}'::jsonb NOT NULL,
    detected_at             timestamp with time zone DEFAULT now() NOT NULL,
    detected_by             text DEFAULT 'system' NOT NULL,
    raised_by_user_id       uuid,
    status                  text DEFAULT 'open' NOT NULL,
    resolution_disposition  text,
    resolution_reason_code  text,
    resolution_notes        text,
    resolved_by             uuid,
    resolved_at             timestamp with time zone,
    field_order_id          uuid,
    replacement_reading_id  uuid,
    notes                   text,
    created_at              timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT read_validation_exceptions_pkey PRIMARY KEY (id),
    CONSTRAINT read_validation_exceptions_id_tenant_id_key UNIQUE (id, tenant_id),
    CONSTRAINT read_validation_exceptions_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT read_validation_exceptions_reading_fkey FOREIGN KEY (meter_reading_id, tenant_id) REFERENCES public.meter_readings(id, tenant_id),
    CONSTRAINT read_validation_exceptions_meter_fkey FOREIGN KEY (meter_id, tenant_id) REFERENCES public.meters(id, tenant_id),
    CONSTRAINT read_validation_exceptions_raised_by_fkey FOREIGN KEY (raised_by_user_id) REFERENCES public.users(id),
    CONSTRAINT read_validation_exceptions_resolved_by_fkey FOREIGN KEY (resolved_by) REFERENCES public.users(id),
    CONSTRAINT read_validation_exceptions_field_order_fkey FOREIGN KEY (field_order_id, tenant_id) REFERENCES public.service_orders(id, tenant_id),
    CONSTRAINT read_validation_exceptions_replacement_fkey FOREIGN KEY (replacement_reading_id, tenant_id) REFERENCES public.meter_readings(id, tenant_id),
    CONSTRAINT read_validation_exceptions_rule_code_check CHECK (rule_code = ANY (ARRAY[
        'high_vs_history'::text, 'low_vs_history'::text, 'reverse_read'::text, 'max_dial_rollover'::text,
        'consecutive_estimate_over_cap'::text, 'zero_read_active_account'::text, 'reading_date_gap'::text,
        'negative_consumption'::text, 'meter_master_incomplete'::text, 'tamper_indicated'::text, 'other'::text])),
    CONSTRAINT read_validation_exceptions_severity_check CHECK (severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])),
    CONSTRAINT read_validation_exceptions_detected_by_check CHECK (detected_by = ANY (ARRAY['system'::text, 'operator'::text, 'import'::text])),
    CONSTRAINT read_validation_exceptions_status_check CHECK (status = ANY (ARRAY['open'::text, 'resolved'::text])),
    CONSTRAINT read_validation_exceptions_disposition_check CHECK (resolution_disposition IS NULL OR resolution_disposition = ANY (ARRAY[
        'estimate_accepted'::text, 'manual_read_entered'::text, 'read_corrected'::text, 'field_order_dispatched'::text, 'excluded'::text, 'override'::text])),
    CONSTRAINT read_validation_exceptions_detail_check CHECK (jsonb_typeof(detail) = 'object'),
    CONSTRAINT read_validation_exceptions_resolution_consistent_check CHECK (
        (status = 'open' AND resolution_disposition IS NULL AND resolution_reason_code IS NULL AND resolved_by IS NULL AND resolved_at IS NULL
             AND field_order_id IS NULL AND replacement_reading_id IS NULL)
     OR (status = 'resolved' AND resolution_disposition IS NOT NULL AND resolution_reason_code IS NOT NULL AND length(btrim(resolution_reason_code)) > 0 AND resolved_by IS NOT NULL AND resolved_at IS NOT NULL)),
    CONSTRAINT read_validation_exceptions_disposition_links_check CHECK (
        status = 'open'
     OR (resolution_disposition = 'field_order_dispatched' AND field_order_id IS NOT NULL)
     OR (resolution_disposition IN ('manual_read_entered', 'read_corrected') AND replacement_reading_id IS NOT NULL)
     OR (resolution_disposition IN ('estimate_accepted', 'excluded', 'override'))),
    CONSTRAINT read_validation_exceptions_over_cap_path_check CHECK (
        status = 'open' OR rule_code <> 'consecutive_estimate_over_cap'
     OR resolution_disposition IN ('override', 'field_order_dispatched'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_read_validation_exceptions_open_rule
    ON public.read_validation_exceptions USING btree (meter_reading_id, rule_code) WHERE (status = 'open');
CREATE INDEX IF NOT EXISTS idx_read_validation_exceptions_tenant_open
    ON public.read_validation_exceptions USING btree (tenant_id, status) WHERE (status = 'open');
CREATE INDEX IF NOT EXISTS idx_read_validation_exceptions_meter ON public.read_validation_exceptions USING btree (meter_id);
CREATE INDEX IF NOT EXISTS idx_read_validation_exceptions_reading ON public.read_validation_exceptions USING btree (meter_reading_id);

ALTER TABLE public.read_validation_exceptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.read_validation_exceptions FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.read_validation_exceptions;
CREATE POLICY tenant_isolation ON public.read_validation_exceptions USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));

COMMENT ON TABLE public.read_validation_exceptions IS
    'CI-112 read exception queue (v5.4.2-05, A-20). One row per failed validation rule per read. Open until resolved exactly once with a CI-112 disposition (estimate_accepted | manual_read_entered | read_corrected | field_order_dispatched | excluded | override), a reason code, a resolver and a server-stamped time; a resolved row is frozen; rows are never deleted. A read with an open row cannot reach approved / released_to_billing and cannot be billed (enforce_read_exception_gate, billing_run_meters guard). consecutive_estimate_over_cap rows are raised by the database and resolve only by override or field_order_dispatched (CI-113 rows 3/4).';
COMMENT ON COLUMN public.read_validation_exceptions.resolution_reason_code IS 'Free text, required at resolution (CI-112 "with a reason code recorded"). No catalogue exists yet; a later patch may add a CHECK.';
COMMENT ON COLUMN public.read_validation_exceptions.field_order_id IS 'Required when resolution_disposition = field_order_dispatched; must be a service_orders row for the same meter.';
COMMENT ON COLUMN public.read_validation_exceptions.replacement_reading_id IS 'Required when resolution_disposition ∈ (manual_read_entered, read_corrected); must be a different meter_readings row for the same meter.';

CREATE OR REPLACE FUNCTION public.enforce_read_validation_exception() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_read   public.meter_readings%ROWTYPE;
    v_meter  uuid;
BEGIN
    IF TG_OP = 'INSERT' THEN
        -- FOR SHARE: serialises against a concurrent validation of the same read.
        SELECT * INTO v_read FROM public.meter_readings r WHERE r.id = NEW.meter_reading_id FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = format('read exception rejected: reading %s not found (or not visible)', NEW.meter_reading_id), ERRCODE = 'foreign_key_violation';
        END IF;
        IF v_read.validation_status IN ('locked', 'void_released') THEN
            RAISE EXCEPTION USING MESSAGE = format('read exception rejected: reading %s is %s (already billed) — a problem found now is corrected with a replacement reading, not an exception on the billed one (CI-012)', NEW.meter_reading_id, v_read.validation_status), ERRCODE = 'check_violation';
        END IF;
        IF v_read.tenant_id <> NEW.tenant_id OR v_read.meter_id <> NEW.meter_id THEN
            RAISE EXCEPTION USING MESSAGE = 'read exception rejected: tenant_id and meter_id must be the reading''s', ERRCODE = 'check_violation';
        END IF;
        IF NEW.status <> 'open' THEN
            RAISE EXCEPTION USING MESSAGE = 'read exception rejected: a row is born open and resolved by a later UPDATE (the resolution is the lineage, CI-088)', ERRCODE = 'check_violation';
        END IF;
        PERFORM public.assert_same_tenant_user(NEW.raised_by_user_id, NEW.tenant_id, 'raised_by_user_id');
        NEW.detected_at := now();
        NEW.created_at := now();
        RETURN NEW;
    END IF;

    -- UPDATE
    IF OLD.status = 'resolved' THEN
        RAISE EXCEPTION USING
            MESSAGE = format('read exception %s is resolved and frozen (CI-112 / CI-088): a disposition is never edited — raise a new exception if the read fails again', OLD.id),
            ERRCODE = 'check_violation';
    END IF;
    -- Identity of an open row is frozen; only severity/detail/notes and the resolution may change.
    IF OLD.id <> NEW.id OR OLD.tenant_id <> NEW.tenant_id OR OLD.meter_reading_id <> NEW.meter_reading_id OR OLD.meter_id <> NEW.meter_id
       OR OLD.rule_code <> NEW.rule_code OR OLD.detected_at <> NEW.detected_at OR OLD.detected_by <> NEW.detected_by
       OR OLD.raised_by_user_id IS DISTINCT FROM NEW.raised_by_user_id OR OLD.created_at <> NEW.created_at THEN
        RAISE EXCEPTION USING MESSAGE = format('read exception %s: identity columns are frozen', OLD.id), ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'resolved' THEN
        NEW.resolved_at := now();
        PERFORM public.assert_same_tenant_user(NEW.resolved_by, OLD.tenant_id, 'resolved_by');
        IF NEW.resolution_disposition = 'field_order_dispatched' THEN
            SELECT so.meter_id INTO v_meter FROM public.service_orders so WHERE so.id = NEW.field_order_id;
            IF NOT FOUND OR v_meter IS DISTINCT FROM OLD.meter_id THEN
                RAISE EXCEPTION USING MESSAGE = format('read exception %s: field_order_id must name a service order for meter %s', OLD.id, OLD.meter_id), ERRCODE = 'check_violation';
            END IF;
        ELSIF NEW.resolution_disposition IN ('manual_read_entered', 'read_corrected') THEN
            SELECT r.meter_id INTO v_meter FROM public.meter_readings r WHERE r.id = NEW.replacement_reading_id;
            IF NOT FOUND OR v_meter IS DISTINCT FROM OLD.meter_id OR NEW.replacement_reading_id = OLD.meter_reading_id THEN
                RAISE EXCEPTION USING MESSAGE = format('read exception %s: replacement_reading_id must name a different reading of meter %s', OLD.id, OLD.meter_id), ERRCODE = 'check_violation';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_read_validation_exception() IS
    'read_validation_exceptions guard (v5.4.2-05): born open in the reading''s tenant/meter with server stamps; open rows may change severity/detail/notes or resolve (once — resolved_at forced to now(); field order / replacement read verified against the same meter); resolved rows are frozen. Table CHECKs carry the disposition and over-cap path rules.';

DROP TRIGGER IF EXISTS a_enforce_read_validation_exception ON public.read_validation_exceptions;
CREATE TRIGGER a_enforce_read_validation_exception BEFORE INSERT OR UPDATE ON public.read_validation_exceptions
    FOR EACH ROW EXECUTE FUNCTION public.enforce_read_validation_exception();

-- ----------------------------------------------------------------------------
-- 5. The read gate + counter maintenance on meter_readings (CI-112, CI-113)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_read_exception_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_billable boolean;          -- NEW is in a billable state
    v_transition boolean;        -- entering a billable state from a non-billable one (or born there)
    v_first boolean;             -- the read's FIRST validation event (validated_at not yet set)
    v_open_rules text;
    v_count integer;
    v_cap integer;
    v_last_actual_date date;
BEGIN
    v_billable := NEW.validation_status IN ('approved', 'released_to_billing', 'locked');
    v_transition := v_billable AND (TG_OP = 'INSERT' OR OLD.validation_status NOT IN ('approved', 'released_to_billing', 'locked', 'void_released'));

    -- validated_at is the database's: NULL until the first validation event,
    -- then frozen. Caller values are replaced.
    IF TG_OP = 'INSERT' THEN
        NEW.validated_at := NULL;
    ELSE
        NEW.validated_at := OLD.validated_at;
    END IF;
    v_first := v_billable AND NEW.validated_at IS NULL;

    -- Once validated, the facts the streak was derived from are frozen (the
    -- v5.2.1 whitelist only froze them at 'locked'; flipping is_estimated on
    -- an approved read desynced the counter from its derivation).
    IF TG_OP = 'UPDATE' AND OLD.validated_at IS NOT NULL
       AND (OLD.is_estimated <> NEW.is_estimated OR OLD.register_type <> NEW.register_type OR OLD.meter_id <> NEW.meter_id
            OR OLD.reading_date <> NEW.reading_date OR OLD.tenant_id <> NEW.tenant_id) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('reading %s is validated (%s): is_estimated, register_type, meter_id, reading_date and tenant_id are frozen (CI-113 counter derivation) — correct it with a replacement reading', OLD.id, OLD.validation_status),
            ERRCODE = 'check_violation';
    END IF;

    IF NEW.validation_status = 'reviewed_clean' AND (TG_OP = 'INSERT' OR OLD.validation_status IS DISTINCT FROM 'reviewed_clean') THEN
        IF EXISTS (SELECT 1 FROM public.read_validation_exceptions e WHERE e.meter_reading_id = NEW.id AND e.status = 'open') THEN
            RAISE EXCEPTION USING MESSAGE = format('reading %s cannot be reviewed_clean while an exception is open (CI-112)', NEW.id), ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF NEW.validation_status = 'reviewed_with_exception' AND (TG_OP = 'INSERT' OR OLD.validation_status IS DISTINCT FROM 'reviewed_with_exception') THEN
        IF NOT EXISTS (SELECT 1 FROM public.read_validation_exceptions e WHERE e.meter_reading_id = NEW.id) THEN
            RAISE EXCEPTION USING MESSAGE = format('reading %s cannot be reviewed_with_exception without a read_validation_exceptions row naming the failed rule (CI-112)', NEW.id), ERRCODE = 'check_violation';
        END IF;
    END IF;

    -- CI-112: no open exception may ride into, or further along, billing —
    -- checked on EVERY step into approved / released_to_billing / locked.
    IF v_billable AND (TG_OP = 'INSERT' OR OLD.validation_status IS DISTINCT FROM NEW.validation_status) THEN
        SELECT string_agg(e.rule_code, ', ' ORDER BY e.rule_code) INTO v_open_rules
          FROM public.read_validation_exceptions e WHERE e.meter_reading_id = NEW.id AND e.status = 'open';
        IF v_open_rules IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = format('reading %s cannot enter %s: open validation exception(s) %s must be resolved first — estimate accepted, manual read entered, field order dispatched, or a reason-coded override (CI-112)', NEW.id, NEW.validation_status, v_open_rules),
                ERRCODE = 'check_violation';
        END IF;
    END IF;

    IF NOT v_first THEN
        RETURN NEW;   -- re-entries (approved -> pending_review -> approved) are not new validation events
    END IF;
    -- clock_timestamp(), not now(): two reads validated in one transaction
    -- must still have a definite order (the streak is ordered by this stamp).
    NEW.validated_at := clock_timestamp();

    -- CI-113 / D14-1: the counter moves at most once per main-register read,
    -- on its validation event, in READING-DATE terms: an estimate counts only
    -- if dated after the latest validated actual; an actual resets only if it
    -- is dated at/after that actual (a back-dated correction does not clear
    -- estimates dated after it — Codex round 2 showed the naive reset let
    -- estimates run past the cap).
    IF NEW.register_type <> 'main' THEN
        RETURN NEW;
    END IF;
    SELECT m.consecutive_estimate_count, a.reading_date
      INTO v_count, v_last_actual_date
      FROM public.meters m
      LEFT JOIN public.meter_readings a ON a.id = m.last_validated_actual_reading_id
     WHERE m.id = NEW.meter_id
       FOR UPDATE OF m;
    IF NOT FOUND THEN
        RETURN NEW;   -- FK will reject the insert anyway
    END IF;
    IF NEW.is_estimated THEN
        IF v_last_actual_date IS NOT NULL AND NEW.reading_date <= v_last_actual_date THEN
            RETURN NEW;   -- dated at/before the last validated actual: not part of the streak
        END IF;
        v_cap := public.max_consecutive_estimates(NEW.tenant_id);
        IF v_count + 1 >= v_cap
           AND NOT EXISTS (SELECT 1 FROM public.read_validation_exceptions e
                            WHERE e.meter_reading_id = NEW.id AND e.rule_code = 'consecutive_estimate_over_cap'
                              AND e.status = 'resolved' AND e.resolution_disposition IN ('override', 'field_order_dispatched')) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('reading %s: approving this estimate makes %s consecutive estimates on meter %s (cap %s) — a bill cannot be generated against an over-cap streak without a field order or a reason-coded override on the consecutive_estimate_over_cap exception (CI-113, D14-1)', NEW.id, v_count + 1, NEW.meter_id, v_cap),
                ERRCODE = 'check_violation';
        END IF;
        UPDATE public.meters m
           SET consecutive_estimate_count = v_count + 1,
               consecutive_estimate_streak_started_on = CASE WHEN v_count = 0 THEN NEW.reading_date ELSE least(m.consecutive_estimate_streak_started_on, NEW.reading_date) END
         WHERE m.id = NEW.meter_id;
    ELSE
        IF v_last_actual_date IS NOT NULL AND NEW.reading_date < v_last_actual_date THEN
            RETURN NEW;   -- back-dated actual: the later actual still bounds the streak
        END IF;
        -- This actual is the latest-dated: the streak is whatever validated
        -- estimates are dated after it (usually none).
        UPDATE public.meters m
           SET consecutive_estimate_count = s.cnt,
               consecutive_estimate_streak_started_on = s.started_on,
               last_validated_actual_reading_id = NEW.id
          FROM (SELECT count(*)::integer AS cnt, min(r.reading_date) AS started_on
                  FROM public.meter_readings r
                 WHERE r.meter_id = NEW.meter_id AND r.register_type = 'main' AND r.is_estimated
                   AND r.validated_at IS NOT NULL AND r.reading_date > NEW.reading_date) s
         WHERE m.id = NEW.meter_id;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_read_exception_gate() IS
    'CI-112 + CI-113 gate on meter_readings (v5.4.2-05). Every step into approved / released_to_billing / locked (by UPDATE, or born there) requires no open read_validation_exceptions row; reviewed_clean requires none open, reviewed_with_exception requires one to exist (INSERT included). validated_at is stamped with the server clock on the read''s FIRST billable entry and frozen; on that event — once per main-register read, re-entries do not recount — the meter''s streak moves: an estimate increments it (refused at the cap unless a consecutive_estimate_over_cap exception on this read was resolved by override or field order), a non-estimated read resets it and is remembered as last_validated_actual_reading_id (D14-1). Once validated, is_estimated / register_type / meter_id / reading_date / tenant_id are frozen. Runs after enforce_reading_validation_workflow (name-ordered).';

DROP TRIGGER IF EXISTS z_enforce_read_exception_gate ON public.meter_readings;
CREATE TRIGGER z_enforce_read_exception_gate BEFORE INSERT OR UPDATE ON public.meter_readings
    FOR EACH ROW EXECUTE FUNCTION public.enforce_read_exception_gate();

-- The database raises the over-cap exception when the estimate is recorded.
CREATE OR REPLACE FUNCTION public.raise_consecutive_estimate_exception() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_count integer;
    v_cap integer;
    v_last_actual_date date;
BEGIN
    IF NOT NEW.is_estimated OR NEW.register_type <> 'main'
       OR NEW.validation_status IN ('approved', 'released_to_billing', 'locked', 'void_released', 'excluded') THEN
        RETURN NULL;
    END IF;
    -- Stored streak + estimates already waiting (not yet validated, not
    -- excluded/voided, dated after the last validated actual) + this one.
    SELECT m.consecutive_estimate_count
         + (SELECT count(*) FROM public.meter_readings p
             WHERE p.meter_id = NEW.meter_id AND p.register_type = 'main' AND p.is_estimated
               AND p.validated_at IS NULL AND p.id <> NEW.id
               AND p.validation_status <> 'excluded' AND p.status NOT IN ('voided', 'replaced')
               AND (a.reading_date IS NULL OR p.reading_date > a.reading_date)),
           a.reading_date
      INTO v_count, v_last_actual_date
      FROM public.meters m LEFT JOIN public.meter_readings a ON a.id = m.last_validated_actual_reading_id
     WHERE m.id = NEW.meter_id;
    IF v_last_actual_date IS NOT NULL AND NEW.reading_date <= v_last_actual_date THEN
        RETURN NULL;   -- dated at/before the last validated actual: cannot extend the streak
    END IF;
    v_cap := public.max_consecutive_estimates(NEW.tenant_id);
    IF v_count + 1 >= v_cap THEN
        INSERT INTO public.read_validation_exceptions (tenant_id, meter_reading_id, meter_id, rule_code, severity, detail, detected_by)
        VALUES (NEW.tenant_id, NEW.id, NEW.meter_id, 'consecutive_estimate_over_cap', 'high',
                jsonb_build_object('consecutive_estimate_count_before', v_count, 'would_become', v_count + 1, 'cap', v_cap,
                                   'estimation_reason', NEW.estimation_reason, 'streak_started_on', (SELECT m.consecutive_estimate_streak_started_on FROM public.meters m WHERE m.id = NEW.meter_id)),
                'system')
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END;
$$;

COMMENT ON FUNCTION public.raise_consecutive_estimate_exception() IS
    'CI-113 rows 3/4 (v5.4.2-05): when an estimated main-register read is inserted in a pre-approval state and would bring the meter to its cap (stored streak + estimates already pending + this one), the database opens a consecutive_estimate_over_cap exception (severity high; estimation_reason recorded for triage, D14-1c — the counter is cause-indifferent). Only a field order or a reason-coded override can resolve it.';

DROP TRIGGER IF EXISTS z_raise_consecutive_estimate_exception ON public.meter_readings;
CREATE TRIGGER z_raise_consecutive_estimate_exception AFTER INSERT ON public.meter_readings
    FOR EACH ROW EXECUTE FUNCTION public.raise_consecutive_estimate_exception();

-- Bill-generation side (CI-112) + master completeness (CI-023) on billing_run_meters.
CREATE OR REPLACE FUNCTION public.enforce_billing_run_meter_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_open_rules text;
    v_reasons text[];
BEGIN
    IF NEW.outcome NOT IN ('billed', 'billed_estimated') THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.outcome IN ('billed', 'billed_estimated') AND OLD.meter_reading_id IS NOT DISTINCT FROM NEW.meter_reading_id AND OLD.meter_id = NEW.meter_id THEN
        RETURN NEW;   -- already billed on this read; not re-gating lifecycle edits
    END IF;
    IF NEW.meter_reading_id IS NOT NULL THEN
        SELECT string_agg(e.rule_code, ', ' ORDER BY e.rule_code) INTO v_open_rules
          FROM public.read_validation_exceptions e WHERE e.meter_reading_id = NEW.meter_reading_id AND e.status = 'open';
        IF v_open_rules IS NOT NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = format('billing_run_meters: meter %s cannot be billed against reading %s — open validation exception(s) %s (CI-112)', NEW.meter_id, NEW.meter_reading_id, v_open_rules),
                ERRCODE = 'check_violation';
        END IF;
    END IF;
    v_reasons := public.meter_master_incomplete_reasons(NEW.meter_id);
    IF cardinality(v_reasons) > 0 THEN
        RAISE EXCEPTION USING
            MESSAGE = format('billing_run_meters: meter %s master record is incomplete (%s) — it belongs in the exception queue (read_validation_exceptions rule meter_master_incomplete), not the bill stream (CI-023)', NEW.meter_id, array_to_string(v_reasons, '; ')),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_billing_run_meter_gate() IS
    'billing_run_meters guard (v5.4.2-05): an outcome of billed / billed_estimated is refused while the read carries an open read_validation_exceptions row (CI-112) or the meter master is incomplete per meter_master_incomplete_reasons() (CI-023).';

DROP TRIGGER IF EXISTS enforce_billing_run_meter_gate ON public.billing_run_meters;
CREATE TRIGGER enforce_billing_run_meter_gate BEFORE INSERT OR UPDATE ON public.billing_run_meters
    FOR EACH ROW EXECUTE FUNCTION public.enforce_billing_run_meter_gate();

-- ----------------------------------------------------------------------------
-- 6. invoice_exceptions — the pre-mail queue (CI-115)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.invoice_exceptions (
    id                          uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id                   uuid NOT NULL,
    invoice_id                  uuid NOT NULL,
    billing_run_id              uuid,
    criterion                   text NOT NULL,
    severity                    text DEFAULT 'medium' NOT NULL,
    exception_source            text DEFAULT 'bill_detector' NOT NULL,
    detail                      jsonb DEFAULT '{}'::jsonb NOT NULL,
    estimated_impact            numeric(12,2),
    queue                       text NOT NULL,
    blocks_delivery             boolean NOT NULL,
    sla_days                    integer,
    escalation_target           text,
    routing_reason              text NOT NULL,
    anomaly_id                  uuid,
    read_validation_exception_id uuid,
    detected_at                 timestamp with time zone DEFAULT now() NOT NULL,
    raised_by_user_id           uuid,
    assigned_to                 uuid,
    status                      text DEFAULT 'open' NOT NULL,
    resolution_reason_code      text,
    resolution_notes            text,
    resolved_by                 uuid,
    resolved_at                 timestamp with time zone,
    notes                       text,
    created_at                  timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT invoice_exceptions_pkey PRIMARY KEY (id),
    CONSTRAINT invoice_exceptions_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT invoice_exceptions_invoice_fkey FOREIGN KEY (invoice_id, tenant_id) REFERENCES public.invoices(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT invoice_exceptions_billing_run_id_fkey FOREIGN KEY (billing_run_id) REFERENCES public.billing_runs(id),
    CONSTRAINT invoice_exceptions_anomaly_id_fkey FOREIGN KEY (anomaly_id) REFERENCES public.anomalies(id),
    CONSTRAINT invoice_exceptions_read_exception_fkey FOREIGN KEY (read_validation_exception_id, tenant_id) REFERENCES public.read_validation_exceptions(id, tenant_id),
    CONSTRAINT invoice_exceptions_raised_by_fkey FOREIGN KEY (raised_by_user_id) REFERENCES public.users(id),
    CONSTRAINT invoice_exceptions_assigned_to_fkey FOREIGN KEY (assigned_to) REFERENCES public.users(id),
    CONSTRAINT invoice_exceptions_resolved_by_fkey FOREIGN KEY (resolved_by) REFERENCES public.users(id),
    CONSTRAINT invoice_exceptions_criterion_check CHECK (criterion = ANY (ARRAY[
        'high_bill'::text, 'zero_bill_active_account'::text, 'negative_bill'::text, 'consecutive_estimate_streak'::text,
        'out_of_tolerance_usage'::text, 'rider_trueup_over_threshold'::text, 'missing_rebill_approval'::text,
        'unresolved_read_exception'::text, 'batch_baseline_breach'::text, 'meter_master_incomplete'::text,
        'tamper_detected'::text, 'canary_mismatch'::text, 'manual'::text, 'other'::text])),
    CONSTRAINT invoice_exceptions_severity_check CHECK (severity = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])),
    CONSTRAINT invoice_exceptions_source_check CHECK (exception_source = ANY (ARRAY['bill_detector'::text, 'batch_baseline'::text, 'read_carryforward'::text, 'manual'::text])),
    CONSTRAINT invoice_exceptions_queue_check CHECK (queue = ANY (ARRAY['batch_hold'::text, 'billing_analyst'::text, 'senior_analyst'::text, 'csr'::text, 'field_ops'::text, 'informational'::text])),
    CONSTRAINT invoice_exceptions_escalation_check CHECK (escalation_target IS NULL OR escalation_target = ANY (ARRAY['senior_analyst'::text, 'billing_manager'::text, 'cfo'::text])),
    CONSTRAINT invoice_exceptions_sla_check CHECK (sla_days IS NULL OR sla_days >= 0),
    CONSTRAINT invoice_exceptions_status_check CHECK (status = ANY (ARRAY['open'::text, 'resolved'::text, 'overridden'::text])),
    CONSTRAINT invoice_exceptions_detail_check CHECK (jsonb_typeof(detail) = 'object'),
    CONSTRAINT invoice_exceptions_routing_reason_check CHECK (routing_reason IS NOT NULL AND length(btrim(routing_reason)) > 0),
    CONSTRAINT invoice_exceptions_carryforward_check CHECK (criterion <> 'unresolved_read_exception' OR read_validation_exception_id IS NOT NULL),
    CONSTRAINT invoice_exceptions_resolution_consistent_check CHECK (
        (status = 'open' AND resolution_reason_code IS NULL AND resolved_by IS NULL AND resolved_at IS NULL)
     OR (status IN ('resolved', 'overridden') AND resolution_reason_code IS NOT NULL AND length(btrim(resolution_reason_code)) > 0 AND resolved_by IS NOT NULL AND resolved_at IS NOT NULL))
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_invoice_exceptions_open_criterion
    ON public.invoice_exceptions USING btree (invoice_id, criterion) WHERE (status = 'open');
CREATE INDEX IF NOT EXISTS idx_invoice_exceptions_open_blocking
    ON public.invoice_exceptions USING btree (invoice_id) WHERE (status = 'open' AND blocks_delivery);
CREATE INDEX IF NOT EXISTS idx_invoice_exceptions_tenant_queue
    ON public.invoice_exceptions USING btree (tenant_id, queue, status);
CREATE INDEX IF NOT EXISTS idx_invoice_exceptions_billing_run ON public.invoice_exceptions USING btree (billing_run_id) WHERE (billing_run_id IS NOT NULL);

ALTER TABLE public.invoice_exceptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_exceptions FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.invoice_exceptions;
CREATE POLICY tenant_isolation ON public.invoice_exceptions USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));

COMMENT ON TABLE public.invoice_exceptions IS
    'CI-115 pre-mail exception queue (v5.4.2-05, A-20). One row per exception criterion per invoice, carrying decision table #35''s routing outputs (queue, blocks_delivery, sla_days, escalation_target, routing_reason). Open until resolved or overridden — both require a reason code, a resolver and a server-stamped time, then the row is frozen. While an open row has blocks_delivery = true the invoice cannot enter pending (release from hold) or sent, and cannot be stamped delivered (enforce_invoice_predelivery_gate). blocks_delivery is frozen at insert and cannot be true on an already-delivered invoice. Every insert / resolution appends an invoice_events row. Queue values are strings until the rbac-model decision lands.';
COMMENT ON COLUMN public.invoice_exceptions.blocks_delivery IS 'Table #35''s control output: the invoice may not be delivered while this is open. Frozen at insert — clearing it is an override, which is a status with a reason code.';
COMMENT ON COLUMN public.invoice_exceptions.status IS 'open → resolved (the bill was corrected or the exception judged not applicable) or → overridden (the flagged bill goes out as-is, by reason-coded decision — CI-115''s escape hatch). Both terminal.';

CREATE OR REPLACE FUNCTION public.enforce_invoice_exception() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_inv public.invoices%ROWTYPE;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT * INTO v_inv FROM public.invoices i WHERE i.id = NEW.invoice_id FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = format('invoice exception rejected: invoice %s not found (or not visible)', NEW.invoice_id), ERRCODE = 'foreign_key_violation';
        END IF;
        IF v_inv.tenant_id <> NEW.tenant_id THEN
            RAISE EXCEPTION USING MESSAGE = 'invoice exception rejected: tenant_id must equal the invoice''s', ERRCODE = 'check_violation';
        END IF;
        IF NEW.billing_run_id IS NULL THEN
            NEW.billing_run_id := v_inv.billing_run_id;
        ELSIF NEW.billing_run_id IS DISTINCT FROM v_inv.billing_run_id THEN
            RAISE EXCEPTION USING MESSAGE = 'invoice exception rejected: billing_run_id must equal the invoice''s', ERRCODE = 'check_violation';
        END IF;
        IF NEW.status <> 'open' THEN
            RAISE EXCEPTION USING MESSAGE = 'invoice exception rejected: a row is born open; resolve or override it by a later UPDATE (the lineage, CI-088)', ERRCODE = 'check_violation';
        END IF;
        IF NEW.blocks_delivery AND (v_inv.sent_at IS NOT NULL OR v_inv.delivery_confirmed_at IS NOT NULL
                                    OR v_inv.status IN ('sent', 'paid', 'partial', 'overdue', 'write_off')) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice exception rejected: invoice %s is already delivered (status %s) — a pre-mail block is meaningless; raise it as blocks_delivery = false or use the dispute workflow', v_inv.invoice_number, v_inv.status),
                ERRCODE = 'check_violation';
        END IF;
        PERFORM public.assert_same_tenant_user(NEW.raised_by_user_id, NEW.tenant_id, 'raised_by_user_id');
        PERFORM public.assert_same_tenant_user(NEW.assigned_to, NEW.tenant_id, 'assigned_to');
        IF NEW.anomaly_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.anomalies a WHERE a.id = NEW.anomaly_id AND a.tenant_id = NEW.tenant_id) THEN
            RAISE EXCEPTION USING MESSAGE = 'invoice exception rejected: anomaly_id must name an anomaly of the same tenant', ERRCODE = 'check_violation';
        END IF;
        NEW.detected_at := now();
        NEW.created_at := now();
        RETURN NEW;
    END IF;

    IF OLD.status <> 'open' THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice exception %s is %s and frozen (CI-115 / CI-088): a disposition is never edited — raise a new exception', OLD.id, OLD.status),
            ERRCODE = 'check_violation';
    END IF;
    IF OLD.id <> NEW.id OR OLD.tenant_id <> NEW.tenant_id OR OLD.invoice_id <> NEW.invoice_id OR OLD.billing_run_id IS DISTINCT FROM NEW.billing_run_id
       OR OLD.criterion <> NEW.criterion OR OLD.exception_source <> NEW.exception_source OR OLD.blocks_delivery <> NEW.blocks_delivery
       OR OLD.routing_reason <> NEW.routing_reason OR OLD.detected_at <> NEW.detected_at OR OLD.raised_by_user_id IS DISTINCT FROM NEW.raised_by_user_id
       OR OLD.anomaly_id IS DISTINCT FROM NEW.anomaly_id OR OLD.read_validation_exception_id IS DISTINCT FROM NEW.read_validation_exception_id
       OR OLD.created_at <> NEW.created_at THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice exception %s: identity, blocks_delivery and routing_reason are frozen — clearing a block is an override (status = overridden, with a reason code)', OLD.id),
            ERRCODE = 'check_violation';
    END IF;
    IF OLD.assigned_to IS DISTINCT FROM NEW.assigned_to THEN
        PERFORM public.assert_same_tenant_user(NEW.assigned_to, OLD.tenant_id, 'assigned_to');
    END IF;
    IF NEW.status IN ('resolved', 'overridden') THEN
        NEW.resolved_at := now();
        PERFORM public.assert_same_tenant_user(NEW.resolved_by, OLD.tenant_id, 'resolved_by');
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS a_enforce_invoice_exception ON public.invoice_exceptions;
CREATE TRIGGER a_enforce_invoice_exception BEFORE INSERT OR UPDATE ON public.invoice_exceptions
    FOR EACH ROW EXECUTE FUNCTION public.enforce_invoice_exception();

-- Draft-invoice delete cascades; every other DELETE is rejected.
CREATE OR REPLACE FUNCTION public.enforce_invoice_exception_no_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.invoices i WHERE i.id = OLD.invoice_id) THEN
        RETURN OLD;   -- cascade from a draft-invoice delete (A-4: only drafts are deletable)
    END IF;
    RAISE EXCEPTION USING
        MESSAGE = format('invoice_exceptions rows are never deleted (CI-014 / CI-088): exception %s stays as lineage — resolve or override it', OLD.id),
        ERRCODE = 'restrict_violation';
END;
$$;

DROP TRIGGER IF EXISTS no_hard_delete ON public.invoice_exceptions;
CREATE TRIGGER no_hard_delete BEFORE DELETE ON public.invoice_exceptions
    FOR EACH ROW EXECUTE FUNCTION public.enforce_invoice_exception_no_delete();
DROP TRIGGER IF EXISTS no_truncate ON public.invoice_exceptions;
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.invoice_exceptions
    FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete();

-- Lineage: invoice_events (enum extended).
ALTER TABLE public.invoice_events DROP CONSTRAINT IF EXISTS invoice_events_event_type_check;
ALTER TABLE public.invoice_events ADD CONSTRAINT invoice_events_event_type_check CHECK ((event_type = ANY (ARRAY[
    'created'::text, 'sent'::text, 'held'::text, 'released_from_hold'::text, 'voided'::text, 'void_attempted_blocked'::text,
    'correction_initiated'::text, 'correction_posted'::text, 'payment_applied'::text, 'written_off'::text, 'status_changed'::text,
    'reversal_chain_depth_exceeded'::text, 'exception_raised'::text, 'exception_resolved'::text, 'exception_overridden'::text])));

CREATE OR REPLACE FUNCTION public.log_invoice_exception_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.invoice_events (tenant_id, invoice_id, event_type, operator_id, occurred_at, metadata)
        VALUES (NEW.tenant_id, NEW.invoice_id, 'exception_raised', NEW.raised_by_user_id, NEW.detected_at,
                jsonb_build_object('invoice_exception_id', NEW.id, 'criterion', NEW.criterion, 'severity', NEW.severity,
                                   'queue', NEW.queue, 'blocks_delivery', NEW.blocks_delivery, 'routing_reason', NEW.routing_reason));
    ELSIF OLD.status = 'open' AND NEW.status IN ('resolved', 'overridden') THEN
        INSERT INTO public.invoice_events (tenant_id, invoice_id, event_type, operator_id, occurred_at, metadata)
        VALUES (NEW.tenant_id, NEW.invoice_id, CASE WHEN NEW.status = 'resolved' THEN 'exception_resolved' ELSE 'exception_overridden' END,
                NEW.resolved_by, NEW.resolved_at,
                jsonb_build_object('invoice_exception_id', NEW.id, 'criterion', NEW.criterion, 'blocks_delivery', NEW.blocks_delivery,
                                   'resolution_reason_code', NEW.resolution_reason_code, 'resolution_notes', NEW.resolution_notes));
    END IF;
    RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS z_log_invoice_exception_event ON public.invoice_exceptions;
CREATE TRIGGER z_log_invoice_exception_event AFTER INSERT OR UPDATE ON public.invoice_exceptions
    FOR EACH ROW EXECUTE FUNCTION public.log_invoice_exception_event();

-- ----------------------------------------------------------------------------
-- 7. The pre-delivery gate on invoices (CI-115)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_invoice_predelivery_gate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_gated boolean := false;
    v_what text;
    v_criteria text;
BEGIN
    IF NEW.status = 'pending' AND OLD.status IN ('draft', 'held') THEN v_gated := true; v_what := 'enter pending'; END IF;
    IF NEW.status = 'sent' AND OLD.status <> 'sent' THEN v_gated := true; v_what := 'enter sent'; END IF;
    IF NEW.sent_at IS NOT NULL AND OLD.sent_at IS NULL THEN v_gated := true; v_what := 'be stamped sent_at'; END IF;
    IF NEW.delivery_confirmed_at IS NOT NULL AND OLD.delivery_confirmed_at IS NULL THEN v_gated := true; v_what := 'be stamped delivery_confirmed_at'; END IF;
    IF NOT v_gated THEN
        RETURN NEW;
    END IF;
    SELECT string_agg(e.criterion || ' (' || e.queue || ')', ', ' ORDER BY e.criterion) INTO v_criteria
      FROM public.invoice_exceptions e
     WHERE e.invoice_id = NEW.id AND e.status = 'open' AND e.blocks_delivery;
    IF v_criteria IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s cannot %s: open delivery-blocking exception(s) %s must be resolved or overridden with a reason code first (CI-115 pre-delivery control gate)', NEW.invoice_number, v_what, v_criteria),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_invoice_predelivery_gate() IS
    'CI-115 (v5.4.2-05): an invoice with an open invoice_exceptions row where blocks_delivery = true may not enter pending (from draft or held), enter sent, or be stamped sent_at / delivery_confirmed_at. Holding is the workflow''s write (A-4 forbids pending → held, so hold before release); this gate makes the hold non-optional.';

DROP TRIGGER IF EXISTS enforce_invoice_predelivery_gate ON public.invoices;
CREATE TRIGGER enforce_invoice_predelivery_gate BEFORE UPDATE ON public.invoices
    FOR EACH ROW EXECUTE FUNCTION public.enforce_invoice_predelivery_gate();

-- ----------------------------------------------------------------------------
-- 8. CI-014 set, privileges, ENABLE ALWAYS
-- ----------------------------------------------------------------------------
DROP TRIGGER IF EXISTS no_hard_delete ON public.read_validation_exceptions;
CREATE TRIGGER no_hard_delete BEFORE DELETE ON public.read_validation_exceptions
    FOR EACH ROW EXECUTE FUNCTION public.enforce_no_hard_delete();
DROP TRIGGER IF EXISTS no_truncate ON public.read_validation_exceptions;
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.read_validation_exceptions
    FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete();
REVOKE DELETE ON public.read_validation_exceptions FROM tally_app;
REVOKE DELETE ON public.invoice_exceptions FROM tally_app;

DO $$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT c.relname, t.tgname
        FROM pg_trigger t
        JOIN pg_class c ON c.oid = t.tgrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public'
          AND NOT t.tgisinternal
          AND t.tgenabled <> 'A'
          AND (
                (c.relname IN ('read_validation_exceptions', 'invoice_exceptions')
                 AND t.tgname IN ('no_hard_delete', 'no_truncate', 'a_enforce_read_validation_exception',
                                  'a_enforce_invoice_exception', 'z_log_invoice_exception_event'))
             OR (c.relname = 'meters' AND t.tgname = 'enforce_meter_estimate_counter')
             OR (c.relname = 'meter_readings' AND t.tgname IN ('z_enforce_read_exception_gate', 'z_raise_consecutive_estimate_exception'))
             OR (c.relname = 'billing_run_meters' AND t.tgname = 'enforce_billing_run_meter_gate')
             OR (c.relname = 'invoices' AND t.tgname = 'enforce_invoice_predelivery_gate')
          )
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I', r.relname, r.tgname);
    END LOOP;
END;
$$;

-- ----------------------------------------------------------------------------
-- 9. Cross-references on existing objects
-- ----------------------------------------------------------------------------
COMMENT ON COLUMN public.invoices.hold_reason IS
    'Why the invoice is held (required when status = held). Since v5.4.2-05 the pre-mail queue is invoice_exceptions: an open row with blocks_delivery = true prevents the release to pending and the transition to sent regardless of this text (CI-115).';
COMMENT ON COLUMN public.billing_run_meters.outcome IS
    'Phase-1 disposition of the meter in this run (decision table #30). Since v5.4.2-05, billed / billed_estimated are refused while the read has an open read_validation_exceptions row (CI-112) or the meter master is incomplete (CI-023, meter_master_incomplete_reasons()).';
-- ============================================================================
-- MIRROR: PATCH v5.4.2-06 — A-21: account lifecycle state-events, date-effective account attributes, deposit / interest ledger (Phase 4 Wave 2; CI-121/125/129/130/131)
-- Appended 2026-08-28; source of truth: sql/v5.4.2-06-account-lifecycle-and-deposits.sql
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Tenant-bound identity for composite FKs
-- ----------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['customers', 'payments', 'customer_credits', 'account_ledger'] LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = t || '_id_tenant_id_key' AND conrelid = ('public.' || t)::regclass) THEN
            EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I UNIQUE (id, tenant_id)', t, t || '_id_tenant_id_key');
        END IF;
    END LOOP;
END;
$$;

-- ----------------------------------------------------------------------------
-- 2. Account lifecycle state events (CI-121)
-- ----------------------------------------------------------------------------
ALTER TABLE public.customers
    ADD COLUMN IF NOT EXISTS status_reason text,
    ADD COLUMN IF NOT EXISTS status_changed_at timestamp with time zone,
    ADD COLUMN IF NOT EXISTS status_changed_by uuid;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'customers_status_changed_by_fkey' AND conrelid = 'public.customers'::regclass) THEN
        ALTER TABLE public.customers ADD CONSTRAINT customers_status_changed_by_fkey FOREIGN KEY (status_changed_by) REFERENCES public.users(id);
    END IF;
END;
$$;

COMMENT ON COLUMN public.customers.status_reason IS 'Write-only (v5.4.2-06, CI-121): required (non-blank) on the UPDATE that changes status; consumed into customer_state_events.reason_code and cleared, so it never lingers for the next transition. Free text until a reason catalogue exists.';
COMMENT ON COLUMN public.customers.status_changed_at IS 'Server-stamped (clock_timestamp(), so events in one transaction stay ordered) on every status change (v5.4.2-06); caller values replaced.';

CREATE TABLE IF NOT EXISTS public.customer_state_events (
    id              uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id       uuid NOT NULL,
    customer_id     uuid NOT NULL,
    from_status     text,
    to_status       text NOT NULL,
    effective_at    timestamp with time zone NOT NULL,
    reason_code     text NOT NULL,
    changed_by      uuid,
    source          text DEFAULT 'operator' NOT NULL,
    created_at      timestamp with time zone DEFAULT now() NOT NULL,
    seq             bigint GENERATED ALWAYS AS IDENTITY,
    CONSTRAINT customer_state_events_pkey PRIMARY KEY (id),
    CONSTRAINT customer_state_events_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT customer_state_events_customer_fkey FOREIGN KEY (customer_id, tenant_id) REFERENCES public.customers(id, tenant_id),
    CONSTRAINT customer_state_events_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES public.users(id),
    CONSTRAINT customer_state_events_to_status_check CHECK (to_status = ANY (ARRAY['active'::text, 'inactive'::text, 'final_billed'::text, 'collections'::text, 'closed'::text])),
    CONSTRAINT customer_state_events_from_status_check CHECK (from_status IS NULL OR from_status = ANY (ARRAY['active'::text, 'inactive'::text, 'final_billed'::text, 'collections'::text, 'closed'::text])),
    CONSTRAINT customer_state_events_source_check CHECK (source = ANY (ARRAY['operator'::text, 'system'::text, 'initial'::text, 'backfill'::text])),
    CONSTRAINT customer_state_events_reason_check CHECK (reason_code IS NOT NULL AND length(btrim(reason_code)) > 0)
);
CREATE INDEX IF NOT EXISTS idx_customer_state_events_customer ON public.customer_state_events USING btree (customer_id, effective_at DESC);
CREATE INDEX IF NOT EXISTS idx_customer_state_events_tenant ON public.customer_state_events USING btree (tenant_id);
ALTER TABLE public.customer_state_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_state_events FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.customer_state_events;
CREATE POLICY tenant_isolation ON public.customer_state_events USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));
COMMENT ON TABLE public.customer_state_events IS
    'CI-121 (v5.4.2-06, A-21): the account state-transition log. Written by the database on every INSERT of a customer (source initial) and every change of customers.status (reason from customers.status_reason, actor from status_changed_by, effective_at = server clock); one backfill row per pre-existing customer at created_at. Append-only. customer_status_as_of() reads it.';

CREATE OR REPLACE FUNCTION public.customer_status_as_of(p_customer_id uuid, p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$
    SELECT e.to_status FROM public.customer_state_events e
     WHERE e.customer_id = p_customer_id AND e.effective_at <= p_at
     ORDER BY e.effective_at DESC, e.seq DESC LIMIT 1
$$;
COMMENT ON FUNCTION public.customer_status_as_of(uuid, timestamp with time zone) IS 'CI-121: the account status in force at p_at per customer_state_events; NULL before recorded history (never the current value). p_at is required.';

CREATE OR REPLACE FUNCTION public.enforce_customer_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.status_changed_at := clock_timestamp();
        PERFORM public.assert_same_tenant_user(NEW.status_changed_by, NEW.tenant_id, 'status_changed_by');
        -- The reason for the initial state is the creation itself; the row
        -- never carries a reason forward (a later transition must supply its own).
        NEW.status_reason := NULL;
        RETURN NEW;
    END IF;
    IF OLD.status IS DISTINCT FROM NEW.status THEN
        IF NEW.status_reason IS NULL OR length(btrim(NEW.status_reason)) = 0 THEN
            RAISE EXCEPTION USING
                MESSAGE = format('customer %s: status %s -> %s requires status_reason (CI-121: every transition is a reason-coded event)', OLD.customer_number, OLD.status, NEW.status),
                ERRCODE = 'check_violation';
        END IF;
        IF OLD.status = 'closed' AND NEW.status <> 'active' THEN
            RAISE EXCEPTION USING
                MESSAGE = format('customer %s: closed reopens only to active, not %s (CI-121)', OLD.customer_number, NEW.status),
                ERRCODE = 'check_violation';
        END IF;
        IF NEW.status = 'closed' AND EXISTS (SELECT 1 FROM public.deposits d WHERE d.customer_id = OLD.id AND d.status IN ('held', 'partial_applied', 'applied', 'refund_pending')) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('customer %s cannot be closed while a deposit is held, applied but not settled, or a refund is pending (CI-131 / customer-move-out Exc 2): record the refund (a zero refund when fully applied) or release the instrument first', OLD.customer_number),
                ERRCODE = 'check_violation';
        END IF;
        PERFORM public.assert_same_tenant_user(NEW.status_changed_by, OLD.tenant_id, 'status_changed_by');
        NEW.status_changed_at := clock_timestamp();   -- ordered even within one transaction
        -- The event is the record; written here so the reason cannot linger on
        -- the row and be reused by the next transition (Fable round 1, M5).
        INSERT INTO public.customer_state_events (tenant_id, customer_id, from_status, to_status, effective_at, reason_code, changed_by, source)
        VALUES (OLD.tenant_id, OLD.id, OLD.status, NEW.status, NEW.status_changed_at, NEW.status_reason, NEW.status_changed_by, 'operator');
        NEW.status_reason := NULL;
        NEW.status_changed_by := NULL;
    ELSE
        -- No transition: nothing to record; a reason supplied without a change is dropped.
        NEW.status_reason := NULL;
        NEW.status_changed_by := OLD.status_changed_by;
        NEW.status_changed_at := coalesce(OLD.status_changed_at, NEW.status_changed_at);
    END IF;
    RETURN NEW;
END;
$$;
COMMENT ON FUNCTION public.enforce_customer_lifecycle() IS 'CI-121 guard on customers (v5.4.2-06): a status change needs status_reason and is written to customer_state_events by this trigger (the reason and actor are consumed into the event and never linger on the row); closed reopens only to active; closed is refused while a deposit is held / partially applied / applied-unsettled / refund pending; status_changed_at is the server''s (clock_timestamp()).';

-- (the lifecycle trigger is created after the backfill, section 10, so the
--  backfill can stamp status_changed_at on legacy rows)

CREATE OR REPLACE FUNCTION public.log_customer_state_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    INSERT INTO public.customer_state_events (tenant_id, customer_id, from_status, to_status, effective_at, reason_code, changed_by, source)
    VALUES (NEW.tenant_id, NEW.id, NULL, NEW.status, NEW.status_changed_at, 'account created', NEW.status_changed_by, 'initial');
    RETURN NULL;
END;
$$;
COMMENT ON FUNCTION public.log_customer_state_event() IS 'AFTER INSERT on customers (v5.4.2-06): the initial state event. Transitions are logged by enforce_customer_lifecycle() itself.';
DROP TRIGGER IF EXISTS z_log_customer_state_event ON public.customers;
CREATE TRIGGER z_log_customer_state_event AFTER INSERT ON public.customers
    FOR EACH ROW EXECUTE FUNCTION public.log_customer_state_event();

CREATE OR REPLACE FUNCTION public.enforce_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    RAISE EXCEPTION USING
        MESSAGE = format('%s is append-only (CI-121 / CI-125 / CI-088): a recorded event is never edited or deleted — record a correcting event', TG_TABLE_NAME),
        ERRCODE = 'restrict_violation';
END;
$$;
COMMENT ON FUNCTION public.enforce_append_only() IS 'Generic UPDATE/DELETE refusal for the v5.4.2-06 event tables (customer_state_events, customer_attribute_history, deposit_events, deposit_interest_rates, deposit_waiver_determinations).';

-- ----------------------------------------------------------------------------
-- 3. Date-effective account attributes (CI-121)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.customer_attribute_history (
    id              uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id       uuid NOT NULL,
    customer_id     uuid NOT NULL,
    attribute       text NOT NULL,
    old_value       text,
    new_value       text,
    effective_at    timestamp with time zone NOT NULL,
    changed_by      uuid,
    source          text DEFAULT 'operator' NOT NULL,
    created_at      timestamp with time zone DEFAULT now() NOT NULL,
    seq             bigint GENERATED ALWAYS AS IDENTITY,
    CONSTRAINT customer_attribute_history_pkey PRIMARY KEY (id),
    CONSTRAINT customer_attribute_history_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT customer_attribute_history_customer_fkey FOREIGN KEY (customer_id, tenant_id) REFERENCES public.customers(id, tenant_id),
    CONSTRAINT customer_attribute_history_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES public.users(id),
    CONSTRAINT customer_attribute_history_attribute_check CHECK (attribute = ANY (ARRAY[
        'billing_delivery_method'::text, 'billing_hold'::text, 'consolidate_invoices'::text, 'do_not_disconnect'::text,
        'landlord_responsible'::text, 'customer_type'::text, 'autopay_enabled'::text, 'deposit_status'::text])),
    CONSTRAINT customer_attribute_history_source_check CHECK (source = ANY (ARRAY['operator'::text, 'system'::text, 'initial'::text, 'backfill'::text]))
);
CREATE INDEX IF NOT EXISTS idx_customer_attribute_history_lookup ON public.customer_attribute_history USING btree (customer_id, attribute, effective_at DESC);
CREATE INDEX IF NOT EXISTS idx_customer_attribute_history_tenant ON public.customer_attribute_history USING btree (tenant_id);
ALTER TABLE public.customer_attribute_history ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.customer_attribute_history FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.customer_attribute_history;
CREATE POLICY tenant_isolation ON public.customer_attribute_history USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));
COMMENT ON TABLE public.customer_attribute_history IS
    'CI-121 mid-state values (v5.4.2-06, A-21): every change of the account attributes billing and collections key on, written by the database (customers: billing_delivery_method, billing_hold, consolidate_invoices, do_not_disconnect, landlord_responsible, customer_type; auto_pay_settings: autopay_enabled; deposits projection: deposit_status). One backfill row per attribute per pre-existing customer at created_at. Append-only. customer_attribute_as_of() reads it.';

CREATE OR REPLACE FUNCTION public.customer_attribute_as_of(p_customer_id uuid, p_attribute text, p_at timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$
    SELECT h.new_value FROM public.customer_attribute_history h
     WHERE h.customer_id = p_customer_id AND h.attribute = p_attribute AND h.effective_at <= p_at
     ORDER BY h.effective_at DESC, h.seq DESC LIMIT 1
$$;
COMMENT ON FUNCTION public.customer_attribute_as_of(uuid, text, timestamp with time zone) IS 'CI-121: the attribute value in force at p_at (text; cast at the call site). NULL before recorded history — never the current value.';

CREATE OR REPLACE FUNCTION public.log_customer_attribute_changes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, source)
        SELECT NEW.tenant_id, NEW.id, a.attribute, NULL,
               CASE a.attribute
                   WHEN 'billing_delivery_method' THEN NEW.billing_delivery_method
                   WHEN 'billing_hold' THEN NEW.billing_hold::text
                   WHEN 'consolidate_invoices' THEN NEW.consolidate_invoices::text
                   WHEN 'do_not_disconnect' THEN NEW.do_not_disconnect::text
                   WHEN 'landlord_responsible' THEN NEW.landlord_responsible::text
                   WHEN 'customer_type' THEN NEW.customer_type
                   WHEN 'deposit_status' THEN NEW.deposit_status
                   WHEN 'autopay_enabled' THEN 'false'
               END,
               NEW.status_changed_at, 'initial'
          FROM (SELECT unnest(ARRAY['billing_delivery_method', 'billing_hold', 'consolidate_invoices', 'do_not_disconnect', 'landlord_responsible', 'customer_type', 'deposit_status', 'autopay_enabled']) AS attribute) a;
        RETURN NULL;
    END IF;
    IF OLD.billing_delivery_method IS DISTINCT FROM NEW.billing_delivery_method THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'billing_delivery_method', OLD.billing_delivery_method, NEW.billing_delivery_method, clock_timestamp());
    END IF;
    IF OLD.billing_hold IS DISTINCT FROM NEW.billing_hold THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, changed_by) VALUES (NEW.tenant_id, NEW.id, 'billing_hold', OLD.billing_hold::text, NEW.billing_hold::text, clock_timestamp(), NEW.billing_hold_set_by);
    END IF;
    IF OLD.consolidate_invoices IS DISTINCT FROM NEW.consolidate_invoices THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'consolidate_invoices', OLD.consolidate_invoices::text, NEW.consolidate_invoices::text, clock_timestamp());
    END IF;
    IF OLD.do_not_disconnect IS DISTINCT FROM NEW.do_not_disconnect THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'do_not_disconnect', OLD.do_not_disconnect::text, NEW.do_not_disconnect::text, clock_timestamp());
    END IF;
    IF OLD.landlord_responsible IS DISTINCT FROM NEW.landlord_responsible THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'landlord_responsible', OLD.landlord_responsible::text, NEW.landlord_responsible::text, clock_timestamp());
    END IF;
    IF OLD.customer_type IS DISTINCT FROM NEW.customer_type THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'customer_type', OLD.customer_type, NEW.customer_type, clock_timestamp());
    END IF;
    IF OLD.deposit_status IS DISTINCT FROM NEW.deposit_status THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, source) VALUES (NEW.tenant_id, NEW.id, 'deposit_status', OLD.deposit_status, NEW.deposit_status, clock_timestamp(), 'system');
    END IF;
    RETURN NULL;
END;
$$;
DROP TRIGGER IF EXISTS z_log_customer_attribute_changes ON public.customers;
CREATE TRIGGER z_log_customer_attribute_changes AFTER INSERT OR UPDATE ON public.customers
    FOR EACH ROW EXECUTE FUNCTION public.log_customer_attribute_changes();

CREATE OR REPLACE FUNCTION public.log_autopay_attribute_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at)
        VALUES (NEW.tenant_id, NEW.customer_id, 'autopay_enabled', NULL, NEW.enabled::text, clock_timestamp());
    ELSIF OLD.enabled IS DISTINCT FROM NEW.enabled OR OLD.customer_id <> NEW.customer_id THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at)
        VALUES (NEW.tenant_id, NEW.customer_id, 'autopay_enabled', OLD.enabled::text, NEW.enabled::text, clock_timestamp());
    END IF;
    RETURN NULL;
END;
$$;
DROP TRIGGER IF EXISTS z_log_autopay_attribute_change ON public.auto_pay_settings;
CREATE TRIGGER z_log_autopay_attribute_change AFTER INSERT OR UPDATE ON public.auto_pay_settings
    FOR EACH ROW EXECUTE FUNCTION public.log_autopay_attribute_change();

-- ----------------------------------------------------------------------------
-- 4. deposit_interest_rates (CI-125 / CI-130; Kyle 2026-06-12)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.deposit_interest_rates (
    id                  uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id           uuid NOT NULL,
    effective_date      date NOT NULL,
    annual_rate         numeric(8,6) NOT NULL,
    source_reference    text,
    notes               text,
    created_by          uuid,
    created_at          timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT deposit_interest_rates_pkey PRIMARY KEY (id),
    CONSTRAINT deposit_interest_rates_tenant_effective_key UNIQUE (tenant_id, effective_date),
    CONSTRAINT deposit_interest_rates_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT deposit_interest_rates_created_by_fkey FOREIGN KEY (created_by) REFERENCES public.users(id),
    CONSTRAINT deposit_interest_rates_rate_check CHECK (annual_rate >= 0 AND annual_rate <= 1)
);
ALTER TABLE public.deposit_interest_rates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.deposit_interest_rates FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.deposit_interest_rates;
CREATE POLICY tenant_isolation ON public.deposit_interest_rates USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));
CREATE OR REPLACE FUNCTION public.enforce_deposit_interest_rate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE v_settled date;
BEGIN
    PERFORM public.assert_same_tenant_user(NEW.created_by, NEW.tenant_id, 'created_by');
    NEW.created_at := now();
    SELECT max(e.period_end) INTO v_settled
      FROM public.deposit_events e JOIN public.deposits d ON d.id = e.deposit_id
     WHERE d.tenant_id = NEW.tenant_id AND e.event_type = 'interest_accrued';
    IF v_settled IS NOT NULL AND NEW.effective_date <= v_settled THEN
        RAISE EXCEPTION USING
            MESSAGE = format('deposit interest rate effective %s rejected: interest has already been accrued through %s at the rates then in force; a settled accrual is never re-rated (CI-125 / CI-130) — a correction is a new accrual period at the new rate from %s', NEW.effective_date, v_settled, v_settled + 1),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS a_enforce_deposit_interest_rate ON public.deposit_interest_rates;
CREATE TRIGGER a_enforce_deposit_interest_rate BEFORE INSERT ON public.deposit_interest_rates
    FOR EACH ROW EXECUTE FUNCTION public.enforce_deposit_interest_rate();

COMMENT ON TABLE public.deposit_interest_rates IS
    'CI-125 / CI-130 (v5.4.2-06, Kyle 2026-06-12): the effective-dated deposit interest rate per tenant (annual, as a fraction — 0.0287 = 2.87%; the PUCT-set rate for a Texas tenant). A new rate is a new row; rows are never edited or deleted. deposit_interest_rate_as_of() raises when no row covers a date.';

CREATE OR REPLACE FUNCTION public.deposit_interest_rate_as_of(p_tenant_id uuid, p_on date) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
DECLARE v numeric;
BEGIN
    IF p_on IS NULL THEN
        RAISE EXCEPTION USING MESSAGE = 'deposit_interest_rate_as_of: p_on is required', ERRCODE = 'null_value_not_allowed';
    END IF;
    SELECT r.annual_rate INTO v FROM public.deposit_interest_rates r
     WHERE r.tenant_id = p_tenant_id AND r.effective_date <= p_on
     ORDER BY r.effective_date DESC LIMIT 1;
    IF v IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = format('no deposit interest rate is in force for tenant %s on %s (CI-125: the rate is date-effective; there is no fallback)', p_tenant_id, p_on),
            ERRCODE = 'no_data_found';
    END IF;
    RETURN v;
END;
$$;
COMMENT ON FUNCTION public.deposit_interest_rate_as_of(uuid, date) IS 'The annual deposit interest rate in force on p_on for the tenant; RAISES when none (never a fallback). Invoker rights: RLS applies.';

CREATE OR REPLACE FUNCTION public.deposit_accrual_amount(p_principal numeric, p_annual_rate numeric, p_period_start date, p_period_end date) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path = public, pg_temp
    AS $$
    SELECT round(p_principal * p_annual_rate * ((p_period_end - p_period_start + 1)::numeric / 365), 2)
$$;
COMMENT ON FUNCTION public.deposit_accrual_amount(numeric, numeric, date, date) IS 'Simple interest for an inclusive day range: principal × annual_rate × days/365, rounded to cents. The deposit_events guard requires every interest_accrued event to carry exactly this amount for its period, rate and principal basis.';

-- ----------------------------------------------------------------------------
-- 5. deposit_waiver_determinations (CI-129)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.deposit_waiver_determinations (
    id                          uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id                   uuid NOT NULL,
    customer_id                 uuid NOT NULL,
    waiver_class                text NOT NULL,
    determined_on               date NOT NULL,
    certification_reference     text,
    certification_expires_on    date,
    determined_by               uuid,
    notes                       text,
    created_at                  timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT deposit_waiver_determinations_pkey PRIMARY KEY (id),
    CONSTRAINT deposit_waiver_determinations_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT deposit_waiver_determinations_customer_fkey FOREIGN KEY (customer_id, tenant_id) REFERENCES public.customers(id, tenant_id),
    CONSTRAINT deposit_waiver_determinations_determined_by_fkey FOREIGN KEY (determined_by) REFERENCES public.users(id),
    CONSTRAINT deposit_waiver_determinations_class_check CHECK (waiver_class = ANY (ARRAY['family_violence_certified'::text, 'age_65_no_balance'::text, 'good_payment_history'::text, 'tariff'::text])),
    CONSTRAINT deposit_waiver_determinations_certification_check CHECK (waiver_class <> 'family_violence_certified' OR (certification_reference IS NOT NULL AND length(btrim(certification_reference)) > 0)),
    CONSTRAINT deposit_waiver_determinations_expiry_check CHECK (certification_expires_on IS NULL OR certification_expires_on >= determined_on)
);
CREATE INDEX IF NOT EXISTS idx_deposit_waiver_determinations_customer ON public.deposit_waiver_determinations USING btree (customer_id);
CREATE INDEX IF NOT EXISTS idx_deposit_waiver_determinations_tenant ON public.deposit_waiver_determinations USING btree (tenant_id);
ALTER TABLE public.deposit_waiver_determinations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.deposit_waiver_determinations FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.deposit_waiver_determinations;
CREATE POLICY tenant_isolation ON public.deposit_waiver_determinations USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));
COMMENT ON TABLE public.deposit_waiver_determinations IS
    'CI-129 (v5.4.2-06): a recorded deposit-waiver determination — 16 TAC §7.45 family-violence certification (Texas Council on Family Violence reference required), age-65-with-no-balance, good-payment-history, or a tariff class — with the determination date and the certification''s expiry. A §7.45-basis deposit cannot be posted for a customer with an unexpired determination (table #53 ranks 0–3; #55 rule 8). Append-only. SENSITIVE: the family-violence class is among the most sensitive data the platform holds; RLS applies, no column-level control exists (flagged).';

-- ----------------------------------------------------------------------------
-- 6. deposits (CI-077 / CI-129 / CI-131)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.deposits (
    id                          uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id                   uuid NOT NULL,
    customer_id                 uuid NOT NULL,
    basis                       text NOT NULL,
    trigger_basis               text,
    instrument                  text DEFAULT 'cash' NOT NULL,
    principal                   numeric(12,2) NOT NULL,
    posted_on                   date NOT NULL,
    source_payment_id           uuid,
    cap_amount                  numeric(12,2),
    cap_basis_annual_billing    numeric(12,2),
    cap_binding                 boolean DEFAULT false NOT NULL,
    instrument_issuer           text,
    instrument_reference        text,
    instrument_expires_on       date,
    status                      text DEFAULT 'held' NOT NULL,
    refund_eligibility_on       date,
    refunded_on                 date,
    released_on                 date,
    legacy_interest_earned      numeric(12,2),
    notes                       text,
    created_by                  uuid,
    created_at                  timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT deposits_pkey PRIMARY KEY (id),
    CONSTRAINT deposits_id_tenant_id_key UNIQUE (id, tenant_id),
    CONSTRAINT deposits_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT deposits_customer_fkey FOREIGN KEY (customer_id, tenant_id) REFERENCES public.customers(id, tenant_id),
    CONSTRAINT deposits_source_payment_fkey FOREIGN KEY (source_payment_id, tenant_id) REFERENCES public.payments(id, tenant_id),
    CONSTRAINT deposits_created_by_fkey FOREIGN KEY (created_by) REFERENCES public.users(id),
    CONSTRAINT deposits_basis_check CHECK (basis = ANY (ARRAY['credit_evaluation'::text, 'adequate_assurance_366'::text, 'additional_trigger'::text, 'tariff'::text, 'legacy_unknown'::text])),
    CONSTRAINT deposits_trigger_basis_check CHECK (trigger_basis IS NULL OR trigger_basis = ANY (ARRAY['nsf'::text, 'disconnect_history'::text, 'broken_dpa'::text])),
    CONSTRAINT deposits_trigger_basis_required_check CHECK ((basis = 'additional_trigger') = (trigger_basis IS NOT NULL)),
    CONSTRAINT deposits_instrument_check CHECK (instrument = ANY (ARRAY['cash'::text, 'letter_of_credit'::text, 'certificate_of_deposit'::text, 'surety_bond'::text, 'prepayment'::text, 'guarantor'::text, 'other_agreed'::text])),
    CONSTRAINT deposits_principal_check CHECK (principal > 0),
    CONSTRAINT deposits_cap_check CHECK (cap_amount IS NULL OR (cap_amount > 0 AND principal <= cap_amount)),
    CONSTRAINT deposits_cap_binding_check CHECK (NOT cap_binding OR (cap_amount IS NOT NULL AND principal = cap_amount)),
    CONSTRAINT deposits_cap_basis_check CHECK (cap_basis_annual_billing IS NULL OR cap_basis_annual_billing > 0),
    CONSTRAINT deposits_instrument_fields_check CHECK (
        (instrument = 'cash' AND instrument_issuer IS NULL AND instrument_reference IS NULL AND instrument_expires_on IS NULL)
     OR (instrument <> 'cash' AND instrument_reference IS NOT NULL AND length(btrim(instrument_reference)) > 0)),
    CONSTRAINT deposits_status_check CHECK (status = ANY (ARRAY['held'::text, 'partial_applied'::text, 'applied'::text, 'refund_pending'::text, 'refunded'::text, 'released'::text])),
    CONSTRAINT deposits_status_dates_check CHECK (
        (status = 'refunded') = (refunded_on IS NOT NULL) AND (status = 'released') = (released_on IS NOT NULL)),
    CONSTRAINT deposits_released_noncash_check CHECK (status <> 'released' OR instrument <> 'cash'),
    CONSTRAINT deposits_legacy_interest_check CHECK (legacy_interest_earned IS NULL OR basis = 'legacy_unknown')
);
CREATE INDEX IF NOT EXISTS idx_deposits_customer ON public.deposits USING btree (customer_id);
CREATE INDEX IF NOT EXISTS idx_deposits_tenant_open ON public.deposits USING btree (tenant_id, status) WHERE (status = ANY (ARRAY['held'::text, 'partial_applied'::text, 'applied'::text, 'refund_pending'::text]));
CREATE INDEX IF NOT EXISTS idx_deposits_source_payment ON public.deposits USING btree (source_payment_id) WHERE (source_payment_id IS NOT NULL);
ALTER TABLE public.deposits ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.deposits FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.deposits;
CREATE POLICY tenant_isolation ON public.deposits USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));
COMMENT ON TABLE public.deposits IS
    'A-21 (v5.4.2-06): one record per deposit — the substrate CI-077 / CI-125 / CI-129–131 and decision tables #53–#55 found missing. basis (which rule governs its refund: §7.45 credit_evaluation / additional_trigger / tariff refund on CI-131''s triggers; adequate_assurance_366 never does; legacy_unknown = carried from customers.deposit_* at patch time, not insertable now), instrument (only cash accrues interest; non-cash carries issuer/reference/expiry), principal, posted_on, the §7.45 cap as recorded at the decision (required for a Texas residential §7.45 deposit; principal ≤ cap; cap_binding when it bit). Identity is frozen after insert. status / refunded_on / released_on are a PROJECTION of deposit_events (direct writes rejected): held → partial_applied (applied_to_balance) → refund_pending (refund_initiated) → refunded (refunded); non-cash → released. customers.deposit_* mirror the deposits (database-maintained).';
COMMENT ON COLUMN public.deposits.cap_amount IS '1/6 of estimated annual billing as computed at the deposit decision (table #53 rank 8); the customer is entitled to know when it bound (cap_binding). Its derivation (cap_basis_annual_billing) is the application''s — the database records and enforces it.';
COMMENT ON COLUMN public.deposits.refund_eligibility_on IS 'Optional: the date the application computed the twelve-bill trigger would earliest fire, or a tariff-set eligibility date. Informational; deposits_refund_due derives the standing trigger.';

CREATE TABLE IF NOT EXISTS public.deposit_events (
    id                  uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id           uuid NOT NULL,
    deposit_id          uuid NOT NULL,
    event_type          text NOT NULL,
    amount              numeric(12,2) NOT NULL,
    effective_on        date NOT NULL,
    period_start        date,
    period_end          date,
    rate_applied        numeric(8,6),
    principal_basis     numeric(12,2),
    ledger_entry_id     uuid,
    reason              text,
    created_by          uuid,
    source              text DEFAULT 'operator' NOT NULL,
    created_at          timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT deposit_events_pkey PRIMARY KEY (id),
    CONSTRAINT deposit_events_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT deposit_events_deposit_fkey FOREIGN KEY (deposit_id, tenant_id) REFERENCES public.deposits(id, tenant_id),
    CONSTRAINT deposit_events_ledger_fkey FOREIGN KEY (ledger_entry_id, tenant_id) REFERENCES public.account_ledger(id, tenant_id),
    CONSTRAINT deposit_events_created_by_fkey FOREIGN KEY (created_by) REFERENCES public.users(id),
    CONSTRAINT deposit_events_type_check CHECK (event_type = ANY (ARRAY['posted'::text, 'applied_to_balance'::text, 'interest_accrued'::text, 'interest_credited'::text, 'refund_initiated'::text, 'refunded'::text, 'released'::text])),
    CONSTRAINT deposit_events_amount_check CHECK (amount >= 0),
    CONSTRAINT deposit_events_source_check CHECK (source = ANY (ARRAY['operator'::text, 'system'::text, 'backfill'::text])),
    CONSTRAINT deposit_events_accrual_fields_check CHECK (
        (event_type = 'interest_accrued' AND period_start IS NOT NULL AND period_end IS NOT NULL AND period_end >= period_start AND rate_applied IS NOT NULL AND principal_basis IS NOT NULL AND principal_basis > 0)
     OR (event_type <> 'interest_accrued' AND period_start IS NULL AND period_end IS NULL AND rate_applied IS NULL AND principal_basis IS NULL)),
    CONSTRAINT deposit_events_accrual_no_overlap EXCLUDE USING gist (deposit_id WITH =, daterange(period_start, period_end, '[]') WITH &&) WHERE (event_type = 'interest_accrued')
);
CREATE INDEX IF NOT EXISTS idx_deposit_events_deposit ON public.deposit_events USING btree (deposit_id, effective_on);
CREATE INDEX IF NOT EXISTS idx_deposit_events_tenant ON public.deposit_events USING btree (tenant_id);
ALTER TABLE public.deposit_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.deposit_events FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.deposit_events;
CREATE POLICY tenant_isolation ON public.deposit_events USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));
COMMENT ON TABLE public.deposit_events IS
    'CI-125 / CI-130 / CI-131 (v5.4.2-06): the append-only deposit sub-ledger. posted (written by the database at deposit insert), applied_to_balance, interest_accrued (period, rate in force, principal in force, amount = deposit_accrual_amount — cash only, only once held > 30 days, first period starts ON posted_on, periods contiguous, never across a rate change or a principal application, never past the return date), interest_credited (≤ accrued − credited), refund_initiated, refunded (held ≤ 30 days: no accrual may exist; > 30 days: accrual must reach the return date and be credited in full; amount = remainder), released (non-cash). deposits.status is projected from these. Optional link to the account_ledger row that moved the money (same customer/tenant; transaction_type deposit / adjustment / deposit_interest / refund).';

-- account_ledger enum extensions (interest is its own movement; a deposit is a reference)
ALTER TABLE public.account_ledger DROP CONSTRAINT IF EXISTS account_ledger_transaction_type_check;
ALTER TABLE public.account_ledger ADD CONSTRAINT account_ledger_transaction_type_check CHECK ((transaction_type = ANY (ARRAY[
    'charge'::text, 'payment'::text, 'adjustment'::text, 'credit_issued'::text, 'credit_applied'::text, 'late_fee'::text, 'deposit'::text, 'refund'::text,
    'write_off'::text, 'transfer'::text, 'nsf'::text, 'escheat'::text, 'donation'::text, 'void_reversal'::text, 'deposit_interest'::text])));
ALTER TABLE public.account_ledger DROP CONSTRAINT IF EXISTS account_ledger_reference_type_check;
ALTER TABLE public.account_ledger ADD CONSTRAINT account_ledger_reference_type_check CHECK ((reference_type = ANY (ARRAY[
    'invoice'::text, 'payment'::text, 'customer_credit'::text, 'adhoc_charge'::text, 'invoice_application'::text, 'billing_run'::text,
    'escheatment_event'::text, 'manual'::text, 'invoice_void'::text, 'refund'::text, 'deposit'::text])));

-- payments: deposit_status exactly when is_deposit. Legacy rows are
-- reconciled first (reported), then the CHECK is added VALID — a NOT VALID
-- check would still fire on any later UPDATE of the offending row (Fable
-- round 1, H4), freezing legacy payments.
DO $$
DECLARE v bigint;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'payments_deposit_status_consistent_check' AND conrelid = 'public.payments'::regclass) THEN
        PERFORM set_config('search_path', 'public, pg_temp', true);
        UPDATE public.payments p SET deposit_status = NULL WHERE NOT coalesce(p.is_deposit, false) AND p.deposit_status IS NOT NULL;
        GET DIAGNOSTICS v = ROW_COUNT;
        IF v > 0 THEN RAISE NOTICE 'v5.4.2-06: deposit_status cleared on % payments row(s) not flagged is_deposit', v; END IF;
        UPDATE public.payments p
           SET deposit_status = CASE coalesce(c.deposit_status, 'none')
                                    WHEN 'held' THEN 'held' WHEN 'partial_applied' THEN 'partial_applied' WHEN 'refund_pending' THEN 'held'
                                    WHEN 'applied' THEN 'applied' ELSE 'refunded' END
          FROM public.customers c
         WHERE c.id = p.customer_id AND coalesce(p.is_deposit, false) AND p.deposit_status IS NULL;
        GET DIAGNOSTICS v = ROW_COUNT;
        IF v > 0 THEN RAISE NOTICE 'v5.4.2-06: deposit_status set on % is_deposit payments row(s) from the customer''s deposit status at patch time (approximation)', v; END IF;
        ALTER TABLE public.payments ADD CONSTRAINT payments_deposit_status_consistent_check
            CHECK ((coalesce(is_deposit, false)) = (deposit_status IS NOT NULL));
    END IF;
END;
$$;

-- customer_credits: a deposit refund names its deposit. Enforced by a
-- trigger on INSERT and on a change of origin_type / deposit_id — legacy
-- rows stay updatable (Fable round 1, H4); the backfill links them where the
-- customer has exactly one legacy deposit.
ALTER TABLE public.customer_credits ADD COLUMN IF NOT EXISTS deposit_id uuid;
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'customer_credits_deposit_fkey' AND conrelid = 'public.customer_credits'::regclass) THEN
        ALTER TABLE public.customer_credits ADD CONSTRAINT customer_credits_deposit_fkey FOREIGN KEY (deposit_id, tenant_id) REFERENCES public.deposits(id, tenant_id);
    END IF;
END;
$$;
CREATE OR REPLACE FUNCTION public.enforce_customer_credit_deposit_lineage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF NEW.origin_type = 'deposit_refund' AND NEW.deposit_id IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'customer_credits: a deposit_refund credit must name the deposit it returns (deposit_id) — its interest is a separate deposit_events.interest_credited movement',
            ERRCODE = 'check_violation';
    END IF;
    IF NEW.deposit_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.deposits d WHERE d.id = NEW.deposit_id AND d.customer_id = NEW.customer_id) THEN
        RAISE EXCEPTION USING MESSAGE = 'customer_credits: deposit_id must name a deposit of the same customer', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS enforce_customer_credit_deposit_lineage ON public.customer_credits;
CREATE TRIGGER enforce_customer_credit_deposit_lineage BEFORE INSERT OR UPDATE OF origin_type, deposit_id ON public.customer_credits
    FOR EACH ROW EXECUTE FUNCTION public.enforce_customer_credit_deposit_lineage();
COMMENT ON COLUMN public.customer_credits.deposit_id IS 'v5.4.2-06: the deposit a deposit_refund credit returns (required for that origin on INSERT and when origin_type/deposit_id change; legacy rows were linked where the customer had exactly one legacy deposit, else left NULL and reported). The interest component is a separate deposit_events.interest_credited / account_ledger deposit_interest movement, not folded into the credit.';

-- ----------------------------------------------------------------------------
-- 7. Derivations
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.deposit_balance(p_deposit_id uuid)
    RETURNS TABLE (principal numeric, applied numeric, remainder numeric, interest_accrued numeric, interest_credited numeric, days_held integer, accrued_through date, exhausted_on date)
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$
    SELECT d.principal,
           coalesce((SELECT sum(e.amount) FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'applied_to_balance'), 0),
           d.principal - coalesce((SELECT sum(e.amount) FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'applied_to_balance'), 0),
           coalesce((SELECT sum(e.amount) FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'interest_accrued'), 0),
           coalesce((SELECT sum(e.amount) FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'interest_credited'), 0),
           (coalesce(d.refunded_on, d.released_on, CURRENT_DATE) - d.posted_on)::integer,
           (SELECT max(e.period_end) FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'interest_accrued'),
           -- the first day on which cumulative applications reached the principal (NULL while any remains)
           (SELECT min(x.effective_on) FROM (
                SELECT e.effective_on, sum(e.amount) OVER (ORDER BY e.effective_on, e.created_at, e.id) AS cum
                  FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'applied_to_balance') x
             WHERE x.cum >= d.principal)
    FROM public.deposits d WHERE d.id = p_deposit_id
$$;
COMMENT ON FUNCTION public.deposit_balance(uuid) IS 'Derived from deposit_events (never stored): principal, applied to balance, remainder, interest accrued, interest credited, days held (to refund/release/today), accrued-through date, exhausted_on (the day applications consumed the whole principal — interest is owed through the day before it).';

CREATE OR REPLACE FUNCTION public.deposit_principal_in_force(p_deposit_id uuid, p_on date) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$
    SELECT d.principal - coalesce((SELECT sum(e.amount) FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'applied_to_balance' AND e.effective_on <= p_on), 0)
    FROM public.deposits d WHERE d.id = p_deposit_id
$$;
COMMENT ON FUNCTION public.deposit_principal_in_force(uuid, date) IS 'Principal on which interest accrues on p_on: principal less applications effective on or before that day — an application reduces the basis from its own date forward (accrual-cycle Alt 3).';

CREATE OR REPLACE FUNCTION public.deposit_refund_trigger_state(p_deposit_id uuid)
    RETURNS TABLE (consecutive_paid_bills integer, delinquent_occasions integer, currently_delinquent boolean, twelve_bill_trigger_met boolean)
    LANGUAGE sql STABLE
    SET search_path = public, pg_temp
    AS $$
    -- Bills issued since posting, newest first. "Paid clean": status paid with
    -- no balance and never past dunning_stage current/resolved. Delinquent
    -- occasion: a bill that entered any dunning stage beyond current, or is
    -- overdue. Approximation of §7.45's "paid ... without delinquency"
    -- stated in the COMMENT; the workflow is the authority on the payment
    -- history it feeds.
    WITH d AS (SELECT * FROM public.deposits WHERE id = p_deposit_id),
    bills AS (
        SELECT i.id, i.status, i.balance, i.dunning_stage, i.invoice_date,
               (i.status = 'paid' AND i.balance = 0 AND i.dunning_stage IN ('current', 'resolved')) AS paid_clean,
               (i.status = 'overdue' OR i.dunning_stage NOT IN ('current', 'resolved')) AS delinquent,
               row_number() OVER (ORDER BY i.invoice_date DESC, i.created_at DESC) AS rn
        FROM public.invoices i, d
        WHERE i.customer_id = d.customer_id AND i.invoice_date >= d.posted_on
          AND i.status NOT IN ('draft', 'held', 'void') AND i.invoice_type IN ('regular', 'final', 'correction')
    ),
    first_unclean AS (SELECT min(rn) AS rn FROM bills WHERE NOT paid_clean)
    SELECT (SELECT count(*)::integer FROM bills b, first_unclean f WHERE b.paid_clean AND (f.rn IS NULL OR b.rn < f.rn)),
           (SELECT count(*)::integer FROM bills WHERE delinquent),
           (SELECT count(*) > 0 FROM bills WHERE status = 'overdue'),
           (SELECT count(*)::integer FROM bills b, first_unclean f WHERE b.paid_clean AND (f.rn IS NULL OR b.rn < f.rn)) >= 12
             AND (SELECT count(*)::integer FROM bills WHERE delinquent) <= 2
             AND NOT (SELECT count(*) > 0 FROM bills WHERE status = 'overdue')
$$;
COMMENT ON FUNCTION public.deposit_refund_trigger_state(uuid) IS 'CI-131 standing condition, derived from invoices since posting: trailing consecutive paid-clean bills, delinquent occasions, current delinquency, and whether §7.45''s twelve-bill trigger is met (≥ 12, ≤ 2, not delinquent). The definition of "paid clean" / "delinquent" is an approximation stated in the function body; the refund workflow is the authority and must record its own evaluation.';

CREATE OR REPLACE VIEW public.deposits_refund_due WITH (security_invoker = true) AS
    SELECT d.id AS deposit_id, d.tenant_id, d.customer_id, d.basis, d.principal, d.posted_on, d.status,
           c.status AS customer_status,
           CASE WHEN c.status IN ('closed', 'final_billed', 'inactive') THEN 'account_closed_or_inactive' ELSE 'twelve_clean_bills' END AS refund_trigger,
           s.consecutive_paid_bills, s.delinquent_occasions, s.currently_delinquent
    FROM public.deposits d
    JOIN public.customers c ON c.id = d.customer_id
    CROSS JOIN LATERAL public.deposit_refund_trigger_state(d.id) s
    WHERE d.instrument = 'cash'
      AND d.basis IN ('credit_evaluation', 'additional_trigger', 'tariff')
      AND d.status IN ('held', 'partial_applied', 'applied')
      AND (c.status IN ('closed', 'final_billed', 'inactive') OR s.twelve_bill_trigger_met);
COMMENT ON VIEW public.deposits_refund_due IS 'CI-131 (v5.4.2-06): §7.45 cash deposits whose mandatory refund trigger has fired and no refund has been initiated — the standing obligation made visible (the schema previously watched only refunds issued and unpaid). A §366 deposit never appears (table #54 rule 3); a legacy_unknown deposit never appears (its basis is unknown). The refund job reads this; an anomaly on a row that persists is the job''s.';

-- ----------------------------------------------------------------------------
-- 8. Guards: deposits (identity frozen, projection columns database-only,
--    Texas cap, waivers, legacy), deposit_events (the ledger rules),
--    projections onto deposits and customers
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.enforce_deposit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_cust public.customers%ROWTYPE;
    v_state text;
    v_waiver text;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT * INTO v_cust FROM public.customers c WHERE c.id = NEW.customer_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit rejected: customer %s not found (or not visible)', NEW.customer_id), ERRCODE = 'foreign_key_violation';
        END IF;
        IF NEW.basis = 'legacy_unknown' THEN
            RAISE EXCEPTION USING MESSAGE = 'deposit rejected: basis legacy_unknown exists only for rows carried from customers.deposit_* at patch time — record the basis that governs this deposit''s refund', ERRCODE = 'check_violation';
        END IF;
        IF NEW.status <> 'held' OR NEW.refunded_on IS NOT NULL OR NEW.released_on IS NOT NULL THEN
            RAISE EXCEPTION USING MESSAGE = 'deposit rejected: a deposit is born held; status / refunded_on / released_on are projected from deposit_events', ERRCODE = 'check_violation';
        END IF;
        PERFORM public.assert_same_tenant_user(NEW.created_by, NEW.tenant_id, 'created_by');
        IF NEW.source_payment_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.payments p WHERE p.id = NEW.source_payment_id AND p.customer_id = NEW.customer_id AND coalesce(p.is_deposit, false)) THEN
            RAISE EXCEPTION USING MESSAGE = 'deposit rejected: source_payment_id must be a payment of the same customer flagged is_deposit', ERRCODE = 'check_violation';
        END IF;
        -- §7.45 deposits (everything but a §366 assurance) honour a recorded waiver.
        IF NEW.basis IN ('credit_evaluation', 'additional_trigger', 'tariff') THEN
            SELECT w.waiver_class INTO v_waiver FROM public.deposit_waiver_determinations w
             WHERE w.customer_id = NEW.customer_id AND w.determined_on <= NEW.posted_on
               AND (w.certification_expires_on IS NULL OR w.certification_expires_on >= NEW.posted_on)
             ORDER BY w.determined_on DESC LIMIT 1;
            IF v_waiver IS NOT NULL THEN
                RAISE EXCEPTION USING
                    MESSAGE = format('deposit rejected: customer %s holds a %s deposit-waiver determination in force on %s — no §7.45 deposit may be required (CI-129, 16 TAC §7.45; table #53 ranks 0–3, #55 rule 8)', v_cust.customer_number, v_waiver, NEW.posted_on),
                    ERRCODE = 'check_violation';
            END IF;
            -- Texas residential: the cap is part of the record.
            SELECT t.state INTO v_state FROM public.tenants t WHERE t.id = NEW.tenant_id;
            IF upper(coalesce(v_state, '')) = 'TX' AND v_cust.customer_type = 'residential' AND NEW.instrument = 'cash' AND NEW.cap_amount IS NULL THEN
                RAISE EXCEPTION USING
                    MESSAGE = 'deposit rejected: a Texas residential deposit must record cap_amount (1/6 of estimated annual billing, 16 TAC §7.45 — CI-129) and principal may not exceed it',
                    ERRCODE = 'check_violation';
            END IF;
        END IF;
        RETURN NEW;
    END IF;

    -- UPDATE: identity frozen; projection columns only from inside the events trigger.
    IF OLD.id <> NEW.id OR OLD.tenant_id <> NEW.tenant_id OR OLD.customer_id <> NEW.customer_id OR OLD.basis <> NEW.basis
       OR OLD.trigger_basis IS DISTINCT FROM NEW.trigger_basis OR OLD.instrument <> NEW.instrument OR OLD.principal <> NEW.principal
       OR OLD.posted_on <> NEW.posted_on OR OLD.source_payment_id IS DISTINCT FROM NEW.source_payment_id
       OR OLD.cap_amount IS DISTINCT FROM NEW.cap_amount OR OLD.cap_basis_annual_billing IS DISTINCT FROM NEW.cap_basis_annual_billing
       OR OLD.cap_binding <> NEW.cap_binding OR OLD.legacy_interest_earned IS DISTINCT FROM NEW.legacy_interest_earned
       OR OLD.created_by IS DISTINCT FROM NEW.created_by OR OLD.created_at <> NEW.created_at THEN
        RAISE EXCEPTION USING
            MESSAGE = format('deposit %s: identity (customer, basis, instrument, principal, posted_on, cap, source) is frozen — a wrong deposit is refunded/released and re-posted', OLD.id),
            ERRCODE = 'check_violation';
    END IF;
    IF (OLD.status <> NEW.status OR OLD.refunded_on IS DISTINCT FROM NEW.refunded_on OR OLD.released_on IS DISTINCT FROM NEW.released_on)
       AND pg_trigger_depth() < 2 THEN
        RAISE EXCEPTION USING
            MESSAGE = format('deposit %s: status / refunded_on / released_on are projected from deposit_events — insert the event (applied_to_balance, refund_initiated, refunded, released)', OLD.id),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
-- (the a_enforce_deposit trigger is created after the backfill, section 10 —
--  the legacy_unknown rows must be written before the guard that refuses
--  that basis exists; the posted-event and projection triggers exist first)

CREATE OR REPLACE FUNCTION public.enforce_deposit_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    d public.deposits%ROWTYPE;
    b record;
    v_rate numeric;
    v_prev_end date;
    v_basis numeric;
    v_expected numeric;
    v_horizon date;
BEGIN
    SELECT * INTO d FROM public.deposits x WHERE x.id = NEW.deposit_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING MESSAGE = format('deposit event rejected: deposit %s not found (or not visible)', NEW.deposit_id), ERRCODE = 'foreign_key_violation';
    END IF;
    IF d.tenant_id <> NEW.tenant_id THEN
        RAISE EXCEPTION USING MESSAGE = 'deposit event rejected: tenant_id must equal the deposit''s', ERRCODE = 'check_violation';
    END IF;
    IF NEW.source = 'backfill' AND pg_trigger_depth() < 2 THEN
        RAISE EXCEPTION USING MESSAGE = 'deposit event rejected: source backfill is written only by the database for a legacy deposit''s posted event', ERRCODE = 'check_violation';
    END IF;
    PERFORM public.assert_same_tenant_user(NEW.created_by, NEW.tenant_id, 'created_by');
    NEW.created_at := now();
    IF d.status IN ('refunded', 'released') THEN
        RAISE EXCEPTION USING MESSAGE = format('deposit %s is %s: no further events (post a new deposit if one is required again)', d.id, d.status), ERRCODE = 'check_violation';
    END IF;
    IF NEW.effective_on < d.posted_on THEN
        RAISE EXCEPTION USING MESSAGE = format('deposit event rejected: effective_on %s precedes posted_on %s', NEW.effective_on, d.posted_on), ERRCODE = 'check_violation';
    END IF;
    IF NEW.ledger_entry_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.account_ledger l WHERE l.id = NEW.ledger_entry_id AND l.customer_id = d.customer_id
           AND l.transaction_type IN ('deposit', 'adjustment', 'deposit_interest', 'refund', 'credit_issued')) THEN
        RAISE EXCEPTION USING MESSAGE = 'deposit event rejected: ledger_entry_id must be an account_ledger row of the same customer with transaction_type deposit / adjustment / deposit_interest / refund / credit_issued', ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO b FROM public.deposit_balance(d.id);

    CASE NEW.event_type
    WHEN 'posted' THEN
        IF pg_trigger_depth() < 2 THEN
            RAISE EXCEPTION USING MESSAGE = 'deposit event rejected: the posted event is written by the database when the deposit is inserted', ERRCODE = 'check_violation';
        END IF;
    WHEN 'applied_to_balance' THEN
        IF d.status = 'refund_pending' THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: a refund is pending — the remainder is committed to the customer; record the refund (or a new deposit)', d.id), ERRCODE = 'check_violation';
        END IF;
        IF NEW.amount <= 0 OR NEW.amount > b.remainder THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: applied_to_balance must be > 0 and ≤ the remainder %s', d.id, b.remainder), ERRCODE = 'check_violation';
        END IF;
        IF b.accrued_through IS NOT NULL AND NEW.effective_on <= b.accrued_through THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: interest has already accrued through %s on the full principal; an application effective %s would change a settled period — apply it from %s', d.id, b.accrued_through, NEW.effective_on, b.accrued_through + 1), ERRCODE = 'check_violation';
        END IF;
    WHEN 'interest_accrued' THEN
        IF d.instrument <> 'cash' THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s is a %s: only cash accrues interest (CI-125; table #55 — the LDC owes interest on money it holds, not on a promise)', d.id, d.instrument), ERRCODE = 'check_violation';
        END IF;
        IF NEW.effective_on - d.posted_on < 31 THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: no interest accrues until the deposit has been held more than 30 days (posted %s; day 31 is %s) — then it accrues retroactively to the posting date (CI-130, 16 TAC §7.45)', d.id, d.posted_on, d.posted_on + 31), ERRCODE = 'check_violation';
        END IF;
        -- The same 30-day rule measured to the accrual horizon: a deposit
        -- whose principal was exhausted within 30 days of posting owes no
        -- interest at all, and an accrual recorded for its short life would
        -- block the zero refund forever (Codex round 2).
        IF b.exhausted_on IS NOT NULL AND b.exhausted_on - d.posted_on <= 30 THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s was exhausted on %s, %s days after posting: no interest is owed on it (CI-130) — settle it with a zero refund', d.id, b.exhausted_on, b.exhausted_on - d.posted_on), ERRCODE = 'check_violation';
        END IF;
        SELECT max(e.period_end) INTO v_prev_end FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'interest_accrued';
        IF v_prev_end IS NULL THEN
            IF NEW.period_start <> d.posted_on THEN
                RAISE EXCEPTION USING MESSAGE = format('deposit %s: the first accrual period must start ON the posting date %s — interest is retroactive to day 1, not from day 31 (CI-130)', d.id, d.posted_on), ERRCODE = 'check_violation';
            END IF;
        ELSIF NEW.period_start <> v_prev_end + 1 THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: accrual periods are contiguous — the next period starts %s, not %s', d.id, v_prev_end + 1, NEW.period_start), ERRCODE = 'check_violation';
        END IF;
        IF NEW.period_end >= NEW.effective_on THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: an accrual is recorded after the period it covers (period_end %s, effective_on %s)', d.id, NEW.period_end, NEW.effective_on), ERRCODE = 'check_violation';
        END IF;
        v_rate := public.deposit_interest_rate_as_of(d.tenant_id, NEW.period_start);
        IF NEW.rate_applied <> v_rate THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: rate_applied %s is not the rate in force on %s (%s) — deposit_interest_rate_as_of (CI-125 / CI-130)', d.id, NEW.rate_applied, NEW.period_start, v_rate), ERRCODE = 'check_violation';
        END IF;
        IF EXISTS (SELECT 1 FROM public.deposit_interest_rates r WHERE r.tenant_id = d.tenant_id AND r.effective_date > NEW.period_start AND r.effective_date <= NEW.period_end) THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: the accrual period %s..%s spans a rate change — split it at the rate''s effective date (accrual-cycle step 3)', d.id, NEW.period_start, NEW.period_end), ERRCODE = 'check_violation';
        END IF;
        IF EXISTS (SELECT 1 FROM public.deposit_events e WHERE e.deposit_id = d.id AND e.event_type = 'applied_to_balance' AND e.effective_on > NEW.period_start AND e.effective_on <= NEW.period_end) THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: the accrual period %s..%s spans a principal application — split it at the application date (accrual-cycle Alt 3)', d.id, NEW.period_start, NEW.period_end), ERRCODE = 'check_violation';
        END IF;
        v_basis := public.deposit_principal_in_force(d.id, NEW.period_start);
        IF v_basis <= 0 THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: the principal was exhausted on %s — nothing is held from that day and no interest accrues after %s', d.id, b.exhausted_on, b.exhausted_on - 1), ERRCODE = 'check_violation';
        END IF;
        IF NEW.principal_basis <> v_basis THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: principal_basis %s is not the principal in force on %s (%s)', d.id, NEW.principal_basis, NEW.period_start, v_basis), ERRCODE = 'check_violation';
        END IF;
        v_expected := public.deposit_accrual_amount(v_basis, v_rate, NEW.period_start, NEW.period_end);
        IF NEW.amount <> v_expected THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: accrual amount %s ≠ %s = %s × %s × %s/365 (deposit_accrual_amount)', d.id, NEW.amount, v_expected, v_basis, v_rate, NEW.period_end - NEW.period_start + 1), ERRCODE = 'check_violation';
        END IF;
    WHEN 'interest_credited' THEN
        IF NEW.amount <= 0 OR NEW.amount > b.interest_accrued - b.interest_credited THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: interest_credited must be > 0 and ≤ accrued − credited (%s)', d.id, b.interest_accrued - b.interest_credited), ERRCODE = 'check_violation';
        END IF;
    WHEN 'refund_initiated' THEN
        IF d.status = 'refund_pending' THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: a refund is already pending', d.id), ERRCODE = 'check_violation';
        END IF;
        IF NEW.amount <> b.remainder THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: refund_initiated amount must be the remainder %s (interest is credited separately and disclosed separately — table #54 rule 7)', d.id, b.remainder), ERRCODE = 'check_violation';
        END IF;
    WHEN 'refunded' THEN
        IF d.instrument <> 'cash' THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s is a %s: a non-cash instrument is released, not refunded', d.id, d.instrument), ERRCODE = 'check_violation';
        END IF;
        IF NEW.amount <> b.remainder THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: refunded amount must be the remainder %s (apply to balance first with applied_to_balance; interest is a separate movement; a fully applied deposit is settled by a zero refund)', d.id, b.remainder), ERRCODE = 'check_violation';
        END IF;
        -- Interest is owed on money held: through the day before the return,
        -- or the day before the principal was exhausted, whichever is first
        -- (Codex round 1: a deposit consumed by the final bill could never
        -- satisfy "accrue to the return date" — nothing was held to accrue on).
        v_horizon := least(NEW.effective_on, coalesce(b.exhausted_on, NEW.effective_on));
        IF d.basis = 'legacy_unknown' AND b.interest_accrued = 0 THEN
            -- A deposit carried from customers.deposit_* has no rate history to
            -- accrue against; its interest lives in legacy_interest_earned. It
            -- may be settled without ledger accrual, with the reason recorded
            -- (flagged for Ryan/Kyle: the alternative is to enter the rate
            -- history back to posting and accrue before every legacy refund).
            IF NEW.reason IS NULL OR length(btrim(NEW.reason)) = 0 THEN
                RAISE EXCEPTION USING MESSAGE = format('deposit %s is a legacy deposit with no accrual history: refunding it requires a reason stating how its interest was settled (legacy_interest_earned = %s)', d.id, coalesce(d.legacy_interest_earned, 0)), ERRCODE = 'check_violation';
            END IF;
        ELSIF v_horizon - d.posted_on <= 30 THEN
            IF b.interest_accrued > 0 THEN
                RAISE EXCEPTION USING MESSAGE = format('deposit %s was held %s days (to %s): no interest is owed, yet %s has been accrued (CI-130)', d.id, v_horizon - d.posted_on, v_horizon, b.interest_accrued), ERRCODE = 'check_violation';
            END IF;
        ELSE
            IF b.accrued_through IS NULL OR b.accrued_through < v_horizon - 1 THEN
                RAISE EXCEPTION USING MESSAGE = format('deposit %s held %s days: interest must be accrued retroactively from %s through %s (the day before %s) before it is refunded — accrued through %s (CI-130: retained > 30 days ⇒ interest to the return date)', d.id, v_horizon - d.posted_on, d.posted_on, v_horizon - 1, CASE WHEN b.exhausted_on IS NOT NULL AND b.exhausted_on <= NEW.effective_on THEN 'exhaustion' ELSE 'return' END, coalesce(b.accrued_through::text, 'nothing')), ERRCODE = 'check_violation';
            END IF;
            IF b.interest_credited <> b.interest_accrued THEN
                RAISE EXCEPTION USING MESSAGE = format('deposit %s: accrued interest %s must be credited in full (credited %s) before the refund — paid at refund (CI-130 / CI-131)', d.id, b.interest_accrued, b.interest_credited), ERRCODE = 'check_violation';
            END IF;
        END IF;
    WHEN 'released' THEN
        IF d.instrument = 'cash' THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s is cash: cash is refunded, not released', d.id), ERRCODE = 'check_violation';
        END IF;
        IF NEW.amount <> b.remainder THEN
            RAISE EXCEPTION USING MESSAGE = format('deposit %s: released amount must be the instrument''s remaining face value %s', d.id, b.remainder), ERRCODE = 'check_violation';
        END IF;
    END CASE;
    RETURN NEW;
END;
$$;
COMMENT ON FUNCTION public.enforce_deposit_event() IS 'The deposit sub-ledger rules (v5.4.2-06; CI-125 / CI-130 / CI-131) — see the table COMMENT on deposit_events. Locks the deposit row so concurrent events serialise.';

-- (the a_enforce_deposit_event trigger is created after the backfill, section
--  10 — legacy applied/refunded history is carried as synthetic events the
--  rules could not admit; the projection triggers exist first)

-- Projection: deposits.status from events; customers.deposit_* from deposits.
CREATE OR REPLACE FUNCTION public.project_deposit_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    b record;
BEGIN
    SELECT * INTO b FROM public.deposit_balance(NEW.deposit_id);
    UPDATE public.deposits d
       SET status = CASE NEW.event_type
                        WHEN 'refunded' THEN 'refunded'
                        WHEN 'released' THEN 'released'
                        WHEN 'refund_initiated' THEN 'refund_pending'
                        WHEN 'applied_to_balance' THEN CASE WHEN b.remainder = 0 THEN 'applied' ELSE 'partial_applied' END
                        ELSE d.status END,
           refunded_on = CASE WHEN NEW.event_type = 'refunded' THEN NEW.effective_on ELSE d.refunded_on END,
           released_on = CASE WHEN NEW.event_type = 'released' THEN NEW.effective_on ELSE d.released_on END
     WHERE d.id = NEW.deposit_id;
    RETURN NULL;
END;
$$;
DROP TRIGGER IF EXISTS z_project_deposit_status ON public.deposit_events;
CREATE TRIGGER z_project_deposit_status AFTER INSERT ON public.deposit_events
    FOR EACH ROW EXECUTE FUNCTION public.project_deposit_status();

CREATE OR REPLACE FUNCTION public.project_customer_deposit_scalars() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_customer uuid := coalesce(NEW.customer_id, OLD.customer_id);
    v_open record;
    v_last record;
    v_interest numeric;
BEGIN
    SELECT count(*) AS n,
           coalesce(sum(CASE WHEN d.instrument = 'cash' THEN bal.remainder ELSE 0 END), 0) AS held,
           max(d.posted_on) AS last_posted,
           (array_agg(d.status ORDER BY d.posted_on DESC, d.created_at DESC))[1] AS latest_status
      INTO v_open
      FROM public.deposits d
      CROSS JOIN LATERAL public.deposit_balance(d.id) bal
     WHERE d.customer_id = v_customer AND d.status IN ('held', 'partial_applied', 'applied', 'refund_pending');
    SELECT d.refunded_on, bal.remainder AS refunded_amount
      INTO v_last
      FROM public.deposits d
      CROSS JOIN LATERAL public.deposit_balance(d.id) bal
     WHERE d.customer_id = v_customer AND d.status = 'refunded'
     ORDER BY d.refunded_on DESC, d.created_at DESC LIMIT 1;
    SELECT coalesce(sum(bal.interest_accrued + coalesce(d.legacy_interest_earned, 0)), 0)
      INTO v_interest
      FROM public.deposits d
      CROSS JOIN LATERAL public.deposit_balance(d.id) bal
     WHERE d.customer_id = v_customer;
    UPDATE public.customers c
       SET deposit_amount = v_open.held,
           deposit_status = CASE WHEN v_open.n = 0 THEN CASE WHEN v_last.refunded_on IS NOT NULL THEN 'refunded' ELSE 'none' END ELSE v_open.latest_status END,
           deposit_received_date = v_open.last_posted,
           deposit_refund_date = v_last.refunded_on,
           deposit_refund_amount = v_last.refunded_amount,
           deposit_interest_earned = v_interest
     WHERE c.id = v_customer;
    RETURN NULL;
END;
$$;
COMMENT ON FUNCTION public.project_customer_deposit_scalars() IS 'v5.4.2-06: customers.deposit_amount / deposit_status / deposit_received_date / deposit_refund_date / deposit_refund_amount / deposit_interest_earned are a projection of the customer''s deposits (cash remainder held; latest open status or refunded/none; last posting; last refund; interest accrued + legacy). Maintained here; direct writes are rejected.';
DROP TRIGGER IF EXISTS z_project_customer_deposit_scalars ON public.deposits;
CREATE TRIGGER z_project_customer_deposit_scalars AFTER INSERT OR UPDATE ON public.deposits
    FOR EACH ROW EXECUTE FUNCTION public.project_customer_deposit_scalars();

-- The database writes the posted event.
CREATE OR REPLACE FUNCTION public.post_deposit_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    INSERT INTO public.deposit_events (tenant_id, deposit_id, event_type, amount, effective_on, created_by, source)
    VALUES (NEW.tenant_id, NEW.id, 'posted', NEW.principal, NEW.posted_on, NEW.created_by, CASE WHEN NEW.basis = 'legacy_unknown' THEN 'backfill' ELSE 'system' END);
    RETURN NULL;
END;
$$;
DROP TRIGGER IF EXISTS y_post_deposit_event ON public.deposits;
CREATE TRIGGER y_post_deposit_event AFTER INSERT ON public.deposits
    FOR EACH ROW EXECUTE FUNCTION public.post_deposit_event();

-- customers.deposit_* are the database's.
CREATE OR REPLACE FUNCTION public.enforce_customer_deposit_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF (OLD.deposit_amount IS DISTINCT FROM NEW.deposit_amount OR OLD.deposit_status IS DISTINCT FROM NEW.deposit_status
        OR OLD.deposit_received_date IS DISTINCT FROM NEW.deposit_received_date OR OLD.deposit_refund_date IS DISTINCT FROM NEW.deposit_refund_date
        OR OLD.deposit_refund_amount IS DISTINCT FROM NEW.deposit_refund_amount OR OLD.deposit_interest_earned IS DISTINCT FROM NEW.deposit_interest_earned)
       AND pg_trigger_depth() < 2 THEN
        RAISE EXCEPTION USING
            MESSAGE = format('customer %s: deposit_amount / deposit_status / deposit_received_date / deposit_refund_* / deposit_interest_earned are projected from deposits and deposit_events (v5.4.2-06) — post a deposit or a deposit event', OLD.customer_number),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS b_enforce_customer_deposit_projection ON public.customers;
CREATE TRIGGER b_enforce_customer_deposit_projection BEFORE UPDATE ON public.customers
    FOR EACH ROW EXECUTE FUNCTION public.enforce_customer_deposit_projection();

-- ----------------------------------------------------------------------------
-- 9. Append-only guards, CI-014 set, privileges
-- ----------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['customer_state_events', 'customer_attribute_history', 'deposit_events', 'deposit_interest_rates', 'deposit_waiver_determinations'] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS append_only ON public.%I', t);
        EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.enforce_append_only()', t);
        EXECUTE format('DROP TRIGGER IF EXISTS no_truncate ON public.%I', t);
        EXECUTE format('CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete()', t);
        EXECUTE format('REVOKE UPDATE, DELETE ON public.%I FROM tally_app', t);
    END LOOP;
    DROP TRIGGER IF EXISTS no_hard_delete ON public.deposits;
    CREATE TRIGGER no_hard_delete BEFORE DELETE ON public.deposits FOR EACH ROW EXECUTE FUNCTION public.enforce_no_hard_delete();
    DROP TRIGGER IF EXISTS no_truncate ON public.deposits;
    CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.deposits FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete();
    REVOKE DELETE ON public.deposits FROM tally_app;
    -- pg_trigger_depth() is a structural fence only if the application role
    -- cannot run code inside a trigger of its own: with TEMP it could create a
    -- temp table + pg_temp function + trigger and reach depth 2 (Fable round
    -- 1, CRITICAL). No CREATE on any schema, no TRIGGER on any table, and now
    -- no TEMP: there is no table tally_app owns and no function it can define.
    EXECUTE format('REVOKE TEMP ON DATABASE %I FROM PUBLIC', current_database());
    EXECUTE format('REVOKE TEMP ON DATABASE %I FROM tally_app', current_database());
END;
$$;

-- ----------------------------------------------------------------------------
-- 10. Backfill (reporting only, never a refusal; re-runnable)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
    v bigint;
BEGIN
    PERFORM set_config('search_path', 'public, pg_temp', true);

    -- 10.1 One initial state event per pre-existing customer.
    INSERT INTO public.customer_state_events (tenant_id, customer_id, from_status, to_status, effective_at, reason_code, source)
    SELECT c.tenant_id, c.id, NULL, c.status, c.created_at, 'backfill: status at v5.4.2-06', 'backfill'
      FROM public.customers c
     WHERE NOT EXISTS (SELECT 1 FROM public.customer_state_events e WHERE e.customer_id = c.id);
    GET DIAGNOSTICS v = ROW_COUNT;
    IF v > 0 THEN RAISE NOTICE 'v5.4.2-06: initial state event written for % customer(s) at created_at (approximation of the transition instant)', v; END IF;
    UPDATE public.customers c SET status_changed_at = c.created_at WHERE c.status_changed_at IS NULL;

    -- 10.2 One backfill attribute row per attribute per customer.
    INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, source)
    SELECT c.tenant_id, c.id, a.attribute, NULL,
           CASE a.attribute
               WHEN 'billing_delivery_method' THEN c.billing_delivery_method
               WHEN 'billing_hold' THEN c.billing_hold::text
               WHEN 'consolidate_invoices' THEN c.consolidate_invoices::text
               WHEN 'do_not_disconnect' THEN c.do_not_disconnect::text
               WHEN 'landlord_responsible' THEN c.landlord_responsible::text
               WHEN 'customer_type' THEN c.customer_type
               WHEN 'deposit_status' THEN c.deposit_status
               WHEN 'autopay_enabled' THEN coalesce((SELECT a2.enabled::text FROM public.auto_pay_settings a2 WHERE a2.customer_id = c.id LIMIT 1), 'false')
           END,
           c.created_at, 'backfill'
      FROM public.customers c
      CROSS JOIN (SELECT unnest(ARRAY['billing_delivery_method', 'billing_hold', 'consolidate_invoices', 'do_not_disconnect', 'landlord_responsible', 'customer_type', 'deposit_status', 'autopay_enabled']) AS attribute) a
     WHERE NOT EXISTS (SELECT 1 FROM public.customer_attribute_history h WHERE h.customer_id = c.id AND h.attribute = a.attribute);
    GET DIAGNOSTICS v = ROW_COUNT;
    IF v > 0 THEN RAISE NOTICE 'v5.4.2-06: % attribute-history backfill row(s) written at created_at (current values; history before this patch is unknown)', v; END IF;

    -- 10.3 Legacy deposits from the customers scalars (only where no deposit
    --      exists yet). The event guard does not exist yet: applied / refunded
    --      history is carried as synthetic 'backfill' events the rules could
    --      not admit (no rate history, no accrual). A refund_pending scalar
    --      comes back as held (the pending refund is not an event we can
    --      reconstruct); a partial_applied scalar as held with the amount the
    --      scalar reported (the applied part is unknown).
    CREATE TEMP TABLE zz_legacy_deposits ON COMMIT DROP AS
    SELECT c.id AS customer_id, c.tenant_id, c.deposit_amount, c.deposit_status, c.deposit_refund_date, c.deposit_refund_amount,
           coalesce(c.deposit_received_date, c.created_at::date) AS posted_on, c.created_at, nullif(c.deposit_interest_earned, 0) AS legacy_interest
      FROM public.customers c
     WHERE c.deposit_amount > 0
       AND c.deposit_status IN ('held', 'partial_applied', 'refund_pending', 'applied', 'refunded')
       AND NOT EXISTS (SELECT 1 FROM public.deposits d WHERE d.customer_id = c.id);
    INSERT INTO public.deposits (id, tenant_id, customer_id, basis, instrument, principal, posted_on, status, legacy_interest_earned, notes)
    SELECT public.uuid_generate_v5(l.customer_id, 'legacy-deposit-v5.4.2-06'), l.tenant_id, l.customer_id, 'legacy_unknown', 'cash', l.deposit_amount, l.posted_on, 'held', l.legacy_interest,
           'backfill v5.4.2-06 from customers.deposit_* (status was ' || l.deposit_status || '); basis unknown — reclassify by refund + re-post, or a Kyle ruling'
      FROM zz_legacy_deposits l;
    GET DIAGNOSTICS v = ROW_COUNT;
    -- applied: the whole principal was applied (date unknown: refund date, else the posting date)
    INSERT INTO public.deposit_events (tenant_id, deposit_id, event_type, amount, effective_on, reason, source)
    SELECT l.tenant_id, public.uuid_generate_v5(l.customer_id, 'legacy-deposit-v5.4.2-06'), 'applied_to_balance', l.deposit_amount,
           greatest(coalesce(l.deposit_refund_date, l.posted_on), l.posted_on), 'backfill: customers.deposit_status was applied; application date unknown', 'backfill'
      FROM zz_legacy_deposits l WHERE l.deposit_status = 'applied';
    -- refunded: refunded for the amount the scalar reported (else the principal), on the refund date (else the posting date)
    INSERT INTO public.deposit_events (tenant_id, deposit_id, event_type, amount, effective_on, reason, source)
    SELECT l.tenant_id, public.uuid_generate_v5(l.customer_id, 'legacy-deposit-v5.4.2-06'), 'refunded', coalesce(l.deposit_refund_amount, l.deposit_amount),
           greatest(coalesce(l.deposit_refund_date, l.posted_on), l.posted_on), 'backfill: customers.deposit_status was refunded; interest history unknown', 'backfill'
      FROM zz_legacy_deposits l WHERE l.deposit_status = 'refunded';
    IF v > 0 THEN RAISE NOTICE 'v5.4.2-06: % legacy deposit(s) carried from customers.deposit_* as basis legacy_unknown (held / partial_applied / refund_pending → held; applied → applied; refunded → refunded via synthetic backfill events; prior deposit_interest_earned kept as legacy_interest_earned)', v; END IF;

    -- 10.4 Legacy deposit_refund credits: link to the customer's legacy deposit where exactly one exists.
    UPDATE public.customer_credits cc
       SET deposit_id = d.id
      FROM public.deposits d
     WHERE cc.origin_type = 'deposit_refund' AND cc.deposit_id IS NULL AND d.customer_id = cc.customer_id AND d.basis = 'legacy_unknown'
       AND (SELECT count(*) FROM public.deposits d2 WHERE d2.customer_id = cc.customer_id) = 1;
    GET DIAGNOSTICS v = ROW_COUNT;
    IF v > 0 THEN RAISE NOTICE 'v5.4.2-06: % legacy deposit_refund credit(s) linked to the customer''s legacy deposit', v; END IF;
    SELECT count(*) INTO v FROM public.customer_credits cc WHERE cc.origin_type = 'deposit_refund' AND cc.deposit_id IS NULL;
    IF v > 0 THEN RAISE NOTICE 'v5.4.2-06: % deposit_refund credit(s) remain without a deposit_id (no single legacy deposit to link); they stay as they are', v; END IF;
END;
$$;

DROP TRIGGER IF EXISTS a_enforce_customer_lifecycle ON public.customers;
CREATE TRIGGER a_enforce_customer_lifecycle BEFORE INSERT OR UPDATE ON public.customers
    FOR EACH ROW EXECUTE FUNCTION public.enforce_customer_lifecycle();
DROP TRIGGER IF EXISTS a_enforce_deposit ON public.deposits;
CREATE TRIGGER a_enforce_deposit BEFORE INSERT OR UPDATE ON public.deposits
    FOR EACH ROW EXECUTE FUNCTION public.enforce_deposit();
DROP TRIGGER IF EXISTS a_enforce_deposit_event ON public.deposit_events;
CREATE TRIGGER a_enforce_deposit_event BEFORE INSERT ON public.deposit_events
    FOR EACH ROW EXECUTE FUNCTION public.enforce_deposit_event();

-- ----------------------------------------------------------------------------
-- 11. ENABLE ALWAYS on every guard this patch created
-- ----------------------------------------------------------------------------
DO $$
DECLARE r record;
BEGIN
    FOR r IN
        SELECT c.relname, t.tgname
        FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND NOT t.tgisinternal AND t.tgenabled <> 'A'
          AND (
                (c.relname IN ('customer_state_events', 'customer_attribute_history', 'deposit_events', 'deposit_interest_rates', 'deposit_waiver_determinations', 'deposits')
                 AND t.tgname IN ('append_only', 'no_truncate', 'no_hard_delete', 'a_enforce_deposit', 'a_enforce_deposit_event', 'z_project_deposit_status', 'y_post_deposit_event', 'z_project_customer_deposit_scalars'))
             OR (c.relname = 'customers' AND t.tgname IN ('a_enforce_customer_lifecycle', 'z_log_customer_state_event', 'z_log_customer_attribute_changes', 'b_enforce_customer_deposit_projection'))
             OR (c.relname = 'auto_pay_settings' AND t.tgname = 'z_log_autopay_attribute_change')
             OR (c.relname = 'deposit_interest_rates' AND t.tgname = 'a_enforce_deposit_interest_rate')
             OR (c.relname = 'customer_credits' AND t.tgname = 'enforce_customer_credit_deposit_lineage')
          )
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I', r.relname, r.tgname);
    END LOOP;
END;
$$;

-- ----------------------------------------------------------------------------
-- 12. Cross-references on existing objects
-- ----------------------------------------------------------------------------
COMMENT ON COLUMN public.customers.deposit_amount IS 'PROJECTION (v5.4.2-06): cash principal currently held less applications, over the customer''s open deposits. Maintained by the database from deposits / deposit_events; direct writes rejected. The record is public.deposits.';
COMMENT ON COLUMN public.customers.deposit_status IS 'PROJECTION (v5.4.2-06): the latest open deposit''s status (held | partial_applied | refund_pending), or refunded / none. Maintained by the database; direct writes rejected. Change history in customer_attribute_history (attribute deposit_status).';
COMMENT ON COLUMN public.customers.deposit_interest_earned IS 'PROJECTION (v5.4.2-06): interest accrued across the customer''s deposits per deposit_events (+ any pre-patch legacy_interest_earned). Never written directly; the derivation is deposit_balance().';
COMMENT ON COLUMN public.customers.status IS 'Account lifecycle (active | inactive | final_billed | collections | closed). Since v5.4.2-06 every change requires status_reason and is logged to customer_state_events by the database; closed reopens only to active and is refused while a deposit is held / refund pending (CI-121, CI-131). customer_status_as_of() answers "what was the status on date X".';
COMMENT ON COLUMN public.payments.is_deposit IS 'True if this payment funded a security deposit. Since v5.4.2-06 the deposit itself is a public.deposits row (source_payment_id → this payment) and deposit_status must be set exactly when is_deposit (CHECK; older rows were reconciled at patch time).';
-- ============================================================================
-- MIRROR: PATCH v5.4.2-07 — A-7: regulatory cost-recovery surcharge riders — the Texas Pipeline Safety Fee (Phase 4 Wave 2; CI-038/045; CI-015/121 touched)
-- Appended 2026-08-31; source of truth: sql/v5.4.2-07-regulatory-surcharge-riders.sql
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Tenant-bound identity for composite FKs
-- ----------------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'invoice_line_items_id_tenant_id_key' AND conrelid = 'public.invoice_line_items'::regclass) THEN
        ALTER TABLE public.invoice_line_items ADD CONSTRAINT invoice_line_items_id_tenant_id_key UNIQUE (id, tenant_id);
    END IF;
END;
$$;

-- ----------------------------------------------------------------------------
-- 2. regulatory_surcharge_rules — the rider classification, bi-temporal in place
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.regulatory_surcharge_rules (
    id                        uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id                 uuid NOT NULL,
    rate_item_id              uuid NOT NULL,
    surcharge_kind            text NOT NULL,
    cycle_start               date NOT NULL,
    cycle_end                 date NOT NULL,
    cap_per_service           numeric(12,2),
    excluded_from_tax_bases   boolean NOT NULL,
    exempts_state_agencies    boolean NOT NULL,
    regulatory_reference      text,
    tariff_filing_reference   text,
    notes                     text,
    metadata                  jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at                timestamp with time zone DEFAULT now() NOT NULL,
    updated_at                timestamp with time zone DEFAULT now() NOT NULL,
    recorded_at               timestamp with time zone DEFAULT now() NOT NULL,
    recorded_until            timestamp with time zone,
    change_type               text DEFAULT 'initial' NOT NULL,
    change_reason             text,
    changed_by                uuid,
    supersedes_id             uuid,
    closed_type               text,
    closed_reason             text,
    closed_by                 uuid,
    CONSTRAINT regulatory_surcharge_rules_pkey PRIMARY KEY (id),
    CONSTRAINT regulatory_surcharge_rules_id_tenant_id_key UNIQUE (id, tenant_id),
    CONSTRAINT regulatory_surcharge_rules_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT regulatory_surcharge_rules_rate_item_fkey FOREIGN KEY (rate_item_id, tenant_id) REFERENCES public.rate_items(id, tenant_id),
    CONSTRAINT regulatory_surcharge_rules_changed_by_fkey FOREIGN KEY (changed_by) REFERENCES public.users(id),
    CONSTRAINT regulatory_surcharge_rules_closed_by_fkey FOREIGN KEY (closed_by) REFERENCES public.users(id),
    CONSTRAINT regulatory_surcharge_rules_supersedes_id_fkey FOREIGN KEY (supersedes_id) REFERENCES public.regulatory_surcharge_rules(id),
    CONSTRAINT regulatory_surcharge_rules_kind_check CHECK ((surcharge_kind = ANY (ARRAY['pipeline_safety_fee'::text, 'other_regulatory_cost_recovery'::text]))),
    CONSTRAINT regulatory_surcharge_rules_cycle_check CHECK ((cycle_end >= cycle_start)),
    CONSTRAINT regulatory_surcharge_rules_cap_positive_check CHECK (((cap_per_service IS NULL) OR (cap_per_service > (0)::numeric))),
    CONSTRAINT regulatory_surcharge_rules_psf_shape_check CHECK (((surcharge_kind <> 'pipeline_safety_fee'::text) OR ((cap_per_service IS NOT NULL) AND excluded_from_tax_bases AND exempts_state_agencies))),
    CONSTRAINT regulatory_surcharge_rules_change_type_check CHECK ((change_type = ANY (ARRAY['initial'::text, 'succession'::text, 'correction'::text, 'backfill'::text]))),
    CONSTRAINT regulatory_surcharge_rules_correction_reason_check CHECK (((change_type <> 'correction'::text) OR (change_reason IS NOT NULL))),
    CONSTRAINT regulatory_surcharge_rules_supersedes_check CHECK (((supersedes_id IS NULL) OR (change_type = 'succession'::text) OR (change_type = 'correction'::text))),
    CONSTRAINT regulatory_surcharge_rules_closed_type_check CHECK (((closed_type IS NULL) OR (closed_type = ANY (ARRAY['superseded'::text, 'retracted'::text])))),
    CONSTRAINT regulatory_surcharge_rules_close_consistent_check CHECK ((((recorded_until IS NULL) AND (closed_type IS NULL) AND (closed_reason IS NULL) AND (closed_by IS NULL)) OR ((recorded_until IS NOT NULL) AND (closed_type IS NOT NULL) AND (closed_reason IS NOT NULL) AND (recorded_until >= recorded_at))))
);

ALTER TABLE public.regulatory_surcharge_rules DROP CONSTRAINT IF EXISTS regulatory_surcharge_rules_open_no_overlap_excl;
ALTER TABLE public.regulatory_surcharge_rules ADD CONSTRAINT regulatory_surcharge_rules_open_no_overlap_excl
    EXCLUDE USING gist (rate_item_id WITH =, daterange(cycle_start, cycle_end, '[]') WITH &&) WHERE (recorded_until IS NULL);
-- The Pipeline Safety Fee is ONE assessment per tenant: a second PSF rider
-- with its own cap over an overlapping cycle would bill a service twice
-- (Fable MEDIUM-2a). One open pipeline_safety_fee rule per tenant per
-- bill date.
ALTER TABLE public.regulatory_surcharge_rules DROP CONSTRAINT IF EXISTS regulatory_surcharge_rules_one_psf_per_tenant_excl;
ALTER TABLE public.regulatory_surcharge_rules ADD CONSTRAINT regulatory_surcharge_rules_one_psf_per_tenant_excl
    EXCLUDE USING gist (tenant_id WITH =, daterange(cycle_start, cycle_end, '[]') WITH &&) WHERE (recorded_until IS NULL AND surcharge_kind = 'pipeline_safety_fee');

CREATE INDEX IF NOT EXISTS idx_regulatory_surcharge_rules_tenant ON public.regulatory_surcharge_rules USING btree (tenant_id);
CREATE INDEX IF NOT EXISTS idx_regulatory_surcharge_rules_open ON public.regulatory_surcharge_rules USING btree (rate_item_id, cycle_start DESC) WHERE (recorded_until IS NULL);
CREATE INDEX IF NOT EXISTS idx_regulatory_surcharge_rules_lineage ON public.regulatory_surcharge_rules USING btree (rate_item_id, recorded_at DESC);
CREATE INDEX IF NOT EXISTS idx_regulatory_surcharge_rules_supersedes ON public.regulatory_surcharge_rules USING btree (supersedes_id) WHERE (supersedes_id IS NOT NULL);

DROP TRIGGER IF EXISTS set_updated_at ON public.regulatory_surcharge_rules;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.regulatory_surcharge_rules FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

ALTER TABLE public.regulatory_surcharge_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.regulatory_surcharge_rules FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.regulatory_surcharge_rules;
CREATE POLICY tenant_isolation ON public.regulatory_surcharge_rules USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));

REVOKE DELETE ON public.regulatory_surcharge_rules FROM tally_app;

COMMENT ON TABLE public.regulatory_surcharge_rules IS
    'CI-038 / CI-045 (v5.4.2-07, A-7). Classification of a rate item as a regulatory cost-recovery surcharge rider, one row per (rate item, assessment cycle): the cycle is a closed bracket of BILL DATES (invoices.invoice_date); cap_per_service is the aggregate a single service line (meter) may be billed over the cycle (NULL = uncapped); excluded_from_tax_bases makes the rider''s lines non-taxable and uncitable as a base by any tax / percentage line; exempts_state_agencies makes a non-zero line on a state-agency account (customers.is_state_agency at the end of the billed period) a refusal. A pipeline_safety_fee rule must carry a cap and both flags. Bi-temporal in place (A-1 group 2): frozen once recorded except notes / metadata; correction = close (closed_type = ''superseded'') + insert with supersedes_id; retraction = close as ''retracted''; one open row per rate item per bill date (exclusion). No remittance gate and no billing-window check exist (Kyle D4-1, 2026-07-10): "bill after remittance, never before" is operator guidance. Read through regulatory_surcharge_rule_as_of().';
COMMENT ON COLUMN public.regulatory_surcharge_rules.cycle_start IS 'First bill date of the assessment cycle (inclusive). A line on an invoice whose invoice_date lies in [cycle_start, cycle_end] is governed by this rule.';
COMMENT ON COLUMN public.regulatory_surcharge_rules.cycle_end IS 'Last bill date of the assessment cycle (inclusive). Open rows of one rate item never overlap.';
COMMENT ON COLUMN public.regulatory_surcharge_rules.cap_per_service IS 'Aggregate the rider may bill to ONE service line (invoice_line_items.meter_id) over the cycle, on non-void invoices, drafts included. Configured by the tenant against its filed tariff — no statutory figure is hard-coded (CI-038 states $1.00 per service; D4-1''s research note $0.50; open with Kyle). Required for pipeline_safety_fee.';
COMMENT ON COLUMN public.regulatory_surcharge_rules.excluded_from_tax_bases IS 'The rider is not a base for any tax or percentage charge (16 TAC §8.201: exempt from franchise fees, gas-utility tax and sales tax). Enforced on the rider''s versions and schedule overrides (never taxable), on its invoice lines (is_taxable = false, no taxable_amount) and on invoice_line_item_bases (never cited). Required true for pipeline_safety_fee.';
COMMENT ON COLUMN public.regulatory_surcharge_rules.exempts_state_agencies IS 'A customer that was a state agency (customers.is_state_agency, per customer_attribute_history) at the end of the billed period may carry only a 0.00 line for this rider. Required true for pipeline_safety_fee.';

-- 2.1 Rule guard: tenant-checked actors; a rider cannot be excluded from
--     tax bases while any open version or schedule override says taxable;
--     a pipeline_safety_fee rider is a gas (or all-service) item.
CREATE OR REPLACE FUNCTION public.enforce_regulatory_surcharge_rule() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_taxable_versions  integer;
    v_taxable_overrides integer;
    v_non_gas           integer;
    v_code              text;
BEGIN
    PERFORM public.assert_same_tenant_user(NEW.changed_by, NEW.tenant_id, 'regulatory_surcharge_rules.changed_by');
    PERFORM public.assert_same_tenant_user(NEW.closed_by, NEW.tenant_id, 'regulatory_surcharge_rules.closed_by');
    IF TG_OP = 'UPDATE' THEN
        RETURN NEW;      -- content is frozen by the bi-temporal guard; only the close and notes/metadata get here
    END IF;
    SELECT ri.item_code INTO v_code FROM public.rate_items ri WHERE ri.id = NEW.rate_item_id AND ri.tenant_id = NEW.tenant_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = format('regulatory_surcharge_rules: rate item %s is not visible in tenant %s', NEW.rate_item_id, NEW.tenant_id),
            ERRCODE = 'foreign_key_violation';
    END IF;
    IF NEW.excluded_from_tax_bases THEN
        SELECT count(*) INTO v_taxable_versions
          FROM public.rate_item_versions v
         WHERE v.rate_item_id = NEW.rate_item_id AND v.recorded_until IS NULL AND (v.is_taxable_default OR v.is_a_tax);
        SELECT count(*) INTO v_taxable_overrides
          FROM public.rate_schedule_items s
         WHERE s.rate_item_id = NEW.rate_item_id AND s.recorded_until IS NULL AND s.is_taxable_override = true;
        IF v_taxable_versions > 0 OR v_taxable_overrides > 0 THEN
            RAISE EXCEPTION USING
                MESSAGE = format('regulatory_surcharge_rules: rider %s cannot be excluded from tax bases while %s open version(s) are taxable / a tax and %s open schedule override(s) say taxable — correct those assertions first (CI-038 / CI-045)', v_code, v_taxable_versions, v_taxable_overrides),
                ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF NEW.surcharge_kind = 'pipeline_safety_fee' THEN
        SELECT count(*) INTO v_non_gas
          FROM public.rate_item_versions v
         WHERE v.rate_item_id = NEW.rate_item_id AND v.recorded_until IS NULL AND v.service_type NOT IN ('gas', 'all');
        IF v_non_gas > 0 THEN
            RAISE EXCEPTION USING
                MESSAGE = format('regulatory_surcharge_rules: the Pipeline Safety Fee is a gas-distribution assessment (16 TAC §8.201) but rider %s has %s open version(s) of another service type', v_code, v_non_gas),
                ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_regulatory_surcharge_rule() IS
    'v5.4.2-07 (A-7): BEFORE INSERT/UPDATE on regulatory_surcharge_rules. Actors must belong to the tenant; on INSERT the rider must be visible in the tenant, an excluded rider may have no open taxable version / override (the reverse direction is enforced on those tables), and a pipeline_safety_fee rider is gas or all-service. Runs after a_enforce_bitemporal_assertion (name order).';

DROP TRIGGER IF EXISTS a_enforce_bitemporal_assertion ON public.regulatory_surcharge_rules;
CREATE TRIGGER a_enforce_bitemporal_assertion BEFORE INSERT OR UPDATE OR DELETE ON public.regulatory_surcharge_rules
    FOR EACH ROW EXECUTE FUNCTION public.enforce_bitemporal_assertion('notes,metadata,updated_at', 'rate_item_id');
DROP TRIGGER IF EXISTS b_enforce_regulatory_surcharge_rule ON public.regulatory_surcharge_rules;
CREATE TRIGGER b_enforce_regulatory_surcharge_rule BEFORE INSERT OR UPDATE ON public.regulatory_surcharge_rules
    FOR EACH ROW EXECUTE FUNCTION public.enforce_regulatory_surcharge_rule();
DROP TRIGGER IF EXISTS enforce_superseded_has_successor ON public.regulatory_surcharge_rules;
CREATE CONSTRAINT TRIGGER enforce_superseded_has_successor AFTER UPDATE ON public.regulatory_surcharge_rules
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.enforce_superseded_has_successor('rate_item_id');
DROP TRIGGER IF EXISTS no_truncate ON public.regulatory_surcharge_rules;
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.regulatory_surcharge_rules
    FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete();

-- 2.2 The lookup (R-15 shape: both coordinates required, NULL raises).
CREATE OR REPLACE FUNCTION public.regulatory_surcharge_rule_as_of(p_rate_item_id uuid, p_billed_on date, p_recorded_at timestamp with time zone)
    RETURNS SETOF public.regulatory_surcharge_rules
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF p_billed_on IS NULL OR p_recorded_at IS NULL THEN
        RAISE EXCEPTION 'regulatory_surcharge_rule_as_of: p_billed_on and p_recorded_at are both required — pass the invoice''s bill date and the run''s recorded_at; never default to now() (CI-001 / CI-003 / CI-006)';
    END IF;
    RETURN QUERY
    SELECT r.* FROM public.regulatory_surcharge_rules r
    WHERE r.rate_item_id = p_rate_item_id
      AND r.recorded_at <= p_recorded_at AND (r.recorded_until IS NULL OR r.recorded_until > p_recorded_at)
      AND r.cycle_start <= p_billed_on AND r.cycle_end >= p_billed_on
    ORDER BY r.recorded_at DESC, r.id
    LIMIT 1;
END;
$$;

COMMENT ON FUNCTION public.regulatory_surcharge_rule_as_of(uuid, date, timestamp with time zone) IS
    'A-7 (v5.4.2-07). The surcharge rule governing a rider for a bill dated p_billed_on, as asserted at p_recorded_at: the open-at-that-instant row whose cycle contains the date. Zero rows = not a surcharge rider for that bill date. Both arguments REQUIRED; NULL RAISES; no live fallback. Invoker rights: RLS applies.';

-- 2.3 Reverse direction: a rider with an excluded rule can never be made taxable.
CREATE OR REPLACE FUNCTION public.enforce_surcharge_rider_not_taxable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_flag boolean;
    v_rule public.regulatory_surcharge_rules%ROWTYPE;
BEGIN
    IF TG_TABLE_NAME = 'rate_item_versions' THEN
        v_flag := (to_jsonb(NEW) ->> 'is_taxable_default')::boolean OR (to_jsonb(NEW) ->> 'is_a_tax')::boolean;
    ELSE
        v_flag := (to_jsonb(NEW) ->> 'is_taxable_override')::boolean IS TRUE;
    END IF;
    IF NOT coalesce(v_flag, false) THEN
        RETURN NEW;
    END IF;
    SELECT r.* INTO v_rule
      FROM public.regulatory_surcharge_rules r
     WHERE r.rate_item_id = (to_jsonb(NEW) ->> 'rate_item_id')::uuid AND r.recorded_until IS NULL AND r.excluded_from_tax_bases
     ORDER BY r.cycle_start DESC LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = format('%s: rate item %s is a %s surcharge rider excluded from every tax base (regulatory_surcharge_rules %s, cycle %s..%s) and cannot be taxable or a tax (CI-038 / CI-045); retract the rule first if the classification is wrong', TG_TABLE_NAME, to_jsonb(NEW) ->> 'rate_item_id', v_rule.surcharge_kind, v_rule.id, v_rule.cycle_start, v_rule.cycle_end),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_surcharge_rider_not_taxable() IS
    'v5.4.2-07 (A-7): BEFORE INSERT / UPDATE OF the taxability columns on rate_item_versions (is_taxable_default, is_a_tax) and rate_schedule_items (is_taxable_override): refused when the rate item has an open regulatory_surcharge_rules row with excluded_from_tax_bases. Together with the rule guard this makes the exclusion hold in both directions of configuration.';

DROP TRIGGER IF EXISTS b_enforce_surcharge_rider_not_taxable ON public.rate_item_versions;
CREATE TRIGGER b_enforce_surcharge_rider_not_taxable BEFORE INSERT OR UPDATE OF is_taxable_default, is_a_tax ON public.rate_item_versions
    FOR EACH ROW EXECUTE FUNCTION public.enforce_surcharge_rider_not_taxable();
DROP TRIGGER IF EXISTS b_enforce_surcharge_rider_not_taxable ON public.rate_schedule_items;
CREATE TRIGGER b_enforce_surcharge_rider_not_taxable BEFORE INSERT OR UPDATE OF is_taxable_override ON public.rate_schedule_items
    FOR EACH ROW EXECUTE FUNCTION public.enforce_surcharge_rider_not_taxable();

-- ----------------------------------------------------------------------------
-- 3. customers.is_state_agency — the exemption designation, with history
-- ----------------------------------------------------------------------------
ALTER TABLE public.customers ADD COLUMN IF NOT EXISTS is_state_agency boolean DEFAULT false NOT NULL;
ALTER TABLE public.customers DROP CONSTRAINT IF EXISTS customers_state_agency_is_government_check;
ALTER TABLE public.customers ADD CONSTRAINT customers_state_agency_is_government_check
    CHECK ((NOT is_state_agency) OR (customer_type = 'government'::text));

COMMENT ON COLUMN public.customers.is_state_agency IS
    'CI-038 (v5.4.2-07, A-7): the account is an agency of the State of Texas and is exempt from the Pipeline Safety Fee surcharge (16 TAC §8.201) and from any other rider whose rule exempts_state_agencies. Narrower than customer_type = ''government'' (cities, counties, school districts are government and NOT exempt) — CHECK: only a government customer may be flagged. Every change is logged to customer_attribute_history (attribute is_state_agency); the exemption is evaluated for the billed period through customer_is_state_agency_as_of(). Whether the designation needs a verifying document is open with Kyle.';

ALTER TABLE public.customer_attribute_history DROP CONSTRAINT IF EXISTS customer_attribute_history_attribute_check;
ALTER TABLE public.customer_attribute_history ADD CONSTRAINT customer_attribute_history_attribute_check CHECK ((attribute = ANY (ARRAY[
    'billing_delivery_method'::text, 'billing_hold'::text, 'consolidate_invoices'::text, 'do_not_disconnect'::text,
    'landlord_responsible'::text, 'customer_type'::text, 'autopay_enabled'::text, 'deposit_status'::text, 'is_state_agency'::text])));

-- 3.1 A-21's logger re-issued with the ninth attribute (body otherwise unchanged).
CREATE OR REPLACE FUNCTION public.log_customer_attribute_changes() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, source)
        SELECT NEW.tenant_id, NEW.id, a.attribute, NULL,
               CASE a.attribute
                   WHEN 'billing_delivery_method' THEN NEW.billing_delivery_method
                   WHEN 'billing_hold' THEN NEW.billing_hold::text
                   WHEN 'consolidate_invoices' THEN NEW.consolidate_invoices::text
                   WHEN 'do_not_disconnect' THEN NEW.do_not_disconnect::text
                   WHEN 'landlord_responsible' THEN NEW.landlord_responsible::text
                   WHEN 'customer_type' THEN NEW.customer_type
                   WHEN 'deposit_status' THEN NEW.deposit_status
                   WHEN 'autopay_enabled' THEN 'false'
                   WHEN 'is_state_agency' THEN NEW.is_state_agency::text
               END,
               NEW.status_changed_at, 'initial'
          FROM (SELECT unnest(ARRAY['billing_delivery_method', 'billing_hold', 'consolidate_invoices', 'do_not_disconnect', 'landlord_responsible', 'customer_type', 'deposit_status', 'autopay_enabled', 'is_state_agency']) AS attribute) a;
        RETURN NULL;
    END IF;
    IF OLD.billing_delivery_method IS DISTINCT FROM NEW.billing_delivery_method THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'billing_delivery_method', OLD.billing_delivery_method, NEW.billing_delivery_method, clock_timestamp());
    END IF;
    IF OLD.billing_hold IS DISTINCT FROM NEW.billing_hold THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, changed_by) VALUES (NEW.tenant_id, NEW.id, 'billing_hold', OLD.billing_hold::text, NEW.billing_hold::text, clock_timestamp(), NEW.billing_hold_set_by);
    END IF;
    IF OLD.consolidate_invoices IS DISTINCT FROM NEW.consolidate_invoices THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'consolidate_invoices', OLD.consolidate_invoices::text, NEW.consolidate_invoices::text, clock_timestamp());
    END IF;
    IF OLD.do_not_disconnect IS DISTINCT FROM NEW.do_not_disconnect THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'do_not_disconnect', OLD.do_not_disconnect::text, NEW.do_not_disconnect::text, clock_timestamp());
    END IF;
    IF OLD.landlord_responsible IS DISTINCT FROM NEW.landlord_responsible THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'landlord_responsible', OLD.landlord_responsible::text, NEW.landlord_responsible::text, clock_timestamp());
    END IF;
    IF OLD.customer_type IS DISTINCT FROM NEW.customer_type THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'customer_type', OLD.customer_type, NEW.customer_type, clock_timestamp());
    END IF;
    IF OLD.deposit_status IS DISTINCT FROM NEW.deposit_status THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, source) VALUES (NEW.tenant_id, NEW.id, 'deposit_status', OLD.deposit_status, NEW.deposit_status, clock_timestamp(), 'system');
    END IF;
    IF OLD.is_state_agency IS DISTINCT FROM NEW.is_state_agency THEN
        INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at) VALUES (NEW.tenant_id, NEW.id, 'is_state_agency', OLD.is_state_agency::text, NEW.is_state_agency::text, clock_timestamp());
    END IF;
    RETURN NULL;
END;
$$;

COMMENT ON FUNCTION public.log_customer_attribute_changes() IS
    'CI-121 (v5.4.2-06, re-issued v5.4.2-07 for is_state_agency): writes customer_attribute_history — the initial value of every tracked attribute at INSERT (effective_at = status_changed_at, source initial) and one row per changed attribute at UPDATE (effective_at = clock_timestamp()). Nine attributes since A-7.';

-- 3.2 Backfill: one history row per pre-existing customer (guarded; no-op on a fresh deploy).
DO $$
DECLARE v integer;
BEGIN
    INSERT INTO public.customer_attribute_history (tenant_id, customer_id, attribute, old_value, new_value, effective_at, source)
    SELECT c.tenant_id, c.id, 'is_state_agency', NULL, c.is_state_agency::text, c.created_at, 'backfill'
      FROM public.customers c
     WHERE NOT EXISTS (SELECT 1 FROM public.customer_attribute_history h WHERE h.customer_id = c.id AND h.attribute = 'is_state_agency');
    GET DIAGNOSTICS v = ROW_COUNT;
    IF v > 0 THEN RAISE NOTICE 'v5.4.2-07: % is_state_agency attribute-history backfill row(s) written at created_at (current value; history before this patch is unknown)', v; END IF;
END;
$$;

-- 3.3 The event tables are written by the database. A-21 left INSERT on
--     customer_state_events / customer_attribute_history open to tally_app
--     with no fence (Fable HIGH-3: a direct is_state_agency = 'false' row —
--     or 'banana' — cancelled the exemption without touching customers).
--     A direct insert (depth < 2 inside the guard) is refused unless the writer is a superuser (a
--     migration backfill — 3.2 above, and A-21's own); TEMP is revoked so
--     the depth fence is structural (D-2026-08-28-37). Boolean attributes
--     carry 'true' / 'false' only.
CREATE OR REPLACE FUNCTION public.enforce_event_written_by_db() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
BEGIN
    -- inside this trigger a direct statement is depth 1; the logger's inserts are depth 2
    IF pg_trigger_depth() < 2 AND NOT (SELECT r.rolsuper FROM pg_roles r WHERE r.rolname = current_user) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('%s is written by the database (CI-121): change the customer row and let the logger record it — a direct insert is not history', TG_TABLE_NAME),
            ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
END;
$$;
COMMENT ON FUNCTION public.enforce_event_written_by_db() IS 'v5.4.2-07 (A-7, closing an A-21 gap): BEFORE INSERT on customer_state_events and customer_attribute_history — refused for a direct statement (pg_trigger_depth() < 2 inside the guard) unless the writer is a superuser (migrations). With TEMP revoked from the app role the depth is a structural fence.';

DROP TRIGGER IF EXISTS a_enforce_event_written_by_db ON public.customer_attribute_history;
CREATE TRIGGER a_enforce_event_written_by_db BEFORE INSERT ON public.customer_attribute_history
    FOR EACH ROW EXECUTE FUNCTION public.enforce_event_written_by_db();
DROP TRIGGER IF EXISTS a_enforce_event_written_by_db ON public.customer_state_events;
CREATE TRIGGER a_enforce_event_written_by_db BEFORE INSERT ON public.customer_state_events
    FOR EACH ROW EXECUTE FUNCTION public.enforce_event_written_by_db();

ALTER TABLE public.customer_attribute_history DROP CONSTRAINT IF EXISTS customer_attribute_history_boolean_values_check;
ALTER TABLE public.customer_attribute_history ADD CONSTRAINT customer_attribute_history_boolean_values_check CHECK (
    (attribute <> ALL (ARRAY['billing_hold'::text, 'consolidate_invoices'::text, 'do_not_disconnect'::text, 'landlord_responsible'::text, 'autopay_enabled'::text, 'is_state_agency'::text]))
    OR ((new_value = ANY (ARRAY['true'::text, 'false'::text])) AND ((old_value IS NULL) OR (old_value = ANY (ARRAY['true'::text, 'false'::text])))));

-- 3.4 The read the exemption uses: the value in force at the END of a date,
--     with the day boundary pinned to Central time (the fee is a Texas
--     assessment; a session TimeZone must not move the boundary — Fable
--     MEDIUM-1). El Paso''s Mountain-time hour is accepted as within the
--     day-level precision of the rule.
CREATE OR REPLACE FUNCTION public.customer_is_state_agency_as_of(p_customer_id uuid, p_on date) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v text;
BEGIN
    IF p_on IS NULL THEN
        RAISE EXCEPTION 'customer_is_state_agency_as_of: p_on is required (the end of the billed period); never default to today';
    END IF;
    v := public.customer_attribute_as_of(p_customer_id, 'is_state_agency', ((p_on + 1)::timestamp AT TIME ZONE 'America/Chicago'));
    IF v IS NULL THEN
        -- the period predates the account's recorded history: the earliest recorded value is the best knowledge there is
        SELECT h.new_value INTO v FROM public.customer_attribute_history h
         WHERE h.customer_id = p_customer_id AND h.attribute = 'is_state_agency'
         ORDER BY h.effective_at, h.seq LIMIT 1;
    END IF;
    IF v IS NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = format('customer_is_state_agency_as_of: customer %s has no is_state_agency history (not visible, or written outside the attribute logger)', p_customer_id),
            ERRCODE = 'no_data_found';
    END IF;
    RETURN v = 'true';
END;
$$;

COMMENT ON FUNCTION public.customer_is_state_agency_as_of(uuid, date) IS
    'A-7 (v5.4.2-07): was the account a state agency at the end of p_on (midnight America/Chicago), per customer_attribute_history? A date before the account''s first recorded value answers with that first value; no history at all raises. Never reads the live customers row. Invoker rights: RLS applies.';

-- ----------------------------------------------------------------------------
-- 4. invoice_line_item_bases — the per-bill base composition (CI-045)
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.invoice_line_item_bases (
    id                 uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    tenant_id          uuid NOT NULL,
    invoice_id         uuid NOT NULL,
    line_item_id       uuid NOT NULL,
    base_line_item_id  uuid NOT NULL,
    base_amount        numeric(12,2) NOT NULL,
    created_at         timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT invoice_line_item_bases_pkey PRIMARY KEY (id),
    CONSTRAINT invoice_line_item_bases_unique UNIQUE (line_item_id, base_line_item_id),
    CONSTRAINT invoice_line_item_bases_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT invoice_line_item_bases_invoice_fkey FOREIGN KEY (invoice_id, tenant_id) REFERENCES public.invoices(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT invoice_line_item_bases_line_fkey FOREIGN KEY (line_item_id, tenant_id) REFERENCES public.invoice_line_items(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT invoice_line_item_bases_base_fkey FOREIGN KEY (base_line_item_id, tenant_id) REFERENCES public.invoice_line_items(id, tenant_id) ON DELETE CASCADE,
    CONSTRAINT invoice_line_item_bases_not_self_check CHECK ((line_item_id <> base_line_item_id)),
    CONSTRAINT invoice_line_item_bases_amount_nonzero_check CHECK ((base_amount <> (0)::numeric))
);

-- A draft invoice may be discarded (A-4); its composition goes with it, the
-- way its lines and snapshot do. Re-issued as CASCADE if an earlier apply
-- created it as NO ACTION.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'invoice_line_item_bases_invoice_fkey' AND conrelid = 'public.invoice_line_item_bases'::regclass AND confdeltype <> 'c') THEN
        ALTER TABLE public.invoice_line_item_bases DROP CONSTRAINT invoice_line_item_bases_invoice_fkey;
        ALTER TABLE public.invoice_line_item_bases ADD CONSTRAINT invoice_line_item_bases_invoice_fkey FOREIGN KEY (invoice_id, tenant_id) REFERENCES public.invoices(id, tenant_id) ON DELETE CASCADE;
    END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_invoice_line_item_bases_tenant ON public.invoice_line_item_bases USING btree (tenant_id);
CREATE INDEX IF NOT EXISTS idx_invoice_line_item_bases_invoice ON public.invoice_line_item_bases USING btree (invoice_id);
CREATE INDEX IF NOT EXISTS idx_invoice_line_item_bases_base ON public.invoice_line_item_bases USING btree (base_line_item_id);

ALTER TABLE public.invoice_line_item_bases ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.invoice_line_item_bases FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.invoice_line_item_bases;
CREATE POLICY tenant_isolation ON public.invoice_line_item_bases USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));

COMMENT ON TABLE public.invoice_line_item_bases IS
    'CI-045 (v5.4.2-07, A-7). The materialized base composition of a bill: one row per (tax / percentage line, line it was computed on, amount of that line taken into the base). Written by the calculation with the lines, before the snapshot; frozen with the invoice (INSERT / UPDATE / DELETE refused once issued — the A-4 line rule). Every non-zero tax or percentage line must have at least one row at issuance (enforce_invoice_surcharge_lines_and_bases). A line of a rider whose regulatory_surcharge_rules row says excluded_from_tax_bases can never be cited (CI-038: the PSF is not a base for franchise fee, gas-utility tax or sales tax). Whether a tax line may cite another tax line (tax-on-tax) is a jurisdiction rule (#23 stage 3, A-8) and is not decided here.';
COMMENT ON COLUMN public.invoice_line_item_bases.base_amount IS 'The part of the cited line''s amount that entered this base: non-zero, same sign as, and no larger in magnitude than the cited line''s amount (a partially taxable line contributes its taxable part).';

-- 4.1 Shared classification helper: is this line one that carries a base?
--     (a tax line, or a percentage_of_bill / percentage_of_charges rate item
--     at the given coordinate)
CREATE OR REPLACE FUNCTION public.line_item_carries_base(p_line public.invoice_line_items, p_valid_at date, p_recorded_at timestamp with time zone) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_calc text;
BEGIN
    IF p_line.charge_type = 'tax' THEN
        RETURN true;
    END IF;
    IF p_line.rate_item_id IS NULL THEN
        RETURN false;
    END IF;
    SELECT v.calculation_type INTO v_calc FROM public.rate_item_as_of(p_line.rate_item_id, p_valid_at, p_recorded_at) v;
    RETURN coalesce(v_calc IN ('percentage_of_bill', 'percentage_of_charges'), false);
END;
$$;

COMMENT ON FUNCTION public.line_item_carries_base(public.invoice_line_items, date, timestamp with time zone) IS
    'A-7 helper: true for a charge_type = ''tax'' line and for a line whose rate item is percentage_of_bill / percentage_of_charges at (p_valid_at, p_recorded_at). These are the lines invoice_line_item_bases may describe and must describe when non-zero.';

-- 4.2 The bases guard.
CREATE OR REPLACE FUNCTION public.enforce_invoice_line_item_base() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_inv   public.invoices%ROWTYPE;
    v_line  public.invoice_line_items%ROWTYPE;
    v_base  public.invoice_line_items%ROWTYPE;
    v_rule  public.regulatory_surcharge_rules%ROWTYPE;
    v_invoice_id uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.invoice_id ELSE NEW.invoice_id END;
BEGIN
    -- The invoice row is locked FOR SHARE so a concurrent issuance (an
    -- UPDATE of status holding the row lock) is waited for and then seen.
    SELECT * INTO v_inv FROM public.invoices i WHERE i.id = v_invoice_id FOR SHARE;
    IF NOT FOUND THEN
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;      -- only reachable through the cascade of a draft-invoice delete (A-3's snapshot rule)
        END IF;
        RAISE EXCEPTION USING
            MESSAGE = format('invoice_line_item_bases: invoice %s is not visible in this tenant', v_invoice_id),
            ERRCODE = 'foreign_key_violation';
    END IF;
    IF public.is_invoice_issued(v_inv.status) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s is issued (status %s): its base composition is immutable (CI-012 / CI-045) — %s rejected; correct it with void_invoice() + rebill', v_inv.invoice_number, v_inv.status, TG_OP),
            ERRCODE = 'restrict_violation';
    END IF;
    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    IF NEW.tenant_id <> v_inv.tenant_id THEN
        RAISE EXCEPTION USING MESSAGE = 'invoice_line_item_bases: tenant_id must equal the invoice''s tenant', ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO v_line FROM public.invoice_line_items l WHERE l.id = NEW.line_item_id;
    IF NOT FOUND OR v_line.invoice_id <> NEW.invoice_id THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice_line_item_bases: line %s is not a line of invoice %s', NEW.line_item_id, v_inv.invoice_number),
            ERRCODE = 'check_violation';
    END IF;
    SELECT * INTO v_base FROM public.invoice_line_items l WHERE l.id = NEW.base_line_item_id;
    IF NOT FOUND OR v_base.invoice_id <> NEW.invoice_id THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice_line_item_bases: base line %s is not a line of invoice %s', NEW.base_line_item_id, v_inv.invoice_number),
            ERRCODE = 'check_violation';
    END IF;
    IF NOT public.line_item_carries_base(v_line, v_inv.period_end, now()) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice_line_item_bases: line %s (%s) is neither a tax line nor a percentage rate item — only those carry a base composition (CI-045)', v_line.id, v_line.description),
            ERRCODE = 'check_violation';
    END IF;
    IF sign(NEW.base_amount) <> sign(v_base.amount) OR abs(NEW.base_amount) > abs(v_base.amount) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice_line_item_bases: base_amount %s must have the sign of, and not exceed, the cited line''s amount %s (line %s)', NEW.base_amount, v_base.amount, v_base.description),
            ERRCODE = 'check_violation';
    END IF;
    IF v_base.rate_item_id IS NOT NULL THEN
        SELECT r.* INTO v_rule FROM public.regulatory_surcharge_rule_as_of(v_base.rate_item_id, v_inv.invoice_date, now()) r;
        IF FOUND AND v_rule.excluded_from_tax_bases THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice_line_item_bases: line %s is a %s surcharge excluded from every tax base (regulatory_surcharge_rules %s) and cannot enter the base of %s (CI-038 / 16 TAC §8.201)', v_base.description, v_rule.surcharge_kind, v_rule.id, v_line.description),
                ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_invoice_line_item_base() IS
    'CI-045 / CI-038 (v5.4.2-07): BEFORE INSERT / UPDATE / DELETE on invoice_line_item_bases. Parent invoice visible and not issued (frozen after); both lines on that invoice; the citing line carries a base (tax or percentage item as of (period_end, now()) — lines precede the snapshot); base_amount sign-consistent and bounded by the cited line; a cited line whose rider is excluded_from_tax_bases for the bill date is refused. Issuance re-checks at the snapshot coordinate.';

DROP TRIGGER IF EXISTS enforce_invoice_line_item_base ON public.invoice_line_item_bases;
CREATE TRIGGER enforce_invoice_line_item_base BEFORE INSERT OR UPDATE OR DELETE ON public.invoice_line_item_bases
    FOR EACH ROW EXECUTE FUNCTION public.enforce_invoice_line_item_base();
DROP TRIGGER IF EXISTS no_truncate ON public.invoice_line_item_bases;
CREATE TRIGGER no_truncate BEFORE TRUNCATE ON public.invoice_line_item_bases
    FOR EACH STATEMENT EXECUTE FUNCTION public.enforce_no_hard_delete();

-- ----------------------------------------------------------------------------
-- 5. Surcharge line discipline on invoice_line_items
-- ----------------------------------------------------------------------------
-- 5.0 The per-(rider, service) mutex the cap check serialises on. A row is
--     upserted (touched) before the cycle total is summed: under READ
--     COMMITTED the second writer waits on the row lock and then sums with
--     a fresh snapshot; under REPEATABLE READ / SERIALIZABLE the second
--     writer's UPDATE of a row the first writer changed raises a
--     serialization failure instead of passing on a stale sum (Fable
--     HIGH-4 — an advisory lock serialised the writers but not their
--     snapshots). Not a projection: it carries no total.
CREATE TABLE IF NOT EXISTS public.regulatory_surcharge_service_locks (
    tenant_id     uuid NOT NULL,
    rate_item_id  uuid NOT NULL,
    meter_id      uuid NOT NULL,
    touched_at    timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT regulatory_surcharge_service_locks_pkey PRIMARY KEY (rate_item_id, meter_id),
    CONSTRAINT regulatory_surcharge_service_locks_tenant_id_fkey FOREIGN KEY (tenant_id) REFERENCES public.tenants(id),
    CONSTRAINT regulatory_surcharge_service_locks_rate_item_fkey FOREIGN KEY (rate_item_id, tenant_id) REFERENCES public.rate_items(id, tenant_id),
    CONSTRAINT regulatory_surcharge_service_locks_meter_fkey FOREIGN KEY (meter_id, tenant_id) REFERENCES public.meters(id, tenant_id)
);
CREATE INDEX IF NOT EXISTS idx_regulatory_surcharge_service_locks_tenant ON public.regulatory_surcharge_service_locks USING btree (tenant_id);
ALTER TABLE public.regulatory_surcharge_service_locks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.regulatory_surcharge_service_locks FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON public.regulatory_surcharge_service_locks;
CREATE POLICY tenant_isolation ON public.regulatory_surcharge_service_locks USING ((public.is_platform_admin() OR (tenant_id = public.get_user_tenant_id())));
REVOKE DELETE ON public.regulatory_surcharge_service_locks FROM tally_app;
COMMENT ON TABLE public.regulatory_surcharge_service_locks IS
    'v5.4.2-07 (A-7): serialisation rows for the per-service surcharge cap — one per (rider, meter), touched by assert_surcharge_line() before it sums the cycle. Under READ COMMITTED concurrent writers queue on the row; under REPEATABLE READ / SERIALIZABLE the loser gets a serialization failure and must retry with a fresh snapshot. Carries no amount: the cap total is always summed from invoice_line_items.';

-- 5.1 The checks, shared by the line guard and the issuance gate — both on
--     CURRENT knowledge (now()): the cap, the exemption and the exclusion
--     are facts about the bill being issued, not about what the run knew
--     (Fable HIGH-2: the snapshot's coordinate pair is caller-chosen).
--     Silent when the line's rate item has no rule for the invoice's bill
--     date.
CREATE OR REPLACE FUNCTION public.assert_surcharge_line(p_line public.invoice_line_items, p_recorded_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_inv  public.invoices%ROWTYPE;
    v_rule public.regulatory_surcharge_rules%ROWTYPE;
    v_sum  numeric;
BEGIN
    IF p_line.rate_item_id IS NULL THEN
        RETURN;
    END IF;
    SELECT * INTO v_inv FROM public.invoices i WHERE i.id = p_line.invoice_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice_line_items: invoice %s is not visible in this tenant', p_line.invoice_id),
            ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_inv.tenant_id <> p_line.tenant_id THEN
        RAISE EXCEPTION USING MESSAGE = 'invoice_line_items: tenant_id must equal the invoice''s tenant', ERRCODE = 'check_violation';
    END IF;
    SELECT r.* INTO v_rule FROM public.regulatory_surcharge_rule_as_of(p_line.rate_item_id, v_inv.invoice_date, p_recorded_at) r;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF p_line.charge_type = 'tax' THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s: line %s is a %s surcharge rider (regulatory_surcharge_rules %s), not a tax — charge_type ''tax'' rejected (CI-038)', v_inv.invoice_number, p_line.description, v_rule.surcharge_kind, v_rule.id),
            ERRCODE = 'check_violation';
    END IF;
    IF v_rule.excluded_from_tax_bases THEN
        IF p_line.is_taxable OR coalesce(p_line.taxable_amount, 0) <> 0 THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s: line %s is a %s surcharge excluded from every tax base — is_taxable must be false and taxable_amount empty (CI-038 / 16 TAC §8.201; rule %s)', v_inv.invoice_number, p_line.description, v_rule.surcharge_kind, v_rule.id),
                ERRCODE = 'check_violation';
        END IF;
        IF EXISTS (SELECT 1 FROM public.invoice_line_item_bases b WHERE b.base_line_item_id = p_line.id) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s: line %s is a %s surcharge excluded from every tax base but is cited as a base by another line (CI-038 / CI-045; rule %s)', v_inv.invoice_number, p_line.description, v_rule.surcharge_kind, v_rule.id),
                ERRCODE = 'check_violation';
        END IF;
    END IF;
    IF v_rule.exempts_state_agencies AND p_line.amount <> 0 AND public.customer_is_state_agency_as_of(v_inv.customer_id, v_inv.period_end) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('invoice %s: the customer was a state agency at the end of the billed period (%s) and is exempt from the %s surcharge — line %s must be 0.00 (CI-038; rule %s)', v_inv.invoice_number, v_inv.period_end, v_rule.surcharge_kind, p_line.description, v_rule.id),
            ERRCODE = 'check_violation';
    END IF;
    IF v_rule.cap_per_service IS NOT NULL THEN
        IF p_line.meter_id IS NULL THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s: line %s is a %s surcharge capped per service (%s over the cycle %s..%s) and must name its service — meter_id is required (CI-038; rule %s)', v_inv.invoice_number, p_line.description, v_rule.surcharge_kind, v_rule.cap_per_service, v_rule.cycle_start, v_rule.cycle_end, v_rule.id),
                ERRCODE = 'check_violation';
        END IF;
        -- serialise concurrent lines for one (rider, service) on the mutex row (5.0)
        INSERT INTO public.regulatory_surcharge_service_locks (tenant_id, rate_item_id, meter_id)
        VALUES (p_line.tenant_id, p_line.rate_item_id, p_line.meter_id)
        ON CONFLICT (rate_item_id, meter_id) DO UPDATE SET touched_at = clock_timestamp();
        -- Only POSITIVE amounts count toward the cap: a negative line (a
        -- correction) never lends headroom, because the invoice carrying it
        -- can be discarded or voided later (Fable HIGH-1). The path to bill
        -- again is void + rebill, which releases the voided amount.
        SELECT coalesce(sum(greatest(l.amount, 0)), 0) INTO v_sum
          FROM public.invoice_line_items l
          JOIN public.invoices i ON i.id = l.invoice_id
         WHERE l.tenant_id = p_line.tenant_id
           AND l.rate_item_id = p_line.rate_item_id
           AND l.meter_id = p_line.meter_id
           AND l.id <> p_line.id
           AND i.status <> 'void'
           AND i.invoice_date >= v_rule.cycle_start AND i.invoice_date <= v_rule.cycle_end;
        IF v_sum + p_line.amount > v_rule.cap_per_service THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s: line %s would bring the %s surcharge on this service to %s for the cycle %s..%s (%s already billed on non-void invoices and drafts, positive lines only, + %s), over the cap of %s per service (CI-038 / 16 TAC §8.201; rule %s)', v_inv.invoice_number, p_line.description, v_rule.surcharge_kind, v_sum + p_line.amount, v_rule.cycle_start, v_rule.cycle_end, v_sum, p_line.amount, v_rule.cap_per_service, v_rule.id),
                ERRCODE = 'check_violation';
        END IF;
    END IF;
END;
$$;

COMMENT ON FUNCTION public.assert_surcharge_line(public.invoice_line_items, timestamp with time zone) IS
    'CI-038 (v5.4.2-07): the surcharge line rules, applied when the line''s rate item has a regulatory_surcharge_rules row for the invoice''s bill date at p_recorded_at (otherwise silent). Never charge_type = ''tax''; excluded_from_tax_bases → is_taxable false, no taxable_amount, cited by no base row; exempts_state_agencies → 0.00 for a customer that was a state agency at period_end (attribute history, never the live row); cap_per_service → meter_id required and the cycle''s cumulative POSITIVE amounts for (rate item, meter) over non-void invoices — drafts included, this line excluded by id then added — must not exceed the cap; the transaction first touches the (rate item, meter) row of regulatory_surcharge_service_locks. Called with now() by the line guard and by the issuance gate (current knowledge — the snapshot coordinate is the run''s record, not the judge).';

-- 5.2 The line guard — runs after A-4's immutability guard (name order).
CREATE OR REPLACE FUNCTION public.enforce_surcharge_line() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_bad  record;
    v_inv  public.invoices%ROWTYPE;
    v_rule public.regulatory_surcharge_rules%ROWTYPE;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- A surcharge line keeps its rider link: nulling or swapping
        -- rate_item_id detached the line from every cap / exclusion check
        -- while it kept its description and amount (Codex CRITICAL-1). The
        -- OLD rider's rule for the bill date decides; a genuine
        -- reclassification is delete + new line.
        IF NEW.rate_item_id IS DISTINCT FROM OLD.rate_item_id AND OLD.rate_item_id IS NOT NULL THEN
            SELECT * INTO v_inv FROM public.invoices i WHERE i.id = OLD.invoice_id;
            IF FOUND THEN
                SELECT r.* INTO v_rule FROM public.regulatory_surcharge_rule_as_of(OLD.rate_item_id, v_inv.invoice_date, now()) r;
                IF FOUND THEN
                    RAISE EXCEPTION USING
                        MESSAGE = format('line %s (%s) is a %s surcharge line (rule %s): its rate_item_id cannot be changed or removed — delete the line and write a new one (CI-038)', OLD.id, OLD.description, v_rule.surcharge_kind, v_rule.id),
                        ERRCODE = 'check_violation';
                END IF;
            END IF;
        END IF;
        -- A line with a base composition (on either side) stays on its invoice:
        -- re-parenting it would carry rows that describe another bill.
        IF NEW.invoice_id IS DISTINCT FROM OLD.invoice_id
           AND EXISTS (SELECT 1 FROM public.invoice_line_item_bases b WHERE b.line_item_id = OLD.id OR b.base_line_item_id = OLD.id) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('line %s (%s) has a base composition (invoice_line_item_bases) and cannot be moved to another invoice — delete the composition first (CI-045)', OLD.id, OLD.description),
                ERRCODE = 'check_violation';
        END IF;
        -- A cited line cannot shrink under, or flip the sign of, what a base already took from it.
        IF NEW.amount IS DISTINCT FROM OLD.amount THEN
            SELECT b.base_amount, cl.description INTO v_bad
              FROM public.invoice_line_item_bases b
              JOIN public.invoice_line_items cl ON cl.id = b.line_item_id
             WHERE b.base_line_item_id = OLD.id
               AND (sign(b.base_amount) <> sign(NEW.amount) OR abs(b.base_amount) > abs(NEW.amount))
             LIMIT 1;
            IF FOUND THEN
                RAISE EXCEPTION USING
                    MESSAGE = format('line %s (%s) cannot change to %s: %s of it is already in the base of %s (invoice_line_item_bases) — adjust the composition first (CI-045)', OLD.id, OLD.description, NEW.amount, v_bad.base_amount, v_bad.description),
                    ERRCODE = 'check_violation';
            END IF;
        END IF;
    END IF;
    PERFORM public.assert_surcharge_line(NEW, now());
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.enforce_surcharge_line() IS 'v5.4.2-07: BEFORE INSERT / UPDATE on invoice_line_items — a surcharge line''s rate_item_id is frozen (the OLD rider''s rule for the bill date decides); a draft line that has a base composition (either side) cannot be moved to another invoice, and a cited line cannot change amount under what a base took from it; then assert_surcharge_line(NEW, now()).';

DROP TRIGGER IF EXISTS z_enforce_surcharge_line ON public.invoice_line_items;
CREATE TRIGGER z_enforce_surcharge_line BEFORE INSERT OR UPDATE OF rate_item_id, amount, meter_id, is_taxable, taxable_amount, invoice_id, charge_type ON public.invoice_line_items
    FOR EACH ROW EXECUTE FUNCTION public.enforce_surcharge_line();

-- 5.3 The issuance gate: base completeness + re-check at the snapshot coordinate.
CREATE OR REPLACE FUNCTION public.enforce_invoice_surcharge_lines_and_bases() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_snap public.invoice_calculation_snapshots%ROWTYPE;
    v_line public.invoice_line_items%ROWTYPE;
    v_base record;
    v_rule public.regulatory_surcharge_rules%ROWTYPE;
BEGIN
    IF NOT public.is_invoice_issued(NEW.status) THEN
        RETURN NULL;
    END IF;
    IF TG_OP = 'UPDATE' AND public.is_invoice_issued(OLD.status) THEN
        RETURN NULL;
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.status = 'void' THEN
        RETURN NULL;         -- discarding a draft/held invoice is not an issuance (A-3's rule)
    END IF;
    SELECT * INTO v_snap FROM public.invoice_calculation_snapshots s WHERE s.invoice_id = NEW.id;
    IF NOT FOUND THEN
        RETURN NULL;         -- enforce_invoice_has_snapshot (queued first) raises for this
    END IF;
    -- Every check below runs on CURRENT knowledge — (invoice_date, now()) for
    -- the rules, (period_end, now()) for the classification. The snapshot's
    -- pair is caller-supplied (A-3 refuses only a future recorded_at and
    -- does not bind valid_at) and would let a backdated coordinate hide the
    -- rule or the rider's calculation type (Fable HIGH-2).
    PERFORM 1 FROM public.invoice_line_items l WHERE l.invoice_id = NEW.id FOR SHARE;
    FOR v_line IN SELECT l.* FROM public.invoice_line_items l WHERE l.invoice_id = NEW.id ORDER BY l.line_order, l.id LOOP
        -- (a) the surcharge rules
        PERFORM public.assert_surcharge_line(v_line, now());
        -- (b) base completeness for non-zero tax / percentage lines
        IF v_line.amount <> 0 AND public.line_item_carries_base(v_line, NEW.period_end, now())
           AND NOT EXISTS (SELECT 1 FROM public.invoice_line_item_bases b WHERE b.line_item_id = v_line.id AND b.invoice_id = NEW.id) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s cannot be issued: line %s (%s) is a tax / percentage charge with no base composition in invoice_line_item_bases (CI-045 — the base is materialized, not assembled ad hoc)', NEW.invoice_number, v_line.line_order, v_line.description),
                ERRCODE = 'check_violation';
        END IF;
    END LOOP;
    -- (c) every base row: both lines on this invoice, bounds still hold, and the
    --     exclusion as the run knew it
    FOR v_base IN
        SELECT b.id AS base_row_id, b.base_amount, bl.invoice_id AS base_invoice_id, bl.amount AS base_line_amount, bl.rate_item_id,
               bl.description AS base_description, cl.invoice_id AS line_invoice_id, cl.description AS line_description, cl AS citing_line
          FROM public.invoice_line_item_bases b
          JOIN public.invoice_line_items bl ON bl.id = b.base_line_item_id
          JOIN public.invoice_line_items cl ON cl.id = b.line_item_id
         WHERE b.invoice_id = NEW.id
    LOOP
        IF v_base.base_invoice_id <> NEW.id OR v_base.line_invoice_id <> NEW.id THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s cannot be issued: a base row (%s ← %s) cites a line that is no longer on this invoice (CI-045)', NEW.invoice_number, v_base.line_description, v_base.base_description),
                ERRCODE = 'check_violation';
        END IF;
        -- the citing line must still be one that carries a base (a rider re-classified
        -- to a fixed charge after the row was written would freeze a false composition — Codex MEDIUM-3)
        IF NOT public.line_item_carries_base(v_base.citing_line, NEW.period_end, now()) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s cannot be issued: %s carries a base composition but is no longer a tax / percentage charge — delete its base rows (CI-045)', NEW.invoice_number, v_base.line_description),
                ERRCODE = 'check_violation';
        END IF;
        IF sign(v_base.base_amount) <> sign(v_base.base_line_amount) OR abs(v_base.base_amount) > abs(v_base.base_line_amount) THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s cannot be issued: base row (%s ← %s) takes %s from a line whose amount is now %s (CI-045)', NEW.invoice_number, v_base.line_description, v_base.base_description, v_base.base_amount, v_base.base_line_amount),
                ERRCODE = 'check_violation';
        END IF;
        IF v_base.rate_item_id IS NULL THEN
            CONTINUE;
        END IF;
        SELECT r.* INTO v_rule FROM public.regulatory_surcharge_rule_as_of(v_base.rate_item_id, NEW.invoice_date, now()) r;
        IF FOUND AND v_rule.excluded_from_tax_bases THEN
            RAISE EXCEPTION USING
                MESSAGE = format('invoice %s cannot be issued: %s is a %s surcharge excluded from every tax base but enters the base of %s (CI-038 / CI-045; rule %s)', NEW.invoice_number, v_base.base_description, v_rule.surcharge_kind, v_base.line_description, v_rule.id),
                ERRCODE = 'check_violation';
        END IF;
    END LOOP;
    RETURN NULL;
END;
$$;

COMMENT ON FUNCTION public.enforce_invoice_surcharge_lines_and_bases() IS
    'CI-038 / CI-045 completeness (v5.4.2-07): at commit of any transaction that moves an invoice into an issued status (the A-3 shape; a draft/held void is exempt), on current knowledge — the snapshot must exist (A-3''s gate) but its caller-supplied coordinate is not trusted: every line passes assert_surcharge_line at now(); every non-zero tax / percentage line (line_item_carries_base at (period_end, now())) has at least one invoice_line_item_bases row on this invoice; every base row cites two lines of this invoice, its citing line still carries a base, within bounds, and none of them an excluded surcharge line. Queued after enforce_invoice_has_snapshot (name order) so a missing snapshot is reported by that gate. Locks the lines FOR SHARE.';

DROP TRIGGER IF EXISTS enforce_invoice_surcharge_lines_and_bases ON public.invoices;
CREATE CONSTRAINT TRIGGER enforce_invoice_surcharge_lines_and_bases
    AFTER INSERT OR UPDATE ON public.invoices
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION public.enforce_invoice_surcharge_lines_and_bases();

-- ----------------------------------------------------------------------------
-- 6. Provenance: the rules table joins the citable set (A-3)
-- ----------------------------------------------------------------------------
ALTER TABLE public.invoice_snapshot_references DROP CONSTRAINT IF EXISTS invoice_snapshot_references_source_table_check;
ALTER TABLE public.invoice_snapshot_references ADD CONSTRAINT invoice_snapshot_references_source_table_check CHECK ((source_table = ANY (ARRAY[
    'rate_schedule_versions'::text, 'wna_zone_versions'::text, 'rate_item_versions'::text,
    'rate_schedule_items'::text, 'franchise_fee_rules'::text, 'customer_tax_exemptions'::text, 'wna_monthly_adjustments'::text,
    'regulatory_surcharge_rules'::text])));

CREATE OR REPLACE FUNCTION public.validate_snapshot_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path = public, pg_temp
    AS $$
DECLARE
    v_snap    public.invoice_calculation_snapshots%ROWTYPE;
    v_status  text;
    v_visible boolean;
BEGIN
    SELECT * INTO v_snap FROM public.invoice_calculation_snapshots s WHERE s.id = NEW.snapshot_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot reference rejected: snapshot %s not found (or not visible to this tenant)', NEW.snapshot_id),
            ERRCODE = 'foreign_key_violation';
    END IF;
    IF v_snap.tenant_id <> NEW.tenant_id THEN
        RAISE EXCEPTION USING
            MESSAGE = 'snapshot reference rejected: tenant_id must equal the snapshot''s tenant',
            ERRCODE = 'check_violation';
    END IF;
    SELECT i.status INTO v_status FROM public.invoices i WHERE i.id = v_snap.invoice_id FOR SHARE;
    IF FOUND AND public.is_invoice_issued(v_status) THEN
        RAISE EXCEPTION USING
            MESSAGE = 'snapshot reference rejected: the invoice is issued and its snapshot is frozen (CI-015)',
            ERRCODE = 'check_violation';
    END IF;
    -- The cited row must have been OPEN on the transaction-time axis at the
    -- snapshot's recorded_at, in the same tenant (every citable table carries
    -- recorded_at / recorded_until). The table name is re-checked here
    -- because this BEFORE trigger runs before the CHECK constraint would.
    IF NEW.source_table <> ALL (ARRAY['rate_schedule_versions', 'wna_zone_versions', 'rate_item_versions',
                                      'rate_schedule_items', 'franchise_fee_rules', 'customer_tax_exemptions', 'wna_monthly_adjustments',
                                      'regulatory_surcharge_rules']) THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot reference rejected: %L is not one of the eight bi-temporal reference tables (invoice_snapshot_references_source_table_check)', NEW.source_table),
            ERRCODE = 'check_violation';
    END IF;
    EXECUTE format(
        'SELECT EXISTS (SELECT 1 FROM public.%I r WHERE r.id = $1 AND r.tenant_id = $2 AND r.recorded_at IS NOT NULL AND r.recorded_at <= $3 AND (r.recorded_until IS NULL OR r.recorded_until > $3))',
        NEW.source_table)
    INTO v_visible
    USING NEW.source_row_id, NEW.tenant_id, v_snap.recorded_at;
    IF NOT v_visible THEN
        RAISE EXCEPTION USING
            MESSAGE = format('snapshot reference rejected: %s row %s was not an open assertion at recorded_at %s in this tenant — the run could not have read it at that coordinate (AC-15 / CI-003)', NEW.source_table, NEW.source_row_id, v_snap.recorded_at),
            ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.validate_snapshot_reference() IS
    'A-3 (v5.4.2-04; re-issued v5.4.2-07 to admit regulatory_surcharge_rules — body otherwise unchanged): BEFORE INSERT on invoice_snapshot_references — the snapshot exists in this tenant and its invoice is not issued; source_table is one of the eight bi-temporal tables; the cited row was an open assertion at the snapshot''s recorded_at in the same tenant.';

COMMENT ON TABLE public.invoice_snapshot_references IS
    'Provenance for a calculation snapshot (v5.4.2-04, A-3 → A-1; A-7 adds regulatory_surcharge_rules): each row cites one bi-temporal row the calculation read (source_table ∈ the seven A-1 tables + regulatory_surcharge_rules). The guard proves the citation was visible at the snapshot''s recorded_at (open on the transaction-time axis at that instant, same tenant). "Which rows did this bill use, and were they really what we knew then?" is answerable from this table; the values themselves are in the snapshot sections. Optional per snapshot; same immutability as the snapshot.';

-- ----------------------------------------------------------------------------
-- 7. The compliance report's billed side
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.regulatory_surcharge_billing_summary WITH (security_invoker = true) AS
SELECT r.id                    AS rule_id,
       r.tenant_id,
       r.rate_item_id,
       ri.item_code,
       r.surcharge_kind,
       r.cycle_start,
       r.cycle_end,
       r.cap_per_service,
       r.regulatory_reference,
       r.tariff_filing_reference,
       coalesce(b.services_billed, 0)   AS services_billed,
       coalesce(b.lines_billed, 0)      AS lines_billed,
       coalesce(b.total_billed, 0)      AS total_billed,
       b.first_billed_on,
       b.last_billed_on,
       b.unit_rates_billed,
       coalesce(b.pending_in_drafts, 0) AS pending_in_drafts
  FROM public.regulatory_surcharge_rules r
  JOIN public.rate_items ri ON ri.id = r.rate_item_id
  LEFT JOIN LATERAL (
        SELECT count(DISTINCT l.meter_id) FILTER (WHERE public.is_invoice_issued(i.status)) AS services_billed,
               count(l.id)                FILTER (WHERE public.is_invoice_issued(i.status)) AS lines_billed,
               sum(l.amount)              FILTER (WHERE public.is_invoice_issued(i.status)) AS total_billed,
               min(i.invoice_date)        FILTER (WHERE public.is_invoice_issued(i.status)) AS first_billed_on,
               max(i.invoice_date)        FILTER (WHERE public.is_invoice_issued(i.status)) AS last_billed_on,
               array_agg(DISTINCT l.rate) FILTER (WHERE public.is_invoice_issued(i.status) AND l.rate IS NOT NULL) AS unit_rates_billed,
               sum(l.amount)              FILTER (WHERE NOT public.is_invoice_issued(i.status)) AS pending_in_drafts
          FROM public.invoice_line_items l
          JOIN public.invoices i ON i.id = l.invoice_id
         WHERE l.tenant_id = r.tenant_id
           AND l.rate_item_id = r.rate_item_id
           AND i.status <> 'void'
           AND i.invoice_date >= r.cycle_start AND i.invoice_date <= r.cycle_end
  ) b ON true
 WHERE r.recorded_until IS NULL;

COMMENT ON VIEW public.regulatory_surcharge_billing_summary IS
    'CI-038 (v5.4.2-07, A-7): the billed side of the 16 TAC §8.201 compliance report (due 90 days after the last billing cycle carrying the surcharge), per open rule / cycle: services billed (distinct meters), lines, total billed and first / last bill date on issued non-void invoices, the distinct unit rates billed, and the amount still in draft / held invoices. NOT here: the amount paid to RRC and the amount COLLECTED from customers — payments are not allocated per line — both are the application''s / the tenant''s accounting. A report, not an exception list: after a cap correction it shows what was billed under the earlier assertion without flagging it. security_invoker: RLS applies.';

-- ----------------------------------------------------------------------------
-- 8. Pre-patch bills: report, never rewrite
-- ----------------------------------------------------------------------------
DO $$
DECLARE v integer;
BEGIN
    SELECT count(DISTINCT i.id) INTO v
      FROM public.invoices i
      JOIN public.invoice_line_items l ON l.invoice_id = i.id
     WHERE public.is_invoice_issued(i.status) AND i.status <> 'void'
       AND l.amount <> 0 AND l.charge_type = 'tax'
       AND NOT EXISTS (SELECT 1 FROM public.invoice_line_item_bases b WHERE b.line_item_id = l.id);
    IF v > 0 THEN
        RAISE NOTICE 'v5.4.2-07: % issued invoice(s) carry non-zero tax lines with no base composition (pre-patch bills; their lines are frozen and no composition can be written for them — CI-045 holds from this patch forward)', v;
    END IF;
END;
$$;

-- ----------------------------------------------------------------------------
-- 9. ENABLE ALWAYS on every guard this patch created (D-2026-08-20-27)
-- ----------------------------------------------------------------------------
DO $$
DECLARE r record;
BEGIN
    FOR r IN
        SELECT c.relname, t.tgname
        FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' AND NOT t.tgisinternal AND t.tgenabled <> 'A'
          AND (
                (c.relname = 'regulatory_surcharge_rules' AND t.tgname IN ('a_enforce_bitemporal_assertion', 'b_enforce_regulatory_surcharge_rule', 'enforce_superseded_has_successor', 'no_truncate'))
             OR (c.relname IN ('rate_item_versions', 'rate_schedule_items') AND t.tgname = 'b_enforce_surcharge_rider_not_taxable')
             OR (c.relname = 'invoice_line_item_bases' AND t.tgname IN ('enforce_invoice_line_item_base', 'no_truncate'))
             OR (c.relname = 'invoice_line_items' AND t.tgname = 'z_enforce_surcharge_line')
             OR (c.relname = 'invoices' AND t.tgname = 'enforce_invoice_surcharge_lines_and_bases')
             OR (c.relname IN ('customer_state_events', 'customer_attribute_history') AND t.tgname = 'a_enforce_event_written_by_db')
          )
    LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER %I', r.relname, r.tgname);
    END LOOP;
END;
$$;

-- ----------------------------------------------------------------------------
-- 10. Cross-references on existing objects
-- ----------------------------------------------------------------------------
COMMENT ON COLUMN public.invoice_line_items.is_taxable IS 'Whether this line enters the taxable base (resolved by the engine from the rider''s is_taxable_default / is_taxable_override, #23 stage 2). Since v5.4.2-07 a line of a rider excluded_from_tax_bases (regulatory_surcharge_rules) must be false; the base each tax / percentage line was actually computed on is materialized in invoice_line_item_bases (CI-045).';
COMMENT ON COLUMN public.invoice_line_items.taxable_amount IS 'The part of this line''s amount that is taxable, when not the whole line. Must be empty / 0 on a line of a rider excluded from tax bases (v5.4.2-07, CI-038).';
COMMENT ON COLUMN public.invoice_line_items.meter_id IS 'The meter (service line) this line bills. Required on a line of a rider capped per service (regulatory_surcharge_rules.cap_per_service, v5.4.2-07): the cap aggregates by (rate item, meter) over the cycle.';
COMMENT ON COLUMN public.franchise_fee_rules.applies_to IS 'Which composition the franchise-fee base uses (total_bill | gross_revenue | base_and_usage | usage_only). Open with Kyle (decision table #26, question 2) how this relates to the per-item is_taxable chain; whichever governs, the base actually used on each bill is written to invoice_line_item_bases (v5.4.2-07) and a PSF / excluded-surcharge line can never be in it (CI-038).';
COMMENT ON COLUMN public.rate_item_versions.is_taxable_default IS 'Default taxability of the rider''s lines (overridable per schedule). A rider with an open regulatory_surcharge_rules row excluded_from_tax_bases can never assert true here (v5.4.2-07). The false DEFAULT is decision table #23''s open question 1 (Kyle): the schema cannot tell "decided false" from "never decided".';
